window.CP_ITEMS=window.CP_ITEMS||{};window.CP_ITEMS["植物"]=[{"uid":"ad596df7-559f-4f97-81d3-7cba94b371c5","title":"杂曲歌辞 相府莲","author":"不详","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["夜闻邻妇泣，切切有余哀。","即问缘何事，征人战未回。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["夜"],"cats":{"人生":["战争"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"ecec8663-2b01-4419-9fdd-9627999cac71","title":"奉和陆鲁望白菊","author":"郑璧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["白艳轻明带露痕，始知佳色重难群。","终朝疑笑梁王雪，尽日慵飞蜀帝魂。","燕雨似翻瑶渚浪，雁风疑卷玉绡纹。","琼妃若会宽裁剪，堪作蟾宫夜舞裙。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","鸟","重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"cpa864df177f8250","title":"暗香","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["旧时月色。","算几番照我，梅边吹笛。","唤起玉人，不管清寒与攀摘。","何逊而今渐老，都忘却、春风词笔。","但怪得、竹外疏花，香冷入瑶席。","江国。","正寂寂。","叹寄与路遥，夜雪初积。","翠尊易泣。","红萼无言耿相忆。","长记曾携手处，千树压、西湖寒碧。","又片片、吹尽也，几时见得。"],"theme":"爱情相思","theme2":["送别"],"style":"幽峭","style2":["绮丽","婉约"],"mood":"孤寂","mood2":["悲怆"],"scene":["花","月"],"cats":{"山水":["西湖"],"天气":["月亮"],"植物":["梅花"]},"theme_conf":0.604},{"uid":"1f411fea-83c6-4e86-aadb-3e0fd0827366","title":"落叶送陈羽","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落叶不更息，断蓬无复归。","飘飖终自异，邂逅暂相依。","悄悄深夜语，悠悠寒月辉。","谁云少年别，流泪各沾衣。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["思乡","伤感"],"植物":["叶子"]},"theme_conf":0.562},{"uid":"44e15dd3-3621-46ff-be2a-145555ed2593","title":"城西竹园送裴佶王达","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["葳蕤凌风竹，寂寞离人觞。","怆怀非外至，沈郁自中肠。","远行从此始，别袂重凄霜。"],"theme":"送别","theme2":[],"style":"旷达","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨"],"scene":["园林","酒"],"cats":{"抒情":["离别","孤独"],"植物":["竹子"]},"theme_conf":0.809},{"uid":"8e8e6eed-cb19-49b2-979a-ec1d3a0e3729","title":"萧宅二三子赠答诗二十首 竹请客","author":"卢仝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["我本泰山阿，避地到南国。","主人欲移家，我亦要归北。","上客幸先归，愿托归飞翼。","唯将翛翛风，累路报恩德。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"山水":["泰山"],"植物":["竹子"]},"theme_conf":0.9},{"uid":"ea100f9a-3504-4a7d-844c-c23ba23f364b","title":"将适吴楚留别章使君留后兼幕府诸公得柳字","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我来入蜀门，岁月亦已久。","岂惟长儿童，自觉成老丑。","常恐性坦率，失身为杯酒。","近辞痛饮徒，折节万夫后。","昔如纵壑鱼，今如丧家狗。","既无游方恋，行止复何有。","相逢半新故，取别随薄厚。","不意青草湖，扁舟落吾手。","眷眷章梓州，开筵俯高柳。","楼前出骑马，帐下罗宾友。","健儿簸红旗，此乐或难朽。","日车隐昆仑，鸟雀噪户牖。","波涛未足畏，三峡徒雷吼。","所忧盗贼多，重见衣冠走。","中原消息断，黄屋今安否。","终作适荆蛮，安排用庄叟。","随云拜东皇，挂席上南斗。","有使即寄书，无使长回首。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","酒","江南"],"cats":{"抒情":["离别"],"人物":["儿童"],"植物":["柳树"]},"theme_conf":0.715},{"uid":"a5d27c21-7045-4e33-8a1e-f50862de0e25","title":"寄天台叶尊师","author":"王贞白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["师住天台久，长闻过石桥。","晴峰见沧海，深洞彻丹霄。","采药霞衣湿，煎芝古鼎焦。","念予无俗骨，频与鹤书招。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["楼"],"cats":{"生活":["写桥"],"植物":["叶子"]},"theme_conf":0.88},{"uid":"5aee2c13-785a-4735-8a13-069d126a37f6","title":"相和歌辞 采莲曲二首 一","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["弄舟朅来南塘水，荷叶映身摘莲子。","暑衣清净鸳鸯喜，作浪舞花惊不起。","殷勤护惜纤纤指，水菱初熟多新刺。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","舟"],"cats":{"抒情":["爱情"],"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.527},{"uid":"bb93206b-92a8-4440-aeb5-4cc3bbe596ea","title":"送僧方及南谒柳员外","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔事庐山远，精舍虎溪东。","朝阳照瀑水，楼阁虹霓中。","骋望羡游云，振衣若秋蓬。","旧房闭松月，远思吟江风。","古寺历头陀，奇峰扳祝融。","南登小桂岭，却望归塞鸿。","衣裓贮文章，自言学雕虫。","抢榆念陵厉，覆篑图穹崇。","远郡多暇日，有诗访禅宫。","石门耸峭绝，竹院含空蒙。","幽响滴岩溜，晴芳飘野丛。","海云悬飓母，山果属狙公。","忽忆吴兴郡，白苹正葱茏。","愿言挹风采，邈若窥华嵩。","桂水夏澜急，火山宵焰红。","三衣濡菌露，一锡飞烟空。","勿谓翻译徒，不为文雅雄。","古来赏音者，燋爨得孤桐。"],"theme":"送别","theme2":["哲理悟道","送别"],"style":"幽峭","style2":["冲淡"],"mood":"相思","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["思念","孤独"],"山水":["庐山"],"天气":["彩虹","太阳"],"人生":["哲理"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"d3a24e9a-b734-4259-819a-f7dd4cf06a76","title":"白菊三首 一","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["人间万恨已难平，栽得垂[杨]更系情。","犹喜闰前霜未下，菊边依旧舞身轻。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.86},{"uid":"ba17fece-e517-4da1-8ff2-f42bf2bacb18","title":"莲叶","author":"郑谷","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["移舟水溅差差绿，倚槛风摇柄柄香。","多谢浣溪人不折，雨中留得盖鸳鸯。"],"theme":"咏物","theme2":["山水田园","爱情相思"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","雨"],"cats":{"抒情":["爱情"],"植物":["荷花","叶子"]},"theme_conf":0.427},{"uid":"00ede8d1-4ba1-4b59-9021-bddf471b00e4","title":"早春思归有唱竹枝歌者坐中下泪","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["渺渺春生楚水波，楚人齐唱竹枝歌。","与君皆是思归客，拭泪看花奈老何。"],"theme":"羁旅思乡","theme2":["题画咏艺"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.402},{"uid":"c8284ada-18a4-46ad-8a47-c2b0c02204ff","title":"过柳州","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["地尽江南戍，山分桂北林。","火云三月合，石路九疑深。","暗谷随风过，危桥共鸟寻。","羁魂愁似绝，不复待猨吟。"],"theme":"羁旅思乡","theme2":["山水田园","边塞征战","羁旅思乡"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":["月","江南","江","山"],"cats":{"抒情":["思乡","伤感"],"生活":["写桥"],"植物":["柳树"]},"theme_conf":0.93},{"uid":"6c18667b-708f-4a2a-9c20-d4a104e36904","title":"春雪题兴善寺广宣上人竹院","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["皎洁青莲客，焚香对雪朝。","竹风催淅沥，花雨让飘飖。","触石和云积，萦池拂水消。","只应将日月，颜色不相饶。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","园林","春"],"cats":{"四季":["春天"],"天气":["写雪"],"植物":["竹子"]},"theme_conf":0.535},{"uid":"bc8adf47-d6ff-46f9-99a3-ee2833e075b7","title":"杂曲歌辞 昔昔盐 花飞桃李蹊","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["远期难可托，桃李自依依。","花径无容迹，戎裘未下机。","随风开又落，度日扫还飞。","欲折枝枝赠，那知归不归。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"人物":["老师"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"ef3c51b2-f0a5-4d9b-8ae3-2a24b342ddee","title":"新乐府 隋堤柳\t悯亡国也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["隋堤柳，岁久年深尽衰朽。","风飘飘兮雨萧萧，三株两株汴河口。","老枝病叶愁杀人，曾经大业年中春。","大业年中炀天子，种柳成行夹流水。","西自黄河东至淮，绿阴一千三百里。","大业末年春暮月，柳色如烟絮如雪。","南幸江都恣佚游，应将此柳系龙舟。","紫髯郎将护锦缆，青娥御史直迷楼。","海内财力此时竭，舟中歌笑何日休。","上荒下困势不久，宗社之危如缀旒。","炀天子，自言福祚长无穷，岂知皇子封酅公。","龙舟未过彭城合，义旗已入长安宫。","萧墙祸生人事变，晏驾不得归秦中。","土坟数尺何处葬，吴公台下多悲风。","二百年来汴河路，沙草和烟朝复暮。","后王何以鉴前王，请看隋堤亡国树。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["江","端午","楼","舟","春"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"山水":["黄河"],"节日":["端午节"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"ef4d4ca2-59ea-4c84-b360-b63252700998","title":"同吉中孚梦桃源 一","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["春雨夜不散，梦中山亦阴。","云中碧潭水，路暗红花林。","花水自深浅，无人知古今。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["花","春","雨","夜","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"人生":["梦想"],"植物":["桃花"]},"theme_conf":0.784},{"uid":"e387aad0-cefb-4e70-b299-855d181a36ab","title":"零陵赠李卿元侍御简吴武陵","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["理世固轻士，弃捐湘之湄。","阳光竞四溟，敲石安所施。","铩羽集枯干，低昂互鸣悲。","朔云吐风寒，寂历穷秋时。","君子尚容与，小人守兢危。","惨凄日相视，离忧坐自滋。","尊酒聊可酌，放歌谅徒为。","惜无协律者，窈眇弦吾诗。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["幽峭","悲慨"],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["酒","江南"],"cats":{"抒情":["伤感"],"植物":["桃花"]},"theme_conf":0.93},{"uid":"16dbc4d3-1930-4f57-8d30-c358ec7ba315","title":"闻吹杨叶者二首 一","author":"郎士元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["妙吹杨叶动悲笳，胡马迎风起恨赊。","若是鴈门寒月夜，此时应卷尽惊沙。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["月","夜"],"cats":{"抒情":["伤感"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"4a4822fe-71f9-448f-923f-ea4061d09e2f","title":"相和歌辞 采莲曲二首 二","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["采莲朅来水无风，莲潭如镜松如龙。","夏衫短袖交斜红，艳歌笑鬬新芙蓉，戏鱼住听莲花东。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","花"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"4e89e730-74b8-4924-ae06-0d2f259c03be","title":"赠罗浮易炼师","author":"杨衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["海上多仙峤，灵人信长生。","荣卫冰雪姿，咽嚼日月精。","默书绛符遍，晦步斗文成。","翠发披肩长，金盖凌风轻。","晓籁息尘响，天鸡叱幽声。","碧树来户阴，丹霞照窗明。","焚香叩虚寂，稽首回太清。","鸾鹭振羽仪，飞翻拂斾旌。","左挹玉泉液，右搴云芝英。","念得参龙驾，攀天度赤城。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["冬","雪","月"],"cats":{"天气":["写雪"],"植物":["梅花"]},"theme_conf":0.88},{"uid":"7f86f129-519b-46fd-a95f-b9f1f29c352d","title":"友人山中梅花","author":"殷尧藩","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["南国看花动远情，沈郎诗苦瘦容生。","铁心自儗山中赋，玉笛谁将月下横。","临水一枝春占早，照人千树雪同清。","好风吹醒罗浮梦，莫听空林翠羽声。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山","花","冬"],"cats":{"抒情":["友情"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"c85a05da-3863-4ff6-8ec4-4fc9f32be0ea","title":"岳州看黄叶","author":"张说","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["白首看黄叶，徂颜复几何。","空慙棠树下，不见政成歌。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"植物":["叶子"]},"theme_conf":0.84},{"uid":"935306d8-d08d-41f7-b8f0-cad379229322","title":"采莲曲","author":"李康成","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["采莲去，月没春江曙。","翠钿红袖水中央，青荷莲子杂衣香，云起风生归路长。","归路长，那得久。","各回船，两摇手。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春","月","花","舟","江"],"cats":{"四季":["春天"],"植物":["荷花"]},"theme_conf":0.699},{"uid":"a9f0993f-d2b7-4b8e-a8dc-ad05daacf472","title":"崔十四宅各赋一物得簷柳","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["官渡老风烟，浔阳媚云日。","汉将营前见，胡笳曲中出。","复在此簷端，垂阴仲长室。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"植物":["柳树"]},"theme_conf":1.0},{"uid":"c0b9984d-eb82-4994-9aeb-dd578cf8b3c1","title":"和钱员外早冬玩禁中新菊","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["禁署寒气迟，孟冬菊初坼。","新黄间繁绿，烂若金照碧。","仙郎小隐日，心似陶彭泽。","秋怜潭上看，日惯篱边摘。","今来此地赏，野意潜自适。","金马门内花，玉山峰下客。","寒芳引清句，吟玩烟景夕。","赐酒色偏宜，握兰香不敌。","凄凄百卉死，岁晚冰霜积。","唯有此花开，殷勤助君惜。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":["冬"],"cats":{"四季":["秋天","冬天"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"82c60214-4e01-4141-9673-b131fa6978b2","title":"国子柳博士兼领太常博士輙申贺赠","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["博士本秦官，求才帖职难。","临风曲台净，对月碧池寒。","讲学分阴重，斋祠晓漏残。","朝衣辨色处，双绶更宜看。"],"theme":"应制干谒","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","月"],"cats":{"植物":["柳树"]},"theme_conf":0.9},{"uid":"8f3bd134-ac28-4961-b0c9-141140f72e47","title":"横吹曲辞 折杨柳 二","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楼上春风过，风前杨柳歌。","枝疎缘别苦，曲怨为年多。","花惊燕地雪，叶映楚池波。","谁堪别离此，征戍在交河。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["雪","春","楼"],"cats":{"抒情":["离别"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.664},{"uid":"d71a5667-a683-40ec-bb82-94373c508595","title":"春日咏梅花二首 二","author":"王初","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["青帝来时值远芳，残花残雪尚交光。","隔年拟待春消息，得见春风已断肠。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"cd904f43-b9eb-4e30-a3fe-f2bcb215a8db","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 二","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红似燕支腻如粉，伤心好物不须臾。","山中风起无时节，明日重来得在无。"],"theme":"山水田园","theme2":["咏物"],"style":"绮丽","style2":["清新","婉约"],"mood":"孤寂","mood2":[],"scene":["月","花","山","冬","夏"],"cats":{"抒情":["孤独","感恩"],"四季":["夏天","冬天"],"天气":["太阳","月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.446},{"uid":"b53c554d-abd0-4532-84d2-529d14fdebce","title":"从韦二明府续处觅绵竹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["华轩蔼蔼他年到，绵竹亭亭出县高。","江上舍前无此物，幸分苍翠拂波涛。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","江"],"cats":{"植物":["竹子"]},"theme_conf":1.0},{"uid":"ff17b57b-4f6b-4190-93b4-72829ac0e3d3","title":"白菊杂书四首 一","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄昏寒立更披襟，露浥清香悦道心。","却笑谁家扃绣户，正薰龙麝暖鸳衾。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["夜","重阳"],"cats":{"抒情":["闺怨"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"1558a170-9f05-4a1a-b907-b9f6061f4772","title":"饯济阴梁明府各探一物得荷叶","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["荷叶生幽渚，芳华信在兹。","朝朝空此地，采采欲因谁。","但恐星霜改，还将蒲稗衰。","怀君美人别，聊以赠心期。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"人物":["女子"],"人生":["青春"],"植物":["荷花","叶子"]},"theme_conf":0.799},{"uid":"7b1fdef6-f900-4fbc-8542-43c3cdd6eab7","title":"九日奉陪令公登白楼同咏菊","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["琼尊犹有菊，可以献留侯。","愿比三花秀，非同百卉秋。","金英分蘂细，玉露结房稠。","黄雀知恩在，衔飞亦上楼。"],"theme":"应制干谒","theme2":["咏物","咏史怀古"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","楼"],"cats":{"抒情":["怀古"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.78},{"uid":"efce77ad-b87b-4f3f-a33f-5732adb9440e","title":"相和歌辞 采莲曲三首 三","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["越女作桂舟，还将桂为檝。","湖上水渺漫，清江初可涉。","摘取芙蓉花，莫摘芙蓉叶。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["江","舟"],"cats":{"植物":["荷花"]},"theme_conf":1.0},{"uid":"71d9f2b6-dfd3-4ee9-8e0e-cbd31c2829e0","title":"黄菊湾","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["时菊凝晓露，露华滴秋湾。","仙人酿酒熟，醉里飞空山。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"清新","style2":["豪放"],"mood":"恬淡","mood2":[],"scene":["酒","重阳","秋"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.562},{"uid":"d9dd3520-9aab-4b1b-bd57-810f29391667","title":"江州重别薛六柳八二员外","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["生涯岂料承优诏，世事空知学醉歌。","江上月明胡鴈过，淮南木落楚山多。","寄身且喜沧洲近，顾影无如白发何。","今日龙钟人共弃，媿君犹遣慎风波。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["离别"],"山水":["江河"],"植物":["柳树"]},"theme_conf":0.863},{"uid":"66d08e7c-5949-4f75-a9bf-6fa8f16392c9","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 翡翠坞","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["翡翠飞飞绕莲坞，一啄嘉鱼一鸣舞。","莲茎触散莲叶欹，露滴珠光似还浦。","虞人掠水轻浮弋，翡翠惊飞飞不息。","直上层空翠影高，还向云间双比翼。","弹射莫及弋不得，日暮虞人空叹息。"],"theme":"咏史怀古","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["冬"],"cats":{"抒情":["爱情","怀古"],"植物":["梅花"]},"theme_conf":0.565},{"uid":"e09998e4-ec09-4118-ac1b-92f7b53b2f7c","title":"寄武陵李少府","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["小县春山口，公孙吏隐时。","楚歌催晚醉，蛮语入新诗。","桂水遥相忆，花源暗有期。","郢门千里外，莫怪尺书迟。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["春","山","酒"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.96},{"uid":"0bec6ec5-bac0-4fc3-9c26-c1ef63cd1d0a","title":"题苗员外竹间亭","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高甃绝行尘，开帘似有春。","风倾竹上雪，山对酒边人。","步暖先逢日，书空远见邻。","还同内斋暇，登赏及诸姻。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","雪","春","酒","山"],"cats":{"四季":["春天"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"496955eb-549a-4176-84d3-ab6460eaa70f","title":"桃花","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["桃花浅深处，似匀深浅妆。","春风助肠断，吹落白衣裳。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.516},{"uid":"a6718251-5934-4db9-ae50-edf26f8b0ea8","title":"对菊","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["九日不出门，十日见黄菊。","灼灼尚繁英，美人无消息。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"人物":["女子"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"599ff2eb-7a17-414b-bae8-6b537724eec2","title":"巽公院五咏 芙蓉亭","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["新亭俯朱槛，嘉木开芙蓉。","清香晨风远，溽彩寒露浓。","潇洒出人世，低昂多异容。","尝闻色空喻，造物谁为工。","留连秋月晏，迢递来山钟。"],"theme":"咏物","theme2":["节令风俗"],"style":"清新","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["园林","楼"],"cats":{"植物":["荷花"]},"theme_conf":0.601},{"uid":"7e808dee-54f9-428c-a303-71ea2ee91df5","title":"听崔莒侍御叶家歌","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宛罗重縠起歌筵，活凤生花动碧烟。","一声唱断无人和，触破秋云直上天。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.65},{"uid":"70580fb2-022f-4fea-9944-776f5637d835","title":"和韦开州盛山十二首 桃坞","author":"张籍","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["春坞桃花发，多将野客游。","日西殊未散，看望酒缸头。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","酒"],"cats":{"四季":["春天"],"植物":["桃花"]},"theme_conf":0.515},{"uid":"0254bcd5-b7b9-43c3-9a6c-b2a8f8aba5a1","title":"送最澄阇梨还日本诗","author":"陆质","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["海东国主尊台教，遣僧来听《妙法华》。","归来香风满衣裓，讲堂日出映朝霞。","（见日本比睿山无量院沙门慈本〖一七九四--一八六八〗在文久二年〖一八六二〗撰《天台霞标》第四篇第一卷。","转录自《中国哲学史研究》一九八五年第一期刊日本户崎哲彦撰《留传日本的有关陆质的史料及若干考证》。","此篇承束景南先生告知。","）（按：慈本于诗下注云：「此诗未知出于何书。","慈本获之希烈宿称钞书中也。","原本海作汝，妙作于，慈本依义改之。","或曰：此诗载在《禅宗日工集》，又改数字载之《本朝高僧传》某传也。","」户崎氏考证此诗又见于《空华老师日用工夫略集》卷一，第二句作「故遣僧来听《法华》」。","约在公元一三○○年前后即传为陆质诗。","但吴𫖮等九人送最澄诗，皆为五言律诗，唯此首为七言古绝，「因此，该诗疑为后人假托之作，或以意采录。","」）。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"天气":["太阳"],"植物":["梨花"]},"theme_conf":0.659},{"uid":"253ad6ba-185c-4915-9b9a-95e2d1a4515a","title":"梅花二首 二","author":"王初","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["迎春雪艳飘零极，度夕蟾华掩映多。","欲托清香传远信，一枝无计奈愁何。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["花","冬","雪","春"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["梅花"]},"theme_conf":0.98},{"uid":"ef63c450-f64a-4b8b-8284-78685e90601d","title":"白菊杂书四首 四","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄鹂啭处谁同听，白菊开时且剩过。","漫道南朝足流品，由来叔宝不宜多。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳"],"cats":{"抒情":["怀古"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.72},{"uid":"d8eb4cff-a052-4634-bb6a-1285a0f124fe","title":"元日恩赐柏叶应制","author":"李乂","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["劲节凌冬劲，芳心待岁芳。","能令人益寿，非止麝含香。"],"theme":"应制干谒","theme2":["节令风俗"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","冬"],"cats":{"四季":["冬天"],"节日":["春节"],"植物":["叶子"]},"theme_conf":0.94},{"uid":"b4ab0057-6846-46fc-afce-1d641980509f","title":"吊江南老家人春梅","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["念尔筋力尽，违我衣食恩。","奈何粗犷儿，生鞭见死痕。","旧使常以礼，新怨将谁吞。","胡为乎泥中，消歇教义源。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆","惆怅"],"scene":["江南","春","江"],"cats":{"抒情":["怀古"],"四季":["春天"],"植物":["梅花"]},"theme_conf":0.606},{"uid":"bc6d74a4-9808-4fed-8678-d1ea19674690","title":"酬李判官度梨岭见寄","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["陇首怨西征，岭南雁北顾。","行人与流水，共向闽中去。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"植物":["梨花"]},"theme_conf":0.88},{"uid":"a5301061-dc9b-4a5b-b5ec-55cb5c2feb65","title":"晋公魏国夫人柳氏挽歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["鱼轩海上遥，鸾影月中销。","双剑来时合，孤桐去日凋。","夕阳迷陇隧，秋雨咽笳箫。","画翣无留影，铭旌已度桥。"],"theme":"悼亡挽歌","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","月","雨"],"cats":{"抒情":["孤独","悼亡"],"四季":["秋天"],"生活":["写桥"],"植物":["柳树"]},"theme_conf":0.99},{"uid":"30bc1cb8-87e0-45f3-b373-b743251ebcb3","title":"赠天台叶尊师","author":"方干","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莫见平明离少室，须知薄暮入天台。","常时爱缩山川去，有夜自携星月来。","灵药不知何代得，古松应是长年栽。","先生暗笑看棋者，半局棋边白发催。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["楼"],"cats":{"植物":["叶子"]},"theme_conf":0.8},{"uid":"746089bc-7a9d-46f1-8ff4-7636f0403347","title":"桃源图","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["神僊有无何渺茫，桃源之说诚荒唐。","流水盘回山百转，生绡数幅垂中堂。","武陵太守好事者，题封远寄南宫下。","南宫先生忻得之，波涛入笔驱文辞。","文工画妙各臻极，异境恍惚移于斯。","架岩凿谷开宫室，接屋连墙千万日。","嬴颠刘蹶了不闻，地坼天分非所恤。","种桃处处惟开花，川原近远蒸红霞。","初来犹自念乡邑，岁久此地还成家。","渔舟之子来何所，物色相猜更问语。","大蛇中断丧前王，群马南渡开新主。","听终辞绝共凄然，自说经今六百年。","当时万事皆眼见，不知几许犹流传。","争持酒食来相馈，礼数不同樽俎异。","月明伴宿玉堂空，骨冷魂清无梦寐。","夜半金鸡啁哳鸣，火轮飞出客心惊。","人间有累不可住，依然离别难为情。","船开櫂进一回顾，万里苍苍烟水暮。","世俗宁知伪与真，至今传者武陵人。"],"theme":"题画咏艺","theme2":["山水田园","送别"],"style":"豪放","style2":["绮丽","清新"],"mood":"欢愉","mood2":[],"scene":["酒","舟","山","夜"],"cats":{"抒情":["离别"],"植物":["桃花"]},"theme_conf":0.301},{"uid":"88ec78ff-b1f5-4176-aa01-60bd10186362","title":"竹","author":"张南史","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["竹，竹。","披山，连谷。","出东南，殊草木。","叶细枝动，霜停露宿。","成林处处云，抽笋年年玉。","天风乍起争韵，池水相涵更绿。","却寻庾信小园中，闲对数竿心自足。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["园林"],"cats":{"植物":["竹子"]},"theme_conf":0.595},{"uid":"6d1ee060-5750-4c9b-8c75-6080912cbe17","title":"野菊","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["晚艳出荒篱，冷香著秋水。","忆向山中见，伴蛩石壁里。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":["相思"],"scene":["重阳","秋","山"],"cats":{"抒情":["思念"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.579},{"uid":"96314951-671b-423f-a172-4f10ec08a6f2","title":"初秋夜坐赠吴武陵","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["稍稍雨侵竹，翻翻鹊惊丛。","美人隔湘浦，一夕生秋风。","积雾杳难极，沧波浩无穷。","相思岂云远，即席莫与同。","若人抱奇音，朱弦緪枯桐。","清商激西颢，泛滟凌长空。","自得本无作，天成谅非功。","希声閟大朴，聋俗何由聪。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思念"],"四季":["秋天"],"人物":["女子"],"植物":["桃花"]},"theme_conf":0.95},{"uid":"24629e4a-bb7a-49cc-b65d-74e1c4302908","title":"白菊三首 三","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["为报繁霜且莫催，穷秋须到自低垂。","横拖长袖招人别，只待春风却舞来。"],"theme":"送别","theme2":[],"style":"旷达","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","重阳","春"],"cats":{"四季":["春天","秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"7700e970-969a-46bb-9fec-0e29a0d88806","title":"咏新菊","author":"姚合","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["黄金色未足，摘取且尝新。","若待重阳日，何曾异众人。"],"theme":"咏物","theme2":["节令风俗"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.637},{"uid":"7545545f-e9d3-4382-a987-89262e9fd3ae","title":"题金家竹溪","author":"王建","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["少年因病离天仗，乞得归家自养身。","买断竹溪无别主，散分泉水与新邻。","山头鹿下长惊犬，池面鱼行不怕人。","乡使到来常欵语，还闻世上有功臣。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"植物":["竹子"]},"theme_conf":0.473},{"uid":"2571f14e-0c02-4fa0-a52c-f3b75069e0b6","title":"赋得路傍一株柳送邢校书赴延州使府","author":"李益","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["路傍一株柳，此路向延州。","延州在何处，此路起悠悠。"],"theme":"送别","theme2":["咏物"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"植物":["柳树"]},"theme_conf":0.562},{"uid":"011a4a69-9e9a-49f7-8b9d-1eff068143a4","title":"梨花（题拟）","author":"周朴","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["临风千点雪。","（见《全芳备祖前集》卷九《梨花门》）。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"植物":["梨花"]},"theme_conf":1.0},{"uid":"5d5532a1-5286-4ccb-abdc-6118ad48504d","title":"横吹曲辞 折杨柳","author":"乔知之","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["可怜濯濯春杨柳，攀折将来就纤手。","妾容与此同盛衰，何必君恩独能久。"],"theme":"闺情宫怨","theme2":[],"style":"旷达","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"1e77033d-2c4f-4e60-8d42-3b1529f3c93c","title":"横吹曲辞 折杨柳","author":"崔湜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["二月风光半，三边戍不还。","年华妾自惜，杨柳为君攀。","落絮缘衫袖，垂条拂髻鬟。","那堪音信断，流涕望阳关。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月"],"cats":{"抒情":["闺怨"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.415},{"uid":"bc326cee-2472-4d7d-8c4c-97a590a72ade","title":"官渡柳歌送李员外承恩往扬州觐省","author":"独孤及","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见官渡河两岸，三月杨柳枝。","千条万条色，一一胜绿丝。","花作铅粉絮，叶成翠羽帐。","此时送远人，怅望春水上。","远客折杨柳，依依两含情。","夹郎木兰舟，送郎千里行。","郎把紫泥书，东征觐庭闱。","脱却貂襜褕，新著五彩衣。","双凤幷两翅，将雏东南飞。","五两得便风，几日到扬州。","莫贪扬州好，客行剩淹留。","郎到官渡头，春阑已应久。","殷勤道远别，为谢大堤柳。","攀条傥相忆，五里一回首。","明年柳枝黄，问郎还家否。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["春","舟"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.702},{"uid":"efb8e0c4-59ad-4806-9df7-31ce2b642c11","title":"南家桃","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["南家桃树深红色，日照露光看不得。","树小花狂风易吹，一夜风吹满墙北。","离人自有经时别，眼前落花心叹息。","更待明年花满枝，一年迢递空相忆。"],"theme":"送别","theme2":["羁旅思乡","爱情相思"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["夜","花"],"cats":{"抒情":["离别","思念","思乡"],"天气":["写风"],"植物":["桃花"]},"theme_conf":0.374},{"uid":"d3ab98da-082d-4117-98e1-79bc8c2635ed","title":"赋得樱桃","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["华林满芳景，洛阳徧阳春。","朱颜含远日，翠色影长津。","乔柯啭娇鸟，低枝映美人。","昔作园中实，今来席上珍。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"人物":["女子"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"7136e8b6-cec9-423f-89e9-a260eeb32481","title":"春日登陕州城楼俯眺原野回丹碧缀烟霞密翠斑红芳菲花柳即目川岫聊以命篇","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碧原开雾隰，绮岭峻霞城。","烟峰高下翠，日浪浅深明。","斑红粧橤树，圆青压溜荆。","迹岩劳傅想，窥野访莘情。","巨川何以济，舟楫伫时英。"],"theme":"山水田园","theme2":["咏史怀古","山水田园"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","花"],"cats":{"抒情":["怀古"],"四季":["春天"],"天气":["太阳"],"植物":["柳树"]},"theme_conf":0.82},{"uid":"2ec75ddb-6cce-4775-b934-7a7995bc9a04","title":"送柳八员外赴江西","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岐路穷无极，长江九派分。","行人随旅雁，楚树入湘云。","久在征南役，何殊蓟北勋。","离心不可问，岁暮雪纷纷。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江"],"cats":{"山水":["江河","长江"],"植物":["柳树"]},"theme_conf":0.622},{"uid":"d30b4748-72eb-4f1d-b8de-99126216c38c","title":"梅雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南京西浦道，四月熟黄梅。","湛湛长江去，冥冥细雨来。","茅茨疎易湿，云雾密难开。","竟日蛟龙喜，盘涡与岸回。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雨","江"],"cats":{"山水":["长江"],"天气":["写雨"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"9ee9b746-0c42-41af-bd85-630f391f7c59","title":"相和歌辞 采莲曲","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["秋江岸边莲子多，采莲女儿凭船歌。","青房圆实齐戢戢，争前竞折荡漾波。","试牵绿茎下寻藕，断处丝多刺伤手。","白练束腰袖半卷，不插玉钗妆梳浅。","船中未满度前洲，借问谁家家住远。","归时共待暮潮上，自弄芙蓉还荡桨。"],"theme":"爱情相思","theme2":["闺情宫怨"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"抒情":["闺怨"],"植物":["荷花"]},"theme_conf":0.467},{"uid":"56f4eb52-4489-494d-a140-817d264544c8","title":"竹","author":"朱放","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["青林何森然，沈沈独曙前。","出墙同淅沥，开户满婵娟。","箨卷初呈粉，苔侵乱上钱。","疎中思水过，深处若山连。","叠夜常栖露，清朝乍有蝉。","砌阴迎缓策，簷翠对欹眠。","迸笋双分箭，繁梢一向偏。","月过惊散雪，风动极闻泉。","幽谷添诗谱，高人欲制篇。","萧萧意何恨，不独往湘川。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["中秋","雪","夜","月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.757},{"uid":"cp9d526676093b5f","title":"绿意・疏影","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["碧圆自洁。","向浅洲远渚，亭亭清绝。","犹有遗簪，不展秋心，能卷几多炎热。","鸳鸯密语同倾盖，且莫与、浣纱人说。","恐怨歌、忽断花风，碎却翠云千叠。","回首当年汉舞，怕飞去、谩皱留仙裙折。","恋恋青衫，犹染枯香，还叹鬓丝飘雪。","盘心清露如铅水，又一夜、西风吹折。","喜静看、匹练秋光，倒泻半湖明月。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":["冲淡"],"mood":"愁怨","mood2":["欢愉","恬淡"],"scene":["江","秋","月"],"cats":{"抒情":["爱情"],"四季":["秋天"],"天气":["月亮"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"e6bf25ce-19e9-4316-bd35-cdc6bb050c61","title":"奉酬卢给事云夫四兄曲江荷花行见寄幷呈上钱七兄阁老张十八助教","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["曲江千顷秋波净，平铺红云盖明镜。","大明宫中给事归，走马来看立不正。","遗我明珠九十六，寒光映骨睡骊目。","我今官闲得婆娑，问言何处芙蓉多。","撑舟昆明度云锦，脚敲两舷呌吴歌。","太白山高三百里，负雪崔嵬插花里。","玉山前却不复来，曲江汀滢水平杯。","我时相思不觉一回首，天门九扇相当开。","上界真人足官府，岂如散仙鞭笞鸾凤终日相追陪。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江","花","山"],"cats":{"抒情":["思念"],"山水":["江河"],"天气":["写云"],"植物":["荷花"]},"theme_conf":0.95},{"uid":"cee17360-6fa9-4406-9794-394ac59be538","title":"横吹曲辞 梅花落","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["铁骑几时回，金闺怨早梅。","雪中花已落，风暖叶应开。","夕逐新春管，香迎小岁杯。","感时何足贵，书里报轮台。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["花","冬"],"cats":{"抒情":["闺怨"],"植物":["梅花"]},"theme_conf":0.519},{"uid":"98cf143d-0917-47aa-8a24-ce3db79ce765","title":"赋得春雪映早梅","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["飞舞先春雪，因依上番梅。","一枝方渐秀，六出已同开。","积素光逾密，真花节暗催。","抟风飘不散，见𬀪忽偏摧。","郢曲琴空奏，羌音笛自哀。","今朝两成咏，翻挟昔人才。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["雪","冬","春"],"cats":{"四季":["春天"],"天气":["写雪"],"植物":["梅花"]},"theme_conf":0.796},{"uid":"906627d5-30e9-4ed3-adeb-3de852f9be50","title":"幽居有白菊一丛因而成咏呈知己","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["还是延年一种材，即将瑶朵冒霜开。","不如红艳临歌扇，欲伴黄英入酒杯。","陶令接䍠堪岸著，梁王高屋好欹来。","月中若有闲田地，为劝嫦娥作意裁。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["酒","重阳"],"cats":{"抒情":["友情"],"天气":["月亮"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"96a483bc-6822-490e-a891-e13f609af452","title":"奉使采箭簳竹谷中晨兴赴岭","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤客倦夜坐，闻猨乘早发。","背溪已斜汉，登栈尚残月。","重峰转森爽，幽步更超越。","云木耸鹤巢，风萝扫虎穴。","人群从自远，世役终难歇。","入山非买山，采竹异采蕨。","谁见子牟意，悁劳书魏阙。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["孤独"],"植物":["竹子"]},"theme_conf":0.85},{"uid":"245660c4-0496-46cf-a7f5-ad6dfffe8db9","title":"题百叶桃花","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["百叶双桃晚更红，窥窗暎竹见玲珑。","应知侍史归天上，故伴仙郎宿禁中。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"植物":["桃花","叶子"]},"theme_conf":1.0},{"uid":"e283ac05-0ee6-4342-b972-af263c1e2405","title":"尊师是桃源黄先生传法弟子常见尊师称先师灵迹今重赋此诗兼寄题黄先生旧馆","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["后学方成市，吾师又上宾。","洞天应不夜，源树秪如春。","棋客留童子，山精避直神。","无因握石髓，及与养生人。"],"theme":"佛道禅颂","theme2":["送别","咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","夜","山"],"cats":{"四季":["春天"],"人物":["老师"],"植物":["桃花"]},"theme_conf":0.85},{"uid":"12f2af31-9401-4281-a410-55843039d6b1","title":"八月十五日夜桃源玩月","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["尘中见月心亦闲，况是清秋仙府间。","凝光悠悠寒露坠，此时立在最高山。","碧虚无云风不起，山上长松山下水。","群动翛然一顾中，天高地平千万里。","少君引我升玉坛，礼空遥请真仙官。","云𫐌欲下星斗动，天乐一声肌骨寒。","金霞昕昕渐东上，轮欹影促犹频望。","绝景良时难再幷，他年此日应惆怅。"],"theme":"山水田园","theme2":["节令风俗","游仙梦幻"],"style":"绮丽","style2":["豪放","清新"],"mood":"惆怅","mood2":["孤寂","恬淡"],"scene":["月","中秋","夜"],"cats":{"天气":["太阳","月亮"],"节日":["中秋节"],"植物":["桃花"]},"theme_conf":0.377},{"uid":"76d1a527-f7ad-4732-98a1-248d9b64c781","title":"萧八明府隄处觅桃栽","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["奉乞桃栽一百根，春前为送浣花村。","河阳县里虽无数，濯锦江边未满园。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春","江","园林"],"cats":{"四季":["春天"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"18134617-3a61-4d5a-a0c2-3d80b54099f6","title":"步出武陵东亭临江寓望","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["鹰至感风候，霜余变林麓。","孤颿带日来，寒江转沙曲。","戍摇旗影动，津晚橹声促。","月上彩霞收，渔歌远相续。"],"theme":"山水田园","theme2":["咏史怀古","边塞征战"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独","怀古"],"山水":["江河"],"植物":["桃花"]},"theme_conf":0.425},{"uid":"06bcd5bc-f822-48b9-9204-08e3eff83f4d","title":"雨中对后簷丛竹","author":"崔元翰","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["含风摇砚水，带雨拂墙衣。","乍似秋江上，渔家半掩扉。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"601d90fb-3589-44f1-9a25-9e16af2102c3","title":"陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["把烛成桥夜，回舟坐客时。","天高云去尽，江迥月来迟。","衰谢多扶病，招邀屡有期。","异方乘此兴，乐罢不无悲。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":["幽峭","沉郁"],"mood":"欢愉","mood2":["悲怆"],"scene":["江","冬"],"cats":{"抒情":["伤感"],"四季":["冬天"],"山水":["江河"],"生活":["写桥"],"动物":["写马"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"bbe77207-c21e-4f74-9e94-fee4f8cb57fc","title":"相和歌辞 采莲曲","author":"储光羲","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["浅渚荷花繁，深塘菱叶疎。","独往方自得，耻邀淇上姝。","广江无术阡，大泽绝方隅。","浪中海童语，流下鲛人居。","春雁时隐舟，新荷复满湖。","采采乘日暮，不思贤与愚。"],"theme":"爱情相思","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独"],"植物":["荷花"]},"theme_conf":0.534},{"uid":"eaef090a-c731-44fb-8d03-829ed9237e25","title":"柳州罗池庙诗（题拟）","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["荔子丹兮蕉黄（「蕉」下或有「叶」字，或有「子」字），杂肴蔬兮进侯堂。","侯之船兮两旗，度中流兮风泊之，待侯不来兮不知我悲。","侯乘驹兮入庙，慰我民兮不嚬以笑。","鹅之山兮柳之水，桂树团团兮白石齿齿。","侯朝出游兮暮来归，春与猿吟兮秋鹤与飞。","（《唐文粹》及欧阳修所见《韩集》均作「秋与鹤飞」。","《集古录跋尾》卷八录碑文作「秋鹤与飞」，欧疑碑文有误。","沈括《梦溪笔谈》卷十四以为此用《楚辞》相错成文格，今从其说。","）北方之人兮为侯是非，千秋万岁兮侯无我违。","福我兮寿我，驱厉鬼兮山之左。","下无湿兮高无干，秔稌充羡兮蛇蛟结蟠。","我民报事兮无怠其始，自今兮钦于世世。","（同前书卷三一、《唐文粹》卷五二《柳州罗池庙碑》附）（〖1〗《柳州罗池庙碑》云：「三年孟秋辛卯，侯降于州之后堂，欧阳翼等见而拜之。","其夕，梦翼而告之曰：『馆我于罗池。","』其日景辰，庙成，大祭。","过客李仪醉酒，慢侮堂上，得疾，扶出庙门即死。","明年春，魏忠、欧阳翼使谢宁来京师，请书其事于石。","余谓柳侯生能泽其民，死能惊动祸福之，以食其土，可谓灵也已。","作迎享送神诗遗柳民，俾歌以祀焉而幷刻之。","……其词曰〖词略〗。","」《湖南通志·金石》六著录嘉定刻此碑，题作《唐罗池庙享神词碑》，附魏绍芳跋此为享神诗。","《唐诗别裁集》卷七收入。","朱东润师主编《中国历代文学作品选》中编第一册收此诗，题作《柳州罗池庙诗》，解题云：「此庙建成后，韩愈为撰《柳州罗池庙碑》，诗就附在碑文的后面。","诗效《楚辞·九歌》体，作为祭祀中迎神、送神时歌唱之用。","」）。"],"theme":"佛道禅颂","theme2":["咏物","咏史怀古","山水田园"],"style":"绮丽","style2":["幽峭","豪放"],"mood":"悲怆","mood2":[],"scene":["园林","酒","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"人生":["读书"],"植物":["柳树"],"食物":["荔枝"]},"theme_conf":0.75},{"uid":"35c4618c-3896-45f8-9b24-51764c90383f","title":"横吹曲辞 折杨柳","author":"刘宪","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["沙塞三河道，金闺二月春。","碧烟杨柳色，红粉绮罗人。","露叶怜啼脸，风花思舞巾。","攀持君不见，为听曲中新。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":[],"scene":["塞外","春","花","月"],"cats":{"抒情":["思念","闺怨"],"四季":["春天"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.5},{"uid":"e76a9e8e-c640-40b3-bf3d-dc0ca2985fe4","title":"答寄芙蓉冠子","author":"王建","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一学芙蓉叶，初开映水幽。","虽经小儿手，不称老夫头。","枕上眠常戴，风前醉恐柔。","明年有闺阁，此样必难求。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","楼"],"cats":{"人物":["儿童"],"植物":["荷花"]},"theme_conf":0.95},{"uid":"9f57b2df-7f47-4600-a68a-a3efb709ff40","title":"浙东元相公书叹梅雨郁蒸之候因寄七言","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["稽山自与岐山别，何事连年𬸚𬸦飞。","百辟商量旧相入，九天祗候老臣归。","平湖晚泛窥清镜，高阁晨开扫翠微。","今日看书最惆怅，为闻梅雨损朝衣。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["雨","冬"],"cats":{"天气":["写雨"],"植物":["梅花"]},"theme_conf":0.95},{"uid":"c5154a66-2e69-41ff-bc12-718763201e90","title":"梅花二首 一","author":"王初","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["应为阳春信未传，固将青艳属残年。","东君欲待寻佳约，剩寄衣香与粉绵。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["花","春","冬"],"cats":{"四季":["春天"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"41181679-c303-4d56-a0a2-f454236cfa0b","title":"裴侍御见赠斑竹杖","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骚人夸竹杖，赠我意何深。","万点湘妃泪，三年贾谊心。","愿持终白首，谁道贵黄金。","他日归愚谷，偏宜绿绮琴。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感"],"植物":["竹子"]},"theme_conf":0.78},{"uid":"d340ad23-8f26-4ee8-9873-8b044a6f158b","title":"赋得临池竹","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["贞条障曲砌，翠叶贯寒霜。","拂牖分龙影，临池待凤翔。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["园林"],"cats":{"植物":["竹子"]},"theme_conf":1.0},{"uid":"d3759322-e75e-443c-a2f9-0a15daa8b91a","title":"阶下莲","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["叶展影飜当砌月，花开香散入帘风。","不如种在天池上，犹胜生于野水中。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","花","月"],"cats":{"植物":["荷花"]},"theme_conf":1.0},{"uid":"05d0c667-b634-4962-8141-6a0cd84f56be","title":"一叶落","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["轻叶独悠悠，天高片影流。","随风来此地，何树落先秋。","变色黄应近，辞林绿尚稠。","无双浮水面，孤绝落关头。","乍减诚难觉，将凋势未休。","客心空自比，谁肯问新愁。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["清新","旷达"],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"0f9dd333-5f18-478b-8b18-53ed1bf06e91","title":"秋夜听严绅巴童唱竹枝歌","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["巴人远从荆山客，回首荆山楚云隔。","思归夜唱竹枝歌，庭槐叶落秋风多。","曲中历历叙乡土，乡思绵绵楚词古。","身骑吴牛不畏虎，手提蓑笠欺风雨。","猨啼日暮江岸边，绿芜连山水连天。","来时十三今十五，一成新衣已再补。","鸿雁南飞报邻伍，在家欢乐辞家苦。","天晴露白钟漏迟，泪痕满面看竹枝。","曲终寒竹风袅袅，西方落日东方晓。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["夜","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"人物":["儿童"],"植物":["竹子"]},"theme_conf":0.586},{"uid":"0e6f466c-3fc6-4930-a25b-3c14172c1b41","title":"寒食宴城北山池即故郡守荣阳郑钢目为折柳亭","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["别馆青山郭，游人折柳行。","落花经上巳，细雨带清明。","𫛸鴂流芳暗，鸳鸯曲水平。","归心何处醉，宝瑟有余声。"],"theme":"节令风俗","theme2":["送别"],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"抒情":["离别","思乡"],"天气":["写雨"],"节日":["寒食节","清明节"],"植物":["柳树"]},"theme_conf":0.88},{"uid":"b6c590ce-9357-4a67-85bb-29a2402d9c33","title":"和王给事禁省梨花咏","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["巧解逢人笑，还能乱蝶飞。","春时风入户，几片落朝衣。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"43c9f1f6-3a24-489d-a8c9-552711348736","title":"奉和虢州刘给事使君三堂新题二十一咏 荷池","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["风雨秋池上，高荷盖水繁。","未谙鸣摵摵，那似卷翻翻。"],"theme":"应制干谒","theme2":["咏物"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["园林","夏","雨"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.95},{"uid":"2fa17eef-441f-4e0f-bb10-37d2d71f601c","title":"军事院霜菊盛开因书一绝寄上谏议","author":"皮日休","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["金华千点晓霜凝，独对壶觞又不能。","已过重阳三十日，至今犹自待王弘。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳","秋","酒","园林"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.403},{"uid":"f7c5a05e-436c-4fd9-b093-3886e90cd529","title":"酬裴杰秀才新樱桃","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["新果真琼液，来应宴紫兰。","圆疑窃龙颔，色已夺鸡冠。","远火微微辨，残星隐隐看。","茂先知味易，曼倩恨偷难。","忍用烹骍骆，从将玩玉盘。","流年如可驻，何必九华丹。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["清新","旷达"],"mood":"愁怨","mood2":["欢愉"],"scene":[],"cats":{"人生":["时光"],"植物":["桃花"]},"theme_conf":0.86},{"uid":"6bb164b4-b9d3-4d23-b54b-e71e3535ddc7","title":"左掖梨花","author":"丘为","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["冷艳全欺雪，余香乍入衣。","春风且莫定，吹向玉阶飞。"],"theme":"咏物","theme2":["闺情宫怨"],"style":"悲慨","style2":["旷达"],"mood":"孤寂","mood2":[],"scene":["花","雪","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"植物":["梨花"]},"theme_conf":0.556},{"uid":"50fa86ae-4358-4dac-bc7d-26a60929034f","title":"杂曲歌辞 昔昔盐 蘼芜叶复齐","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["提筐红叶下，度日采蘼芜。","掬翠香盈袖，看花忆故夫。","叶齐谁复见，风暖恨偏孤。","一被春光累，容颜与昔殊。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["花","春"],"cats":{"抒情":["思念","孤独","闺怨"],"四季":["春天"],"植物":["叶子"]},"theme_conf":0.9},{"uid":"04803420-1f5b-48f0-abba-2940006ba36b","title":"月夜梧桐叶上见寒露","author":"戴察","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["萧疎桐叶上，月白露初团。","滴沥清光满，荧煌素彩寒。","风摇愁玉坠，枝动惜珠干。","气冷疑秋晚，声微觉夜阑。","凝空流欲遍，润物净宜看。","莫厌窥临倦，将晞聚更难。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":["幽峭","绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"植物":["叶子"]},"theme_conf":0.82},{"uid":"74cd7154-770a-41c4-b55d-1e27ac1ba628","title":"崦里桃花","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["崦里桃花逢女冠，林间杏叶落仙坛。","老人方授上清箓，夜听步虚山月寒。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"植物":["桃花"]},"theme_conf":1.0},{"uid":"f515aba3-5d02-403d-b829-c550e84156db","title":"王起居独游青龙寺玩红叶因寄","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["十亩苍苔遶画廊，几株红树过清霜。","高情还似看花去，闲对南山步夕阳。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["孤独"],"植物":["叶子"]},"theme_conf":0.88},{"uid":"26a4d4f1-b9bb-42c4-8201-8b84b88c5531","title":"江梅","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["梅蘂腊前破，梅花年后多。","绝知春意好，最奈客愁何。","雪树元同色，江风亦自波。","故园不可见，巫岫郁嵯峨。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","冬"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"植物":["梅花"]},"theme_conf":0.638},{"uid":"cde3ddab-b6aa-4cce-99de-e600b9e82746","title":"红叶","author":"吴融","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["露染霜干片片轻，斜阳照处转烘明。","和烟飘落九秋色，随浪泛将千里情。","几夜月中藏鸟影，谁家庭际伴蛩声。","一时衰飒无多恨，看着清风彩剪成。"],"theme":"咏物","theme2":[],"style":"清新","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.96},{"uid":"afb30a8c-345b-471d-bf80-9f1828f8e097","title":"横吹曲辞 折杨柳","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["红粉青楼曙，垂杨仲月春。","怀君重攀折，非妾妒腰身。","舞带萦丝断，娇娥向叶嚬。","横吹凡几曲，独自最愁人。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["春","楼","月"],"cats":{"抒情":["伤感","孤独","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"c5953a86-c1c2-432a-8e73-cfb2ab364071","title":"题道虔上人竹房","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["诗思禅心共竹闲，任他流水向人间。","手持如意高窓里，斜日沿江千万山。"],"theme":"佛道禅颂","theme2":["咏物","哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","山"],"cats":{"人生":["哲理"],"植物":["竹子"]},"theme_conf":0.78},{"uid":"a36a0840-505a-449f-b3eb-e0060e8ae76d","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["羽毛似雪无瑕点，顾影秋池舞白云。","闲整素仪三岛近，回飘清唳九霄闻。","好风顺举应摩日，逸翮将成莫恋群。","凌励坐看空碧外，更怜凫鹭老江𣸣。"],"theme":"咏物","theme2":["咏史怀古"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雪","冬","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"植物":["梅花"]},"theme_conf":0.95},{"uid":"e1f2edef-a6a6-40bd-97e1-c5dedb7976b2","title":"题桐叶","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["去年桐落故溪上，把笔偶题归燕诗。","江楼今日送归燕，正是去年题叶时。","叶落燕归真可惜，东流玄髪且无期。","笑筵歌席反惆怅，明月清风怆别离。","庄叟彭殇同在梦，陶潜身世两相遗。","一丸五色成虚语，石烂松薪更莫疑。","哆侈不劳文似锦，进趋何必利如锥。","钱神任尔知无敌，酒圣于吾亦庶几。","江畔秋光蟾阁镜，槛前山翠茂陵眉。","樽香轻泛数枝菊，簷影斜侵半局棋。","休指宦游论巧拙，秪将愚直祷神祇。","三吴烟水平生念，宁向闲人道所之。"],"theme":"咏怀抒感","theme2":["闲适隐逸","咏物"],"style":"旷达","style2":["婉约","绮丽"],"mood":"惆怅","mood2":[],"scene":["月","酒","楼"],"cats":{"抒情":["离别"],"天气":["月亮"],"植物":["叶子"]},"theme_conf":0.85},{"uid":"6e27c564-356b-4c7b-8594-861f03d55cfc","title":"武陵书怀五十韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西汉开支郡，南朝号戚藩。","四封当列宿，百雉俯清沅。","高岸朝霞合，惊湍激箭奔。","积阴春暗度，将霁雾先昏。","俗尚东皇祀，谣传义帝冤。","桃花迷隐迹，楝叶慰忠魂。","户算资渔猎，乡豪恃子孙。","照山畬火动，踏月俚歌喧。","拥檝舟为市，连甍竹覆轩。","披沙金粟见，拾羽翠翘翻。","茗折苍溪秀，苹生枉渚暄。","禽惊格磔起，鱼戏𪡋喁繁。","沈约台榭故，李衡墟落存。","湘灵悲鼓瑟，泉客泣酬恩。","露变蒹葭浦，星悬橘柚村。","虎咆空野震，鼍作满川浑。","邻里皆迁客，儿童习左言。","炎天无冽井，霜月见芳荪。","清白家传远，诗书志所敦。","列科叨甲乙，从宦出丘樊。","结友心多契，驰声气尚吞。","士安曾重赋，元礼许登门。","草檄嫖姚幕，巡兵戊己屯。","筑台先自隗，送客独留髠。","遂结王畿绶，来观衢室罇。","鸢飞入鹰隼，鱼目俪玙璠。","晓烛罗驰道，朝阳辟帝阍。","王正会夷夏，月朔盛旗旛。","独立当瑶阙，传呵步紫垣。","按章清犴狱，视祭洁苹蘩。","御历昌期远，传家宝祚蕃。","繇文光夏启，神教畏轩辕。","内禅因天性，雄图授化元。","继明悬日月，出震统乾坤。","大孝三朝备，洪恩九族惇。","百川宗渤澥，五岳辅昆仑。","何幸逢休运，微班识至尊。","校𦈏资筦榷，复土奉山园。","一失贵人意，徒闻太学论。","直庐辞锦帐，远守愧朱幡。","巢幕方犹燕，抢榆尚笑鲲。","邅回过荆楚，流落感凉温。","旅望花无色，愁心醉不惛。","春江千里草，暮雨一声猿。","问卜安冥数，看方理病源。","带赊衣改制，尘涩劒成痕。","三秀悲中散，二毛伤虎贲。","来忧御魑魅，归愿牧鸡豚。","就日秦京远，临风楚奏烦。","南登无灞岸，旦夕上高原。"],"theme":"羁旅思乡","theme2":["山水田园","送别"],"style":"绮丽","style2":["清新","雄浑"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["夏","江","楼","花"],"cats":{"抒情":["友情","思乡","伤感","孤独"],"四季":["夏天"],"天气":["太阳"],"人物":["儿童"],"人生":["读书"],"植物":["桃花"]},"theme_conf":0.239},{"uid":"1f1220b8-28ca-4ded-b86b-11a6f4a7c0e7","title":"红叶","author":"罗隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不奈荒城畔，那堪晚照中。","野晴霜浥绿，山冷雨催红。","游子灞陵道，美人长信宫。","等闲居岁暮，摇落意无穷。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["花","雨","山"],"cats":{"人物":["女子"],"植物":["叶子"]},"theme_conf":0.86},{"uid":"ac8989bc-6581-4530-9869-49574f9b111c","title":"竹","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["卷箨正离披，新枝复蒙密。","翛翛月下闻，褭褭林际出。","岂独对芳菲，终年色如一。"],"theme":"山水田园","theme2":["咏物","送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["月","春"],"cats":{"抒情":["孤独"],"植物":["竹子"]},"theme_conf":0.392},{"uid":"aa3363f3-d276-4f9a-985e-37f2db392800","title":"寄淮上柳十三","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["苇萧中辟户，相映绿淮流。","莫讶春潮阔，鸥边可泊舟。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","舟","江"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":0.9},{"uid":"2bfd3472-5aea-48b4-ae78-6c030ef4e64f","title":"春池柳","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["年柳变池台，隋堤曲直回。","逐浪丝阴去，迎风带影来。","疎黄一鸟弄，半翠几眉开。","萦雪临春岸，参差间早梅。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"3d5c77d4-1ce5-458f-bf76-648539c0a0b2","title":"闻吹杨叶者二首 二","author":"郎士元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["天生一艺更无伦，寥亮幽音妙入神。","吹向别离攀折处，当应合有断肠人。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["离别","伤感"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"08d0e076-ff46-4c75-b7d2-60a94290dfb6","title":"千叶桃花","author":"杨凭","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千叶桃花胜百花，孤荣春晚驻年华。","若教避俗秦人见，知向河源旧侣夸。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["孤独"],"山水":["黄河"],"植物":["桃花","叶子"]},"theme_conf":1.0},{"uid":"58ab4b4a-7267-4525-8e47-15ba3f8aec41","title":"幸梨园观打毬应制","author":"武平一","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["令节重遨游，分镳应彩毬。","骖驔廻上苑，蹀躞绕通沟。","影就红尘没，光随赭汗流。","赏阑清景暮，歌舞乐时休。"],"theme":"应制干谒","theme2":[],"style":"旷达","style2":[],"mood":"欢愉","mood2":[],"scene":["园林"],"cats":{"植物":["梨花"]},"theme_conf":0.99},{"uid":"5679526b-d077-4f1f-a67e-fc430e4643a9","title":"柳州二月榕叶落尽偶题","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宦情羁思共凄凄，春半如秋意转迷。","山城过雨百花尽，榕叶满庭莺乱啼。"],"theme":"咏物","theme2":["羁旅思乡","山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["月亮"],"植物":["柳树","叶子"]},"theme_conf":0.421},{"uid":"a2833e0a-d45e-4103-9604-e22a620a016b","title":"池上竹","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一丛婵娟色，四面清冷波。","气润晚烟重，光闲秋露多。","翠筠入疎柳，清影拂圆荷。","岁晏琅玕实，心期有凤过。"],"theme":"山水田园","theme2":["咏物","闲适隐逸"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","中秋","秋"],"cats":{"四季":["秋天"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.408},{"uid":"b2c3957f-77eb-42bc-a2ae-0337b317a053","title":"题慈仁寺竹院","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["千峰对古寺，何异到西林。","幽罄蝉声下，闲窗竹翠阴。","诗人谢客兴，法侣远公心。","寂寂炉烟里，香花欲暮深。"],"theme":"佛道禅颂","theme2":["山水田园","闲适隐逸"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["园林","花"],"cats":{"山水":["庐山"],"植物":["竹子"]},"theme_conf":0.8},{"uid":"1f0f728d-0c02-4fd4-9976-ba6f0cba1c12","title":"相和歌辞 采莲归","author":"王勃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["采莲归，绿水芙蓉衣，秋风起浪凫雁飞。","桂棹兰桡下长浦，罗裙玉腕摇轻橹。","叶屿花潭极望平，江讴越吹相思苦。","相思苦，佳期不可驻。","塞外征夫犹未还，江南采莲今已暮。","今已暮，摘莲花，今渠那必尽倡家。","官道城南把桑叶，何如江上采莲花？","莲花复莲花，花叶何重叠。","叶翠本羞眉，花红彊如颊。","佳人不兹期，怅望别离时。","牵花怜共蒂，折藕爱连丝。","故情何处所？新物徒华滋。","不惜南津交佩解，还羞北海雁书迟。","采莲歌有节，采莲夜未歇。","正逢浩荡江上风，又值徘徊江上月。","莲浦夜相逢，吴姬越女何丰茸。","共问寒江千里外，征客关山更几重。"],"theme":"爱情相思","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江南","塞外","舟"],"cats":{"抒情":["爱情","离别","思念","思乡"],"人物":["女子"],"植物":["荷花"]},"theme_conf":0.374},{"uid":"ab8714f5-9716-490c-ba80-04926c6c4849","title":"送柳道士","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["去世能成道，游仙不定家。","归期千岁鹤，行迈五云车。","海上春应尽，壶中日未斜。","不知相忆处，琪树几枝花。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.546},{"uid":"8b2a898c-bb52-463e-8a8a-989eacb2ce54","title":"华下对菊","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["清香裛露对高斋，泛酒偏能浣旅怀。","不似春风逞红艳，镜前空坠玉人钗。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["重阳","酒","春","花"],"cats":{"四季":["春天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.724},{"uid":"9e60181d-a16b-4261-89b7-a3814a52a107","title":"禁中九日对菊花酒忆元九","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["赐酒盈杯谁共持，宫花满把独相思。","相思只傍花边立，尽日吟君咏菊诗。"],"theme":"节令风俗","theme2":["爱情相思"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["酒","重阳"],"cats":{"抒情":["爱情","思念"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"],"食物":["写酒"]},"theme_conf":0.78},{"uid":"e6bc6d3d-576c-40c2-8736-922e8f15d9e0","title":"观叶生画花","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["心窍玲珑貌亦奇，荣枯只在手中移。","今朝故向霜天里，点破繁花四五枝。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"植物":["叶子"]},"theme_conf":1.0},{"uid":"13410de4-30e9-4c47-96f8-df7dd6d6e543","title":"白菊杂书四首 二","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["四面云屏一带天，是非断得自翛然。","此生只是偿诗债，白菊开时最不眠。"],"theme":"闲适隐逸","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.78},{"uid":"8a9d9842-af13-4e4a-9973-63799a2ff132","title":"晚岁登武陵城顾望水陆怅然有作","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["星象承乌翼，蛮陬想犬牙。","俚人祠竹节，仙洞闭桃花。","城基历汉魏，江源自賨巴。","华表廖王墓，菜地黄琼家。","霜轻菊秀晚，石浅水纹斜。","樵音绕故垒，汲路明寒沙。","清风稍改叶，卢橘始含葩。","野桥过驿骑，丛祠发逈笳。","跳鳞避举网，倦鸟寄行楂。","路尘高出树，山火远连霞。","夕曛转赤岸，浮霭起苍葭。","轧轧渡水桨，连连赴林鸦。","呌阍道非远，赐环期自赊。","孤臣本危涕，乔木在天涯。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["孤独","怀古"],"生活":["写桥"],"植物":["桃花"]},"theme_conf":0.385},{"uid":"a2c64cce-66c4-481f-bcce-0b54ff36d87f","title":"严郑公宅同咏竹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["绿竹半含箨，新梢才出墙。","色侵书帙晚，阴过酒樽凉。","雨洗娟娟净，风吹细细香。","但令无剪伐，会见拂云长。"],"theme":"咏物","theme2":[],"style":"婉约","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["酒"],"cats":{"植物":["竹子"]},"theme_conf":0.568},{"uid":"e46d6dff-6b75-4e72-8637-707d78481256","title":"裴侍郎湘川回以青竹筒相遗因而赠之","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["楚竹青玉润，从来湘水阴。","缄书取直节，君子知虚心。","入用随宪简，积文不受金。","体将丹凤直，色映秋霜深。","宁肯假伶伦，谬为龙凤吟。","唯将翰院客，昔秘瑶华音。","长跪捧嘉贶，岁寒惭所钦。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","冬"],"cats":{"四季":["秋天","冬天"],"植物":["竹子"]},"theme_conf":0.9},{"uid":"2c9a2809-eb92-46db-bdea-5c6071efe4f1","title":"梦好梨花歌","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["薄薄落落雾（别本作「路」）不分，梦中唤作梨花云。","瑶池水光蓬莱雪，青叶白花相次发。","不从地上生枝柯，合在天头遶宫阙。","天风微微吹不破，白艳却愁香涴露。","玉房彩女齐看来，错认仙山鹤飞过。","落花散粉飘满空，梨花颜色同不同。","眼穿臂短取不得，取得亦如从梦中。","无人为我解此梦，梨花一曲心珍重。","（见宋张邦基《墨庄漫录》卷六）（按：《墨庄漫录》：「东坡作梅花词云：『高情已逐晓云空，不与梨花同梦。","』注云：『唐王建有《梦看梨花云诗》。","』予求王建诗，行世甚少，唯印行本一卷，乃无此篇。","后得之于晏元献《类要》中。","后又得建全集七卷，乃得全篇，题云《梦好梨花歌》。","〖诗略〗或误传为王昌龄，非也。","」另参本书卷九王昌龄诗附按。","）。"],"theme":"游仙梦幻","theme2":[],"style":"清新","style2":["婉约"],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["花"],"cats":{"抒情":["伤感","孤独"],"人生":["梦想","读书"],"植物":["梨花"]},"theme_conf":0.776},{"uid":"cbdd1bd4-58ea-4bd4-a64c-40654f818387","title":"咏庭梅寄人","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["蚤花常犯寒，繁实常苦酸。","何事上春日，坐令芳意阑。","夭桃定相笑，游妓肯回看。","君问调金鼎，方知正味难。"],"theme":"咏物","theme2":["咏物"],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["园林","花","春","冬"],"cats":{"四季":["春天"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"9fb8dfe5-540c-4e2e-b12a-085273a6cf99","title":"和王相公题中书丛竹寄上元相公","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["多时仙掖里，色并翠琅玕。","幽意含烟月，清阴庇蕙兰。","枝繁宜露重，叶老爱天寒。","竟日双鸾止，孤吟为一看。"],"theme":"咏物","theme2":["送别","应制干谒","咏物"],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["元宵"],"cats":{"抒情":["孤独"],"节日":["元宵节"],"植物":["竹子"]},"theme_conf":0.7},{"uid":"04adc73f-5d2d-4a17-9254-28a80a52069f","title":"相和歌辞 采莲曲","author":"贺知章","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["稽山罢雾郁嵯峨，镜水无风也自波。","莫言春度芳菲尽，别有中流采芰荷。"],"theme":"爱情相思","theme2":["送别","山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["荷花"]},"theme_conf":0.393},{"uid":"7cece203-8db8-49ea-97f2-74f1f885a3bc","title":"青龙寺留别义操阇梨","author":"空海","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["同法同门喜遇深，空随白雾忽归岑。","一生一别难再见，非梦思中数数寻。","（同前）。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["欢愉"],"scene":[],"cats":{"抒情":["离别"],"植物":["梨花"]},"theme_conf":0.715},{"uid":"a5f2d36f-9597-41a7-99cc-5ff88b7c8c79","title":"相和歌辞 采莲曲","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["越江女，越江莲。","齐菡萏，双婵娟。","嬉游向何处？","采摘且同船。","浩唱发容与，清波生漪涟。","时逢岛屿泊，几共鸳鸯眠。","襟袖既盈溢，馨香亦相传。","薄暮归去来，苎罗生碧烟。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["中秋","江南","江","舟"],"cats":{"抒情":["爱情"],"节日":["中秋节"],"植物":["荷花"]},"theme_conf":0.66},{"uid":"918ace29-2ca6-4146-9993-0a9dac3f5835","title":"咏夹迳菊","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夹迳尽黄英，不通人竝行。","几曾相对绽，元自两行生。","丛比高低等，香连左右幷。","畔摇风势断，中夹日华明。","间隔蛩吟隔，交横蝶乱横。","频应泛桑落，摘处近前楹。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"d21445d0-930f-43ac-b31b-de28e5ec6e6b","title":"杂曲歌辞 杨柳枝 三","author":"和凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["鹊桥初就咽银河，今夜仙郎自性和。","不是昔年攀桂树，岂能月里索姮娥。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["月","七夕","夜"],"cats":{"生活":["写桥"],"节日":["七夕节"],"植物":["柳树"]},"theme_conf":0.65},{"uid":"f198211f-331a-4f1f-87f2-ca57cc5264cd","title":"春日咏梅花二首 一","author":"王初","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["靓妆才罢粉痕新，递晓风回散玉尘。","若遣有情应怅望，已兼残雪又兼春。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"7ef7bc94-3b3f-4224-ba4c-889a39870e38","title":"朝日勅赐百官樱桃","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["仙果人间都未有，今朝忽见下天门。","捧盘小吏初宣勅，当殿群臣共拜恩。","日色遥分门下坐，露香才出禁中园。","每年重此先偏待，愿得千春奉至尊。"],"theme":"游仙梦幻","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"天气":["太阳"],"植物":["桃花"]},"theme_conf":0.65},{"uid":"5a8f448f-d34b-4f01-95ca-4c0111970197","title":"摘樱桃赠元居士时在望仙亭南楼与朱道士同处","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["海上朱樱赠所思，楼居况是望仙时。","蓬莱羽客如相访，不是偷桃一小儿。"],"theme":"寄赠酬答","theme2":["游仙梦幻"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["楼"],"cats":{"人物":["儿童"],"植物":["桃花"]},"theme_conf":0.92},{"uid":"35638e63-ef59-411d-a832-af24221fd0fd","title":"题落叶","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["霜景催危叶，今朝半树空。","萧条故国异，零落旅人同。","飒岸浮寒水，依堦拥夜虫。","随风偏可羡，得到洛阳宫。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","怀古"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.463},{"uid":"82506631-692c-4f17-96a4-9fcb52ca6d5a","title":"梨岭","author":"林藻","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["曾向岭头题姓字，不穿杨叶不言归。","弟兄各折一枝桂，还向岭头联影飞。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"植物":["梨花"]},"theme_conf":1.0},{"uid":"27423bb8-fa3f-41e6-83a6-9c105c176d3d","title":"御沟新柳","author":"冯宿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夹道天渠远，垂丝御柳新。","千条宜向日，万户共迎春。","轻翠含烟发，微音逐吹频。","静看思渡口，回望忆江滨。","袅袅分游骑，依依驻旅人。","阳和如可及，攀折在兹辰。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"清新","style2":["婉约","冲淡"],"mood":"相思","mood2":[],"scene":["春","江"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.528},{"uid":"dfaaaf11-9ead-4921-a71e-1f60be94af03","title":"得柳员外书封寄近诗书中兼报新主行营兵马因代书戏答","author":"独孤及","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["郎官作掾心非好，儒服临戎政已闻。","说劒尝宗漆园吏，戒严应笑棘门军。","遥知抵掌论皇道，时复吟诗向白云。","百越待君言即叙，相思不敢怆离群。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["园林","江南"],"cats":{"抒情":["思念"],"人生":["读书","战争"],"动物":["写马"],"植物":["柳树"]},"theme_conf":0.95},{"uid":"12c990df-c417-480a-aa17-39836764b4ef","title":"湘岸移木芙蓉植龙兴精舍","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["有美不自蔽，安能守孤根。","盈盈湘西岸，秋至风露繁。","丽影别寒水，秾芳委前轩。","芰荷谅难杂，反此生高原。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":["婉约"],"mood":"孤寂","mood2":["欢愉"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"植物":["荷花"]},"theme_conf":0.621},{"uid":"8b5741ba-0a9b-4a04-9ea8-fed55e797055","title":"和令狐相公九日对黄白二菊花见怀","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["素萼迎寒秀，金英带露香。","繁华照旄钺，荣盛对银黄。","琮璧交辉映，衣裳杂彩章。","晴云遥盖覆，秋蝶近悠扬。","空想逢九日，何由陪一觞。","满丛佳色在，未肯委严霜。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":["冲淡","清新"],"mood":"孤寂","mood2":[],"scene":["重阳","花"],"cats":{"四季":["秋天"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.78},{"uid":"5400406f-949f-4793-8c52-8cb59b47ac61","title":"忆白菊","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["稚子书传白菊开，西成相滞未容回。","月明阶下窗纱薄，多少清香透入来。"],"theme":"亲情","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念"],"人物":["儿童"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.528},{"uid":"9debbe96-77b3-4b24-ab2d-7c3afc4a9245","title":"竹里梅","author":"刘言史","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["竹里梅花相竝枝，梅花正发竹枝垂。","风吹总向竹枝上，直似王家雪下时。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["冬"],"cats":{"植物":["梅花","竹子"]},"theme_conf":0.564},{"uid":"2e0dfd8f-821c-40ce-b802-251e56eb1ed3","title":"隄上柳","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["垂柳万条丝，春来织别离。","行人攀折处，闺妾断肠时。"],"theme":"闺情宫怨","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["离别","伤感","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.403},{"uid":"66652d2e-dd84-451f-a266-0250675171d1","title":"与诸客携酒寻去年梅花有感","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["马上同携今日杯，湖边共觅去春梅。","年年只是人空老，处处何曾花不开。","诗思又牵吟咏发，酒酣闲唤管弦来。","樽前百事皆依旧，点检惟无薛秀才。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["酒"],"cats":{"抒情":["思乡"],"植物":["梅花"],"食物":["写酒"]},"theme_conf":0.522},{"uid":"a02551b7-28e1-4a79-8e2c-a185c70cffcb","title":"杂曲歌辞 桃花行 一","author":"李峤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["岁去无言忽顦顇，时来含笑吐氛氲。","不能拥路迷仙客，故欲开蹊侍圣君。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"抒情":["思乡"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"17a154bf-36c4-49cf-8091-105f48c9ec09","title":"桃林夜贺晋公","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["西来骑火照山红，夜宿桃林腊月中。","手把命珪兼相印，一时重叠赏元功。"],"theme":"山水田园","theme2":["应制干谒"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夜"],"cats":{"植物":["桃花"]},"theme_conf":0.541},{"uid":"73b463e3-0634-4be4-8d69-935d41bb76ba","title":"落叶","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["陈绿向参差，初红已重叠。","中庭初扫地，绕树三两叶。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["秋","园林"],"cats":{"抒情":["思乡"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"3108e645-afe2-4f20-b8a8-cc280496b99c","title":"对梨花赠皇甫秀才","author":"韦庄","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["林上梨花雪压枝，独攀琼艳不胜悲。","依前此地逢君处，还是去年今日时。","且恋残阳留绮席，莫推红袖诉金巵。","腾腾战鼓正多事，须信明朝难重持。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["花","雪"],"cats":{"抒情":["伤感","孤独"],"植物":["梨花"]},"theme_conf":0.85},{"uid":"974d29ec-068c-4022-81f5-ebdf6d8c4bc8","title":"芙蓉榭","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["风摆莲衣干，月背鸟巢寒。","文鱼翻乱叶，翠羽上危栏。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["月","楼"],"cats":{"植物":["荷花"]},"theme_conf":0.78},{"uid":"f646a1ae-7a3e-4cdb-96d4-8c2ab4fb899a","title":"露青竹杖歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["鲜于仲通正当年，章仇兼琼在蜀川。","约束蜀儿采马鞭，蜀儿采鞭不敢眠。","横截斜飞飞鸟边，绳桥夜上层崖颠。","头插白云跨飞泉，采得马鞭长且坚。","浮沤丁子珠联联，灰煮蜡楷光烂然。","章仇兼琼持上天，上天雨露何其偏。","飞龙闲厩马数千，朝饮吴江夕秣燕。","红尘扑辔汗湿鞯，师子麒麟聊比肩。","江面昆明洗刷牵，四蹄踏浪头枿天。","蛟龙稽颡河伯虔，拓羯胡雏脚手鲜。","陈闳韩干丹青妍，欲貌未貌眼欲穿。","金鞍玉勒锦连干，骑入桃花杨柳烟。","十二楼中奏管弦，楼中美人夺神仙。","争爱大家把此鞭，禄山入关关破年。","忽见扬州北邙前，秪有人还千一钱。","亭亭笔直无皴节，磨捋形相一条铁。","市头格是无人别，江海贱臣不拘絏。","垂窗挂影西窗缺，稚子觅衣挑仰穴。","家童拾薪几拗折，玉润犹沾玉垒雪。","碧鲜似染苌弘血，蜀帝城边子规咽。","相如桥上文君绝，往年策马降至尊。","七盘九折横剑门，穆王八骏超昆仑。","安用冉冉孤生根，圣人不贵难得货，金玉珊珊谁买恩。"],"theme":"讽喻刺世","theme2":["山水田园","游仙梦幻","送别"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["雪","楼","鸟"],"cats":{"抒情":["孤独"],"人物":["女子","儿童"],"生活":["写桥"],"植物":["竹子"]},"theme_conf":0.75},{"uid":"d39a3dfa-9d38-4b9f-9a13-d3063b0b47bd","title":"横吹曲辞 梅花落","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["梅岭花初发，天山雪未开。","雪处疑花满，花边似雪回。","因风入舞袖，杂粉向妆台。","匈奴几万里，春至不知来。"],"theme":"边塞征战","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["冬","花","山","雪"],"cats":{"植物":["梅花"]},"theme_conf":0.568},{"uid":"0e651edd-1bc8-49c9-bd85-b49df84c9743","title":"横吹曲辞 折杨柳","author":"韦承庆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万里边城地，三春杨柳节。","叶似镜中眉，花如关外雪。","征人远乡思，倡妇高楼别。","不忍掷年华，含情寄攀折。"],"theme":"送别","theme2":["边塞征战","羁旅思乡"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["雪","春","楼"],"cats":{"抒情":["思乡"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.463},{"uid":"48f5b2c1-37be-4114-9f50-6001f4abd841","title":"新栽梅","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["池边新种七株梅，欲到花时点检来。","莫怕长洲桃李妬，今年好为使君开。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["冬"],"cats":{"植物":["梅花"]},"theme_conf":1.0},{"uid":"f19c7864-67cf-4485-9b9d-a02c505ec4c7","title":"桃源篇","author":"权德舆","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["小年尝读桃源记，忽覩良工施绘事。","岩迳初欣缭绕通，溪风转觉芬芳异。","一路鲜云杂彩霞，渔舟远远逐桃花。","渐入空蒙迷岛道，宁知掩映有人家。","庞眉秀骨争迎客，凿井耕田人世隔。","不知汉代有衣冠，犹说秦家变阡陌。","石髓云英甘且香，仙翁留饭出青囊。","相逢自是松乔侣，良会应殊刘阮郎。","内子闲吟倚瑶瑟，玩此沈沈销永日。","忽闻丽曲金玉声，便使老夫思阁笔。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["绮丽","冲淡"],"mood":"恬淡","mood2":[],"scene":["花","舟"],"cats":{"植物":["桃花"]},"theme_conf":0.826},{"uid":"cp749e871e4d03de","title":"淡黄柳","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["空城晓月。","吹入垂杨陌。","马上单衣寒恻恻。","看尽鹅黄嫩绿，都是江南旧相识。","正岑寂。","明朝又寒食。","强携酒、小桥宅，怕梨花落尽成秋色。","燕燕飞来，问春何在，唯有池塘自碧。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":["恬淡"],"scene":["清明","江南","酒","秋","春","月"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"生活":["写桥"],"节日":["寒食节","清明节"],"植物":["柳树"]},"theme_conf":0.86},{"uid":"2b0ce34d-ac0b-46f7-9e30-c7433a73d83a","title":"菊","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["暗暗淡淡紫，融融冶冶黄。","陶令篱边色，罗含宅里香。","几时禁重露，实是怯残阳。","愿泛金鹦鹉，升君白玉堂。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"202641be-8d53-4de4-b477-fcbef11c89bf","title":"种白蘘荷","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["血虫化为疠，夷俗多所神。","衔猜每腊毒，谋富不为仁。","蔬果自远至，杯酒盈肆陈。","言甘中必苦，何用知其真。","华洁事外饰，尤病中州人。","钱刀恐贾害，饥至益逡巡。","窜伏常战栗，怀故逾悲辛。","庶氏有嘉草，攻禬事久泯。","炎帝垂灵编，言此殊足珍。","崎岖乃有得，托以全余身。","纷敷碧树阴，眄睐心所亲。"],"theme":"讽喻刺世","theme2":["民生疾苦","边塞征战","咏物"],"style":"沉郁","style2":["清新"],"mood":"悲怆","mood2":[],"scene":["夏","酒"],"cats":{"抒情":["伤感"],"四季":["夏天"],"人生":["战争"],"植物":["荷花"]},"theme_conf":0.88},{"uid":"16f2a421-f439-45f3-9fe5-b9948368568e","title":"送柳道时余北还","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["征役各异路，烟波同旅愁。","轻桡上桂水，大艑下扬州。","何处成后会，今朝分旧游。","离心比杨柳，萧飒不胜秋。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江"],"cats":{"抒情":["伤感"],"四季":["秋天"],"植物":["柳树"]},"theme_conf":0.802},{"uid":"cp1ab8bda1f065cf","title":"采莲令","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["月华收，云淡霜天曙。","西征客、此时情苦。","翠娥执手送临歧，轧轧开朱户。","千娇面、盈盈伫立，无言有泪，断肠争忍回顾。","一叶兰舟，便恁急桨凌波去。","贪行色、岂知离绪。","万般方寸，但饮恨，脉脉同谁语。","更回首、重城不见，寒江天外，隐隐两三烟树。"],"theme":"送别","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["舟","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"植物":["荷花"]},"theme_conf":0.622},{"uid":"e996c456-84b3-43a2-a846-5ef5d5310e5c","title":"奉和文尧对庭前千叶石榴","author":"黄滔","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一朵千英绽晓枝，彩霞堪与别为期。","移根若在芙蓉苑，岂向当年有醒时。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["园林"],"cats":{"植物":["叶子"]},"theme_conf":0.78},{"uid":"67cea0fa-4c7b-456a-ae5d-574d1dc8a878","title":"晚投江泽浦即事呈柳兵曹泥","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落日过重霞，轻烟上远沙。","移舟冲荇蔓，转浦入芦花。","断岸迂来客，连波漾去槎。","故乡何处在，更道向天涯。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["江","舟"],"cats":{"抒情":["思乡"],"人生":["战争"],"植物":["柳树"]},"theme_conf":0.719},{"uid":"80c6900a-4be3-44cb-9a58-346a4c8fa498","title":"重忆白菊","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["我怜贞白重寒芳，前后丛生夹小堂。","月朵暮开无绝艳，风茎时动有奇香。","何慙谢雪清才咏，不羡刘梅贵主妆。","更忆幽窗凝一梦，夜来村落有微霜。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":["婉约"],"mood":"相思","mood2":[],"scene":["夜","重阳","花","冬","雪","月"],"cats":{"抒情":["思念"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"090b7792-2942-4f3c-a34d-caccd066c76f","title":"芙蓉楼送辛渐二首 一","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["寒雨连天夜入湖，平明送客楚山孤。","洛阳亲友如相问，一片冰心在玉壶。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","楼"],"cats":{"抒情":["孤独"],"植物":["荷花"]},"theme_conf":0.807},{"uid":"72cbfe88-6a41-4893-b31a-7c10562da7cb","title":"莲叶","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["根是泥中玉，心承露下珠。","在君塘下种，埋没任春蒲。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["荷花","叶子"]},"theme_conf":0.96},{"uid":"e10bd711-4a4e-40e6-85a7-bcec617b61c0","title":"批叶翘谏书纸尾","author":"闽王王继鹏","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["春色曾看紫陌头，乱红飞尽不禁愁。","人情自厌芳华歇，一叶随风落御沟。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["青春"],"植物":["叶子"]},"theme_conf":0.67},{"uid":"4c09aa73-453f-4edb-953d-0f72a14a1e5c","title":"和鲁望白菊","author":"张贲","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["雪彩冰姿号女华，寄身多是地仙家。","有时南国和霜立，几处东篱伴月斜。","谢客琼枝空贮恨，袁郎金钿不成夸。","自知终古清香在，更出梅粧弄晚霞。"],"theme":"咏物","theme2":["羁旅思乡","山水田园","送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["冬","雪","重阳"],"cats":{"抒情":["思乡"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.92},{"uid":"738fc3d5-b2e3-4f00-8a81-496c103cdd58","title":"同吉中孚梦桃源 二","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夜静春梦长，梦逐仙山客。","园林满芝术，鸡犬傍篱栅。","几处花下人，看予笑头白。"],"theme":"山水田园","theme2":["游仙梦幻"],"style":"冲淡","style2":[],"mood":"相思","mood2":["恬淡","欢愉"],"scene":["春","夜","山","园林"],"cats":{"四季":["春天"],"人生":["梦想"],"生活":["乡村"],"植物":["桃花"]},"theme_conf":0.438},{"uid":"8a4edbf7-050f-4176-87cc-a3b461ea1acf","title":"采莲曲","author":"刘方平","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["落日晴江里，荆歌艳楚腰。","采莲从小惯，十五即乘潮。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"植物":["荷花"]},"theme_conf":1.0},{"uid":"56f535d2-27cb-485a-9fc4-1c4f04e2131d","title":"霜菊","author":"席夔","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["时令忽已变，行看被霜菊。","可怜后时秀，当此凛风肃。","淅沥翠枝翻，凄清金蘂馥。","凝姿节堪重，澄艳景非淑。","宁祛青女威，愿盈君子掬。","持来泛罇酒，永以照幽独。"],"theme":"咏物","theme2":["咏物"],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["秋","重阳"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"3f692193-2a80-41b5-b4bf-47176d040535","title":"赋得长亭柳","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["濯濯长亭柳，阴连灞水流。","雨搓金缕细，烟褭翠丝柔。","送客添新恨，听莺忆旧游。","赠行多折取，那得到深秋。"],"theme":"送别","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":["相思"],"scene":["楼","秋"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"植物":["柳树"]},"theme_conf":0.786},{"uid":"cp7755e2bdab1251","title":"解佩环・疏影","author":"彭元逊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["江空不渡，恨蘼芜杜若，零落无数。","远道荒寒，婉娩流年，望望美人迟暮。","风烟雨雪阴晴晚，更何须，春风千树。","尽孤城、落木萧萧，日夜江声流去。","日晏山深闻笛，恐他年流落，与子同赋。","事阔心违，交淡媒劳，蔓草沾衣多露。","汀洲窈窕馀醒寐，遗浮沈沣浦。","有白鸥淡月，微波寄语，逍遥容与。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["江","夜"],"cats":{"抒情":["孤独"],"人物":["女子"],"人生":["时光"],"植物":["梅花"]},"theme_conf":0.5},{"uid":"5cfff02d-2c43-4e77-867a-2d5101a05cc5","title":"闻梨花发赠刘师命","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["桃溪惆怅不能过，红艳纷纷落地多。","闻道郭西千树雪，欲将君去醉如何。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["花","雪"],"cats":{"植物":["梨花"]},"theme_conf":0.88},{"uid":"0879b3a8-9a54-4a34-9746-c2490ef2497e","title":"抱疾谢李吏部赠诃黎勒叶","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["一叶生西徼，赍来上海查。","岁时经水府，根本别天涯。","方士真难见，商胡辄自夸。","此香同异域，看色胜仙家。","茗饮暂调气，梧丸喜伐邪。","幸蒙祛老疾，深愿驻韶华。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["感恩"],"植物":["叶子"]},"theme_conf":0.88},{"uid":"e7686a0a-7362-4c2f-94d2-e18d8640534a","title":"同柳侍郎题侯钊侍郎新昌里","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清源君子居，左右尽图书。","三迳春自足，一飘欢有余。","庭莎成野席，阑药是家蔬。","幽显岂殊迹，昔贤徒病诸。"],"theme":"寄赠酬答","theme2":["咏物","闲适隐逸"],"style":"清新","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":0.86},{"uid":"04e6eb11-0b8c-4b26-ae73-2c7dc13845dc","title":"衞明府寄枇杷叶以诗荅","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["倾筐呈绿叶，重叠色何鲜。","讵是秋风里，犹如晓露前。","仙方当见重，消疾本应便。","全胜甘蕉赠，空投谢氏篇。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.88},{"uid":"913c4360-669c-4e85-ba3d-49dec96abce4","title":"东峰亭各赋一物得阴崖竹","author":"袁邕","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["终岁寒苔色，寂寥幽思深。","朝歌犹夕岚，日永流清阴。","龙钟负烟雪，自有凌云心。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["冬","山","楼","雪"],"cats":{"四季":["冬天"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"0eaf80f5-5cbe-4075-9e50-793cfa66c8f5","title":"宿叶公棋阁","author":"李洞","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["带风棋阁竹相敲，局莹无尘拂树梢。","日到长天征未断，钟来岳顶劫须抛。","挑灯雪客栖寒店，供茗溪僧𦶟废巢。","因悟修身试贪教，不须焚火向三茅。"],"theme":"哲理悟道","theme2":["哲理悟道","羁旅思乡"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"人生":["哲理"],"植物":["叶子"]},"theme_conf":0.72},{"uid":"06798167-53e9-4e1b-b84f-b150edd78eac","title":"夏日梅溪馆寄庞舍人","author":"张祜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["东阳宾礼重，高馆望行期。","埽簟因松叶，𥮾瓜使竹枝。","卷帘闻鸟近，翻枕梦人迟。","坐听津桥说，今营太守碑。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"生活":["写桥"],"植物":["梅花"]},"theme_conf":0.567},{"uid":"f5f8aec8-f9c4-42c3-9231-a2bcaac4bfc6","title":"赠进士李德新接海棠梨","author":"翁洮","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["蜀人犹说种难成，何事江东见接生。","席上若微桃李伴，花中堪作牡丹兄。","高轩日午争浓艳，小径风移旋落英。","一种呈妍今得地，劒峰梨岭谩纵横。"],"theme":"咏物","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"植物":["梨花"]},"theme_conf":0.8},{"uid":"82f109d2-3bc1-447a-a73e-018133ac8929","title":"梅花","author":"后主煜","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["失却烟花主，东君自不知。","清香更何用，犹发去年枝。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"植物":["梅花"]},"theme_conf":1.0},{"uid":"44f744e6-ab04-4af4-82e9-5a28fe9142a2","title":"县中池竹言怀","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["官小志已足，时清免负薪。","卑栖且得地，荣耀不关身。","自爱赏心处，丛篁流水滨。","荷香度高枕，山色满南邻。","道在即为乐，机忘宁厌贫。","却愁丹凤诏，来访漆园人。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["园林"],"cats":{"抒情":["伤感"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"eac61312-dec6-4712-a34a-9a71969af9d5","title":"相和歌辞 采莲曲三首 二","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["荷叶罗裙一色裁，芙蓉向脸两边开。","乱入池中看不见，闻歌始觉有人来。"],"theme":"爱情相思","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"植物":["荷花"]},"theme_conf":0.546},{"uid":"8881d860-4e39-4a12-97f0-a222687988d5","title":"梅花","author":"后主煜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["殷勤移植地，曲槛小阑边。","共约重芳日，还忧不盛妍。","阻风开步障，乘月溉寒泉。","谁料花前后，蛾眉却不全。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["花"],"cats":{"植物":["梅花"]},"theme_conf":0.641},{"uid":"013c9243-bd61-42c8-afd4-9261db7c74e2","title":"题罗浮石","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["清景持芳菊，凉天倚茂松。","名山何必去，此地有群峰。"],"theme":"咏物","theme2":["山水田园"],"style":"绮丽","style2":["幽峭","旷达"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"植物":["梅花"]},"theme_conf":0.53},{"uid":"fcf6c22d-0c07-4dfb-852c-43e7e0a2206b","title":"一叶落","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["烦暑郁未退，凉飙潜已起。","寒温与盛衰，遰相为表里。","萧萧秋林下，一叶忽先委。","勿言微摇落，摇落从此始。"],"theme":"哲理悟道","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","秋"],"cats":{"四季":["夏天","秋天"],"植物":["叶子"]},"theme_conf":0.86},{"uid":"ecfeec5e-3205-401e-bc5d-e9b58efb9031","title":"桃源行送友","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["武陵川径入幽遐，中有鸡犬秦人家，家傍流水多桃花。","桃花两边种来久，流水一通何时有。","垂条落蘂暗春风，夹岸芳菲至山口。","岁岁年年能寂寥，林下青苔日为厚。","时有仙鸟来衔花，曾无世人此携手。","可怜不知若为名，君往从之多所更。","古驿荒桥平路尽，崩湍怪石小溪行。","相见维舟登览处，红堤绿岸宛然成。","多君此去从仙隐，令人晚节悔营营。"],"theme":"送别","theme2":["山水田园"],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["春","花"],"cats":{"抒情":["友情"],"四季":["春天"],"生活":["写桥"],"植物":["桃花"]},"theme_conf":0.408},{"uid":"12029f03-2eaa-44eb-9944-e95e1f178cd8","title":"忆平泉杂咏 忆寒梅","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒塘数树梅，常近腊前开。","雪映缘岩竹，香侵泛水苔。","遥思清景暮，还有野禽来。","谁是攀枝客，兹辰醉始回。"],"theme":"山水田园","theme2":["咏物"],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"抒情":["思念"],"植物":["梅花"]},"theme_conf":0.47},{"uid":"7d43e3ff-6078-4459-a640-27d32c61e8ea","title":"寄题玉霄峰叶涵象尊师所居","author":"皮日休","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青冥向上玉霄峰，元始先生戴紫蓉。","晓案琼文光洞壑，夜坛香气惹杉松。","闲迎仙客来为鹤，静噀灵符去是龙。","子细扪心无偃骨，欲随师去肯相容。"],"theme":"山水田园","theme2":["送别","咏物"],"style":"绮丽","style2":["婉约"],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"植物":["叶子"]},"theme_conf":0.362},{"uid":"a853ea87-07a2-401d-85ab-ff6ad9767bdc","title":"山路见梅感而有作","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["莫言山路僻，还被好风催。","行客凄凉过，村篱冷落开。","晚溪寒水照，晴日数蜂来。","重忆江南酒，何因把一杯。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["山","酒","江南"],"cats":{"抒情":["思念","伤感"],"生活":["乡村"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"4dc66101-9b61-41a9-9e26-965eef8d818d","title":"盛山十二诗 梅谿","author":"韦处厚","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["夹岸凝清素，交枝漾浅沦。","味调方荐实，腊近又先春。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","冬"],"cats":{"四季":["春天"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"420fad84-9a0a-4718-a809-493e7845cd9f","title":"送菊潭王明府","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["业成洙泗客，皓发著儒衣。","一与游人别，仍闻带印归。","林多宛地古，云尽汉山稀。","莫爱浔阳隐，嫌官计亦非。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳","山"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.798},{"uid":"33f9ccb9-1b90-41cf-9ce3-e9394b68c4a3","title":"落叶","author":"孔绍安","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["早秋惊落叶，飘零似客心。","翻飞未肯下，犹言惜故林。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.791},{"uid":"68ae20e0-130a-43ef-b672-8ce0d95abb8b","title":"早梅","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["早梅发高树，逈映楚天碧。","朔吹飘夜香，繁霜滋晓白。","欲为万里赠，杳杳山水隔。","寒英坐销落，何用慰远客。"],"theme":"咏物","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["冬","夜","山"],"cats":{"植物":["梅花"]},"theme_conf":0.365},{"uid":"3f27da66-1e73-4bee-91a4-9de2d9545fc2","title":"相和歌辞 采莲曲","author":"徐彦伯","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["妾家越水边，摇艇入江烟。","既觅同心侣，复采同心莲。","折藕丝能脆，开花叶正圆。","春歌弄明月，归棹落花前。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月"],"cats":{"抒情":["爱情"],"天气":["月亮"],"植物":["荷花"]},"theme_conf":0.713},{"uid":"b98a1f96-5eaa-4d8d-ae39-4a7a38b6eb1e","title":"相和歌辞 采莲曲","author":"李白","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["若耶溪边采莲女，笑隔荷花共人语。","日照新妆水底明，风飘香袖空中举。","岸上谁家游冶郎，三三五五映垂杨。","紫骝嘶入落花去，见此踟蹰空断肠。"],"theme":"山水田园","theme2":["爱情相思","闺情宫怨"],"style":"婉约","style2":["清新"],"mood":"愁怨","mood2":["欢愉"],"scene":["花"],"cats":{"抒情":["伤感","闺怨"],"植物":["荷花"]},"theme_conf":0.424},{"uid":"38869ec6-7ab2-4c91-b1b1-6772267fdf63","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 忆西湖双㶉𫛶","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["双㶉𫛶，锦毛斓斑长比翼，戏绕莲藂回锦臆。","照灼花丛两相得，渔歌惊起飞南北。","缭绕追随不迷惑，云间上下同栖息。","不作惊禽远相忆，东家少妇机中语。","剪断回文泣机杼，徒嗟孔雀衔毛羽。","一去东南别离苦，五里裴回竟何补。"],"theme":"咏物","theme2":["送别","民生疾苦","咏史怀古"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江南","江"],"cats":{"抒情":["离别","思念","怀古"],"山水":["西湖"],"植物":["梅花"]},"theme_conf":0.85},{"uid":"eff8686f-2cb8-4d15-9adb-7439085544ad","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 忆东郭居","author":"李绅","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔余过稚齿，从师昧知奥。","徒怀利物心，不获藏身宝。","曳娄一缝掖，出处劳昏早。","醒醉迷啜哺，衣裳辨颠倒。","忠诚贯白日，直己凭苍昊。","卷舌堕谗谀，惊波息行潦。","衰禽识旧木，疲马知归道。","杨柳长庭柯，兰荃覆阶草。","旌旄光里舍，骑服欢妻嫂。","绿鬓绝新知，苍须稀旧老。","冠緌身忝贵，斋沐心常祷。","笙磬谅谐和，庭除还洒扫。","栖迟还竹巷，物役浸江岛。","倏忽变星霜，悲伤满衷抱。"],"theme":"咏怀抒感","theme2":["羁旅思乡","咏物","讽喻刺世"],"style":"清新","style2":[],"mood":"相思","mood2":["悲怆","欢愉"],"scene":["园林","冬"],"cats":{"抒情":["思念","思乡","伤感"],"植物":["梅花"]},"theme_conf":0.75},{"uid":"25b83882-d6df-4662-9463-fdde2af46b26","title":"东渡早梅一树岁华如雪酣赏成咏","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["暇日留囗事，期云亦囗开。","乡心持岁酒，津下赏山梅。","晚实和商鼎，浓香拂寿杯。","唯应招北客，日日踏青来。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","雪","酒"],"cats":{"抒情":["思乡"],"天气":["写雪"],"节日":["清明节"],"植物":["梅花"]},"theme_conf":0.572},{"uid":"e70730a9-552c-481c-aadc-364713afd410","title":"横吹曲辞 折杨柳","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["垂杨拂绿水，摇艳东风年。","花明玉关雪，叶暖金窗烟。","美人结长恨，相对心凄然。","攀条折春色，远寄龙庭前。"],"theme":"闺情宫怨","theme2":["送别"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人物":["女子"],"植物":["柳树"]},"theme_conf":0.526},{"uid":"cpff779c5996e524","title":"月照梨花・河传","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["霁景风软，烟江春涨。","小阁无人，绣帘半上。","花外姊妹相呼。","约樗蒲。","修蛾忘了章台样。","细思一饷。","感事添惆怅。","胸酥臂玉消减，拟觅双鱼。","倩传书。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"惆怅","mood2":["孤寂"],"scene":["花","月","楼","春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"山水":["江河"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"09fea87e-c0a8-44bc-a18f-307b9f7ee92b","title":"杂曲歌辞 桃花曲","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["魏帝宫人舞凤楼，隋家天子泛龙舟。","君王夜醉春眠[晏]，不觉桃花逐水流。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["花","端午","舟","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"节日":["端午节"],"植物":["桃花"]},"theme_conf":0.9},{"uid":"027bd68f-e4fa-4564-a2cd-f18352352932","title":"梨园弟子","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["白头垂泪话梨园，五十年前雨露恩。","莫问华清今日事，满山红叶鏁宫门。"],"theme":"闺情宫怨","theme2":["咏史怀古"],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["园林"],"cats":{"抒情":["伤感","闺怨","怀古"],"人物":["老师"],"植物":["梨花"]},"theme_conf":0.624},{"uid":"3764f95f-0f5c-4dcd-96f9-2fab476f9018","title":"题杨虢县竹亭","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["夜宿密公室，话馀将昼兴。","遶堦三迳雪，当户一池冰。","家训资风化，心源隐政能。","明朝复何见，莱草古沟堘。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","楼","雪","夜"],"cats":{"植物":["竹子"]},"theme_conf":0.65},{"uid":"91f0030c-0030-4b54-9f67-aa37cf114dfe","title":"送菊潭王明府","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["组绶掩衰颜，辉光里第间。","晚凉经灞水，清昼入商山。","行境逢花发，弹琴见鹤还。","唯应理农后，乡老贺君闲。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["重阳","山"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.497},{"uid":"15a37290-0aef-4c6b-92c9-97cff61aafa6","title":"曲池荷","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["浮香绕曲岸，圆影覆华池。","常恐秋风早，飘零君不知。"],"theme":"咏物","theme2":["山水田园"],"style":"清新","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["园林","夏"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.56},{"uid":"32744451-b4f4-47d1-866c-44b2675377c3","title":"横吹曲辞 折杨柳","author":"翁绶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["紫陌金堤映绮罗，游人处处动离歌。","阴移古戍迷荒草，花带残阳落远波。","台上少年吹白雪，楼中思妇敛青蛾。","殷勤攀折赠行客，此去关山雨雪多。"],"theme":"送别","theme2":["羁旅思乡","边塞征战"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","雪","雨","塞外"],"cats":{"抒情":["思乡"],"植物":["柳树"]},"theme_conf":0.4},{"uid":"d3e37fe7-24cf-41a3-aab4-66398019be30","title":"送柳宜城葬","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["鸣笳已逐春风咽，匹马犹依旧路嘶。","遥望柳家门外树，恐闻黄鸟向人啼。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"3e046bc6-cc22-4226-90f8-5d8793fb343e","title":"和薛秀才寻梅花同饮见赠","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忽惊林下发寒梅，便试花前饮冷杯。","白马走迎诗客去，红筵铺待舞人来。","歌声怨处微微落，酒气熏时旋旋开。","若到岁寒无雨雪，犹应醉得两三回。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["冬","酒","花"],"cats":{"四季":["冬天"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"1f4dfb15-6a50-428f-8ce8-121b853cce12","title":"送柳判官赴振武","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["边庭汉仪重，旌甲似云中。","虏地山川壮，单于鼓角雄。","关寒塞榆落，月白胡天风。","君逐嫖姚将，麒麟有战功。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["塞外","月","园林","山"],"cats":{"人生":["战争"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.65},{"uid":"a5d3f266-dd2f-4608-a407-2218fff81515","title":"竹迳偶然作","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["退朝此休沐，闭户无尘氛。","杖策入幽迳，清风随此君。","琴觞恣偃傲，兰蕙相氛氲。","幽赏方自适，林西烟景曛。"],"theme":"闲适隐逸","theme2":["山水田园"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["酒"],"cats":{"植物":["竹子"]},"theme_conf":0.93},{"uid":"620190f9-ce46-4ac0-979a-2926f377fb5a","title":"和杜录事题红叶","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒山十月旦，霜叶一时新。","似烧非因火，如花不待春。","连行排绛帐，乱落剪红巾。","解驻篮轝看，风前唯两人。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"人物":["老师"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"ed9ff702-9ada-422f-885d-8e4fafb39c87","title":"采莲子二首 二","author":"皇甫松","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["船动湖光滟滟秋，贪看年少信船流。","无端隔水抛莲子，遥被人知半日羞。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["荷花"]},"theme_conf":0.764},{"uid":"d97a60f8-4b5a-4f77-a39a-00c869ff0ff3","title":"小苑春望宫池柳色","author":"张昔","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["小苑春初至，皇衢日更清。","遥分万条柳，回出九重城。","隐映龙池润，参差凤阙明。","影宜宫雪曙，色带禁烟晴。","深浅残阳变，高低晓吹轻。","年光正堪折，欲寄一枝荣。"],"theme":"送别","theme2":["哲理悟道"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"节日":["寒食节"],"植物":["柳树"]},"theme_conf":0.508},{"uid":"bb2b70d6-9985-4b06-a850-5b51f2c98e1b","title":"落叶","author":"王周","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["素律铄欲脆，青女妒复稀。","月冷天风吹，叶叶乾红飞。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋","月"],"cats":{"抒情":["思乡"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"366c7400-a019-4cce-b576-bac90d4566d2","title":"和袭美寄题玉霄峰叶涵象尊师所居","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["天台一万八千丈，师在浮云端掩扉。","永夜祗知星斗大，深秋犹见海山微。","风前几降青毛节，雪后应披白羽衣。","南望烟霞空再拜，欲将飞魄问灵威。"],"theme":"寄赠酬答","theme2":["山水田园","咏物"],"style":"绮丽","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"植物":["叶子"]},"theme_conf":0.92},{"uid":"2ff96bd0-5cde-4fff-aa80-de11819ccd23","title":"相和歌辞 采莲女","author":"阎朝隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["采莲女，采莲舟，春日春江碧水流。","莲衣承玉钏，莲刺罥银钩。","薄暮敛容歌一曲，氛氲香气满汀洲。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"植物":["荷花"]},"theme_conf":1.0},{"uid":"d2782132-3d54-4bf4-8d68-d2b9c2803bda","title":"咏双开莲花","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["菡萏新花晓竝开，浓妆美笑面相隈。","西方采画迦陵鸟，早晚双飞池上来。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"植物":["荷花"]},"theme_conf":1.0},{"uid":"46d56217-7555-4a85-99fd-2ef265de9b8d","title":"初秋莲塘归","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋光净无迹，莲消锦云红。","只有溪上山，还识扬舲翁。","如何白苹花，幽渚笑凉风。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"591954e3-94ae-41f0-a2b1-5dbad55e951f","title":"龙州韦郎中先梦六赤后因打叶子以诗上","author":"李洞","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["红蜡香烟扑画楹，梅花落尽庾楼清。","光辉圆魄衔山冷，彩镂方牙着腕轻。","宝帖牵来狮子镇，金盆引出凤凰倾。","微黄喜兆庄周梦，六赤重新掷印成。"],"theme":"哲理悟道","theme2":["游仙梦幻"],"style":"婉约","style2":["绮丽","清新"],"mood":"相思","mood2":["欢愉"],"scene":["花","楼"],"cats":{"人生":["哲理","梦想"],"植物":["叶子"]},"theme_conf":0.565},{"uid":"86a4b0c2-fd29-4877-ae66-d5ee191930b9","title":"谢韦大夫柳栽","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["本在胡笳曲，今从汉将营。","浓阴方待庇，弱植岂无情。","比雪花应吐，藏乌叶未成。","五株蒙远赐，应使号先生。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["雪"],"cats":{"抒情":["感恩"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"c1ab438f-0521-4b14-8056-9e57eb77a87a","title":"采莲子二首 一","author":"皇甫松","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["菡萏香连十顷陂，小姑贪戏采莲迟。","晚来弄水船头湿，更脱红裙裹鸭儿。"],"theme":"爱情相思","theme2":["闺情宫怨"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["花","舟"],"cats":{"抒情":["闺怨"],"植物":["荷花"]},"theme_conf":0.636},{"uid":"1d70922b-4e1b-4eb5-ae5b-79df44859f57","title":"新竹","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["笋添南堦竹，日日成清閟。","缥节已储霜，黄苞犹揜翠。","出栏抽五六，当户罗三四。","高标陵秋严，贞色夺春媚。","稀生巧补林，并出疑争地。","纵横乍依行，烂熳忽无次。","风枝未飘吹，露粉先涵泪。","何人可携玩，清景空瞪视。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["秋","春"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"植物":["竹子"]},"theme_conf":0.609},{"uid":"afb9c85b-d867-4bda-8c84-516d90b554e0","title":"落叶","author":"孔德绍","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["早秋惊叶落，飘零似客心。","翻飞未肯下，犹言惜故林。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.761},{"uid":"d7806360-7bc2-41cb-b8bf-f889b1c9362e","title":"塞上梅","author":"王建","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["天山路傍一株梅，年年花发黄云下。","昭君已殁汉使回，前后征人惟系马。","日夜风吹满陇头，还随陇水东西流。","此花若近长安路，九衢年少无攀处。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","冬"],"cats":{"生活":["边塞"],"植物":["梅花"]},"theme_conf":0.839},{"uid":"00cc533a-059f-49d8-9812-a43906c52e11","title":"看浑中丞山桃花初有他客不通晚方得入因有戏赠","author":"吕温","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["朝来驻马香街里，风度遥闻语笑声。","无事闭门教日晚，山桃落尽不胜情。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["山","花"],"cats":{"抒情":["思乡"],"植物":["桃花"]},"theme_conf":0.86},{"uid":"c91e2fce-3d9c-42fa-9692-39d502521789","title":"春寻柳先生","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["言是商山老，尘心莫问年。","白髯垂策短，乌帽据梧偏。","酒熟飞巴雨，丹成见海田。","疎云披远水，景动石床前。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":0.65},{"uid":"00522c4a-6d4b-48a8-bc12-cc5dd744feca","title":"横吹曲辞 梅花落","author":"刘方平","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["新岁芳梅树，繁苞四面同。","春风吹渐落，一夜几枝空。","小妇今如此，长城恨不穷。","莫将辽海雪，来比后庭中。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["冬","花"],"cats":{"植物":["梅花"]},"theme_conf":1.0},{"uid":"1b0a3511-24ee-414c-a93f-b561d791f545","title":"题梅妃画真","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["忆昔娇妃在紫宸，铅华不御得天真。","霜绡虽似当时态，争奈娇波不顾人。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"抒情":["思念"],"植物":["梅花"]},"theme_conf":0.828},{"uid":"7cebb127-e2e6-423d-a597-340dc11ecfdf","title":"红叶","author":"唐彦谦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["无处不飘扬，高楼临道旁。","素娥前夕月，青女夜来霜。","宿雨随时润，秋晴著物光。","幽怀长若此，病眼更相妨。","蜀纸裁深色，燕脂落靓粧。","低丛侵小阁，倒影入回塘。","谢朓留霞绮，甘宁弃锦张。","何人休远道，是处有斜阳。","薜荔垂书幌，梧桐坠井床。","晚风生旅馆，寒籁近僧房。","桂绿明淮甸，枫丹照楚乡。","鴈疎临鄠杜，蝉急傍潇湘。","树异桓宣武，园非顾辟疆。","茂陵愁卧客，不自保危肠。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["清新","沉郁"],"mood":"愁怨","mood2":[],"scene":["秋","楼"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.7},{"uid":"8e2f586b-9ef4-4672-af24-723a5ec87773","title":"和令狐舍人酬峰上人题山栏孤竹","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["满院冰姿粉箨残，一茎青翠近帘端。","离丛自欲亲香火，抱节何妨共岁寒。","能让繁声任真籁，解将孤影对芳兰。","范云许访西林寺，枝叶须和彩凤看。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":["旷达"],"mood":"孤寂","mood2":[],"scene":["山","冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"山水":["庐山"],"植物":["竹子"]},"theme_conf":0.381},{"uid":"5819c12f-8c4d-4dea-b268-b080f64b2336","title":"万年厉员外宅残菊","author":"顾非熊","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["才过重阳后，人心已为残。","近霜须苦惜，带蝶更宜看。","色减频经雨，香销恐渐寒。","今朝陶令宅，不醉却应难。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.94},{"uid":"7a4aebc8-e23e-42b7-8ccb-8a40366adcee","title":"隔浦莲","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["隔浦爱红莲，昨日看犹在。","夜来风吹落，只得一回采。","花开虽有明年期，复愁明年还暂时。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["花","夜"],"cats":{"抒情":["伤感"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"ba115d1b-606c-4751-af66-e617b670babd","title":"横吹曲辞 折杨柳","author":"欧阳瑾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["垂柳拂妆台，葳蕤叶半开。","年华枝上见，边思曲中来。","嫩色宜新雨，轻花伴落梅。","朝朝倦攀折，征戍几时回。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["雨"],"cats":{"植物":["柳树"]},"theme_conf":1.0},{"uid":"238e54b0-be71-449d-8184-a084c2769f0a","title":"杂曲歌辞 昔昔盐 垂柳覆金堤","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["新年垂柳色，袅袅对空闺。","不畏芳菲好，自缘离别嗁。","因风飘玉户，向日映金堤。","驿使何时度？还将赠陇西。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"抒情":["离别"],"节日":["春节"],"植物":["柳树"]},"theme_conf":0.607},{"uid":"ea947281-09d2-4141-a645-d41ab8e32f8e","title":"天竺寺七叶堂避暑","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["郁郁复郁郁，伏热何时毕？","行入七叶堂，烦暑随步失。","簷雨稍霏微，窗风正萧瑟。","清宵一觉睡，可以销百疾。"],"theme":"哲理悟道","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"60b400e0-ad92-455c-bd50-e6c2f1cfaf88","title":"杜中丞书院新移小竹","author":"王建","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["此地本无竹，远从山寺移。","经年求养法，隔日记浇时。","嫩绿卷新叶，残黄收故枝。","色轻寒不动，声与静相宜。","爱护出常数，稀稠看自知。","贫来缘未有，客散独行迟。"],"theme":"咏物","theme2":["山水田园","哲理悟道","羁旅思乡"],"style":"清新","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["园林"],"cats":{"抒情":["思乡","孤独"],"植物":["竹子"]},"theme_conf":0.9},{"uid":"e44c5577-e518-4ead-a5c3-1940c86f0c8b","title":"石莲花","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["今逢石上生，本自波中有。","红艳秋风里，谁怜众芳后。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"植物":["荷花"]},"theme_conf":1.0},{"uid":"e00cf508-6def-4daf-8e9b-71fce922a6f9","title":"梨花","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["艳静如笼月，香寒未逐风。","桃花徒照地，终被笑妖红。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["花"],"cats":{"植物":["梨花"]},"theme_conf":1.0},{"uid":"39a18f10-005c-4200-ba56-70b7e35adea4","title":"题叶道士山房","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["水边垂柳赤栏桥，洞里仙人碧玉箫。","近得麻姑音信否，浔阳江上不通潮。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","山"],"cats":{"生活":["写桥"],"植物":["叶子"]},"theme_conf":0.52},{"uid":"f10c2ed6-1350-49fb-83e1-c2b6bcea8a02","title":"早梅","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一树寒梅白玉条，迥临村路傍溪桥。","应缘近水花先发，疑是经春雪未销。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["冬"],"cats":{"生活":["写桥"],"植物":["梅花"]},"theme_conf":0.514},{"uid":"006adf6f-0796-40ae-9143-224e5036cba0","title":"蓝田溪杂咏二十二首 竹间路","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["暗归草堂静，半入花园去。","有时载酒来，不与清风遇。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["酒","园林"],"cats":{"植物":["竹子"]},"theme_conf":0.554},{"uid":"3018b75e-666f-4dcb-9baa-cc5050fd2165","title":"蓝田溪杂咏二十二首 石莲花","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["幽石生芙蓉，百花惭美色。","远笑越溪女，闻芳不可识。"],"theme":"山水田园","theme2":["咏物"],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"植物":["荷花"]},"theme_conf":0.557},{"uid":"51c06f33-6a09-4f9d-94e1-86d39fd6078a","title":"之任武陵寒食日途次松滋渡先寄刘员外禹锡","author":"窦常","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["杏花榆荚晓风前，云际离离上峡船。","江转数程淹驿骑，楚曾三户少人烟。","看春又过清明节，算老重经癸巳年。","幸得柱山当郡舍，在朝长咏卜居篇。"],"theme":"寄赠酬答","theme2":["送别"],"style":"清新","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"节日":["寒食节","清明节"],"植物":["桃花"]},"theme_conf":0.72},{"uid":"71077c12-3f1e-40bc-b453-2fa73f3be4aa","title":"又题洛苑梧叶上","author":"天宝宫人","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一叶题诗出禁城，谁人酬和独含情。","自嗟不及波中叶，荡漾乘春取次行。"],"theme":"咏物","theme2":["送别"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"植物":["叶子"]},"theme_conf":0.617},{"uid":"18575058-f526-4248-a273-164a84618218","title":"杂曲歌辞 昔昔盐 水溢芙蓉沼","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["渌沼春光后，青青草色浓。","绮罗惊翡翠，暗粉妒芙蓉。","云遍窗前见，荷翻镜里逢。","将心托流水，终日渺无从。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"1c1ac9e3-ae77-47b4-a501-ab9ca2eb84bc","title":"和马郎中移白菊见示","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["陶诗只采黄金宝，郢曲新传白雪英。","素色不同篱下发，繁花疑自月中生。","浮杯小摘开云母，带露全移缀水精。","偏称含香五字客，从兹得地始芳荣。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","雪","重阳"],"cats":{"节日":["重阳节"],"动物":["写马"],"植物":["菊花"]},"theme_conf":0.86},{"uid":"1fd7fb7a-8fd1-45bc-9dcb-803c52590d34","title":"横吹曲辞 折杨柳","author":"余延寿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["大道连国门，东西种杨柳。","葳蕤君不见，褭娜垂来久。","缘枝栖暝禽，雄去雌独吟。","余花怨春尽，微月起秋阴。","坐望窗中蝶，起攀枝上叶。","好风吹长条，妸娜何如妾。","妾见柳园新，高楼四五春。","莫吹胡塞曲，愁杀陇头人。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["春","塞外","秋","月","楼"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天","秋天"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.644},{"uid":"e4417fb7-c663-4f78-a4c5-ff279a5a5579","title":"酬令狐相公庭前白菊花谢偶书所怀见寄","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["数丛如雪色，一旦冒霜开。","寒蘂差池落，清香断续来。","思深含别怨，芳谢惜年催。","千里难同赏，看看又早梅。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["花","园林"],"cats":{"抒情":["感恩"],"植物":["菊花"]},"theme_conf":0.9},{"uid":"d720e147-9ffc-44e0-a11a-49198cbce2b7","title":"樱桃花","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["樱桃花，一枝两枝千万朵。","花塼曾立摘花人，窣破罗帬红似火。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"植物":["桃花"]},"theme_conf":0.703},{"uid":"1274d774-d716-4705-8497-c3cdd510a7c0","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 早梅桥","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["早梅花，满枝发。","东风报春春未彻，紫萼迎风玉珠裂。","杨柳未黄莺结舌，委素飘香照新月。","桥边一树伤离别，游荡行人莫攀折。","不竞江南艳阳节，任落东风伴春雪。"],"theme":"送别","theme2":["咏史怀古"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春","冬","花","雪"],"cats":{"抒情":["离别","怀古"],"四季":["春天"],"生活":["写桥"],"植物":["梅花"]},"theme_conf":0.576},{"uid":"e3ea1c9d-0de9-4738-97fb-034154b7b740","title":"题黄花驿","author":"薛逢","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["孤戍迢迢蜀路长，鸟鸣山馆客思乡。","更看绝顶烟霞外，数树岩花照夕阳。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["花","山"],"cats":{"抒情":["思乡","孤独"],"植物":["菊花"]},"theme_conf":0.57},{"uid":"9140947f-72ac-49e2-90f9-42f04f3bc302","title":"幸梨园亭观打毬应制","author":"崔湜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["年光陌上发，香辇禁中游。","草绿鸳鸯殿，花明翡翠楼。","宝杯承露酌，仙管杂风流。","今日陪欢豫，皇恩不可酬。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["楼","酒","园林"],"cats":{"植物":["梨花"]},"theme_conf":0.96},{"uid":"a782bd15-160a-4ffd-803e-35334740fbff","title":"相和歌辞 张静婉采莲曲","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["兰膏坠发红玉春，燕钗拖颈抛盘云。","城西杨柳向娇晚，门前沟水波潾潾。","麒麟公子朝天客，珮马珰珰铛度春陌。","掌中无力舞衣轻，翦断鲛绡破春碧。","抱月飘烟一尺腰，麝脐龙髓怜娇饶。","秋罗拂衣碎光动，露重花多香不销。","㶉𫛶胶胶塘水满，绿萍如粟莲茎短。","一夜西风送雨来，粉痕零落愁红浅。","船头折藕丝暗牵，藕根莲子相留连。","郎心似月月易缺，十五十六清光圆。"],"theme":"爱情相思","theme2":["送别"],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":["愁怨"],"scene":["秋","花","春","月"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"植物":["荷花"]},"theme_conf":0.503},{"uid":"21500334-b2e4-4199-8c2c-cbff940c9b6d","title":"和裴迪登蜀州东亭送客逢早梅相忆见寄","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["东阁官梅动诗兴，还如何逊在扬州。","此时对雪遥相忆，送客逢春可自由。","幸不折来伤岁暮，若为看去乱乡愁。","江边一树垂垂发，朝夕催人自白头。"],"theme":"送别","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["冬","楼"],"cats":{"抒情":["思念","思乡","伤感"],"植物":["梅花"]},"theme_conf":0.401},{"uid":"2036833d-b04f-49fe-b709-3eccd090f147","title":"相和歌辞 采莲曲二首 一","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["虽听采莲曲，讵识采莲心。","漾檝爱花远，回船愁浪深。","烟生极浦色，日落半江阴。","同侣怜波静，看妆堕玉簪。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":["恬淡"],"scene":["舟","江"],"cats":{"抒情":["伤感"],"植物":["荷花"]},"theme_conf":0.657},{"uid":"6b2be4af-0264-4adc-80c4-0691ad752f41","title":"相和歌辞 采莲曲二首 二","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["涔阳女儿花满头，毵毵同泛木兰舟。","春风日暮南湖里，争唱菱歌不肯休。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["舟","春"],"cats":{"四季":["春天"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"da9d7556-8296-4658-8f9f-d05ed47f75b9","title":"有僧言罗浮事因为诗以写之","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["君言罗浮上，容易见九垠。","渐高元气壮，汹涌来翼身。","夜宿最高峰，瞻望浩无邻。","海黑天宇旷，星辰来逼人。","是时当朏魄，阴物恣腾振。","日光吐鲸背，劒影开龙鳞。","倏若万马驰，旌旗耸奫沦。","又如广乐奏，金石含悲辛。","疑其有巨灵，怪物尽来宾。","阴阳迭用事，乃俾夜作晨。","咿喔天鸡鸣，扶桑色昕昕。","赤波千万里，涌出黄金轮。","下视生物息，霏如隙中尘。","醯鸡仰瓮口，亦谓云汉津。","世人信耳目，方寸度大钧。","安知视听外，怪愕不可陈。","悠悠想大方，此乃桮水滨。","知小天地大，安能识其真。"],"theme":"哲理悟道","theme2":["山水田园","边塞征战"],"style":"绮丽","style2":["豪放","幽峭"],"mood":"慷慨","mood2":["悲怆"],"scene":["夜"],"cats":{"抒情":["伤感"],"植物":["梅花"]},"theme_conf":0.409},{"uid":"9a85b1aa-f7e3-46c6-9d47-c032a38ee885","title":"桃源行","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["渔舟何招招，浮在武陵水。","拖纶掷饵信流去，误入桃源行数里。","清源寻尽花绵绵，踏花觅径至洞前。","洞门苍黑烟雾生，暗行数步逢虚明。","俗人毛骨惊仙子，争来致词何至此。","须臾皆破冰雪颜，笑言委曲问人间。","因嗟隐身来种玉，不知人世如风烛。","筵羞石髓劝客餐，灯𦶟松脂留客宿。","鸡声犬声遥相闻，晓色葱茏开五云。","渔人振衣起出户，满庭无路花纷纷。","翻然恐失乡悬处，一息不肯桃源住。","桃花满溪水似镜，尘心如垢洗不去。","仙家一出寻无踪，至今流水山重重。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","雪","舟"],"cats":{"天气":["写雪"],"植物":["桃花"]},"theme_conf":0.664},{"uid":"36e09cb4-4fb7-48be-b6c6-c9bd906d9331","title":"辋川集 竹里馆","author":"王维","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["独坐幽篁里，弹琴复长啸。","深林人不知，明月来相照。"],"theme":"闲适隐逸","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"植物":["竹子"]},"theme_conf":0.86},{"uid":"22362105-f266-4297-b3e9-d54b40adf8f0","title":"上阳红叶","author":"徐凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["洛下三分红叶秋，二分翻作上阳愁。","千声万片御沟上，一片出宫何处流。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"6536e3da-09c7-42c0-814f-2552d0ea55ea","title":"追咏棠梨花十韵","author":"吴融","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蜀地从来胜，棠梨第一花。","更应无软弱，别自有妍华。","不贵绡为雾，难降绮作霞。","移须归紫府，驻合饵丹砂。","密映弹琴宅，深藏卖酒家。","夜宜红蜡照，春称锦筵遮。","连庙魂栖望，飘江字绕巴。","未饶酥点薄，兼妬雪飞斜。","旧赏三年断，新期万里赊。","长安如种得，谁定牡丹夸。"],"theme":"游仙梦幻","theme2":["咏物"],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["花","夜"],"cats":{"植物":["梨花"]},"theme_conf":0.4},{"uid":"284295e3-3fc4-4afb-a38b-d5ae9bccc0b1","title":"奉和谏议酬先辈霜菊","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["紫茎芳艳照西风，秖怕霜华掠断丛。","争奈病夫难强饮，应须速自召车公。"],"theme":"寄赠酬答","theme2":["送别"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["菊花"]},"theme_conf":0.7},{"uid":"8b86f9b3-708e-4939-b35a-5292571f9406","title":"酬柳相公","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["天下如今已太平，相公何事唤狂生。","个身恰似笼中鹤，东望沧溟呌数声。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"植物":["柳树"]},"theme_conf":0.88},{"uid":"7545d07f-17d2-47df-89d1-ed639aeff478","title":"武陵观火诗","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["楚乡祝融分，炎火常为虞。","是时直突烟，发自晨炊徒。","盲风扇其威，白昼曛阳鸟。","操绠不暇汲，循墙还避逾。","怒如列缺光，迅与芬轮俱。","联延掩四远，赫弈成洪𬬻。","汹疑云涛翻，飒若鬼神趋。","当前迎惞𨹮，是物同膏腴。","金乌入梵天，赤龙游玄都。","腾烟透窻户，飞燄生栾栌。","火山摧半空，星雨洒中衢。","瑶坛被髹漆，宝树攒珊瑚。","光县与琴焦，旗亭无酒濡。","市人委百货，邑令遗双凫。","余势下隈隩，长熛烘舳舻。","吹焚照水府，炙浪愁天吴。","灾罢云日晚，心惊视听殊。","高灰辨廪庾，黑土连𬮱阇。","众烬合星罗，游氛铄人肤。","厚地藏宿热，遥林呈骤枯。","火德资生人，庸可一日无。","御之失其道，敲石弥天隅。","晋库走龙劒，吴宫伤燕雏。","五行有沴气，先哲垂𬣙谟。","宋郑同日起，时当贤大夫。","无苛自可乐，弭患非所图。","贤守恤人瘼，临烟驻骊驹。","吊场色惨忸，颜失词劬愉。","下令蠲里布，指期轻市租。","闬垣适未立，苫盖自相娱。","山木行剪伐，江泥宜墐途。","邑臣不必曾，何用征越巫。"],"theme":"民生疾苦","theme2":["山水田园","哲理悟道"],"style":"绮丽","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["江南","鸟"],"cats":{"抒情":["伤感"],"植物":["桃花"]},"theme_conf":0.92},{"uid":"f7b65471-38e0-4be2-b932-87655d3edbfd","title":"和水部张员外宣政衙赐百官樱桃诗","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["汉家旧种明光殿，炎帝还书本草经。","岂似满朝承雨露，共看传赐出青冥。","香随翠笼擎初到，色暎银盘写未停。","食罢自知无所报，空然慙汗仰皇扃。"],"theme":"讽喻刺世","theme2":["山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["夏","雨"],"cats":{"植物":["桃花"]},"theme_conf":0.506},{"uid":"cp6ed8f2981cfc67","title":"霜叶飞","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["断烟离绪。","关心事，斜阳红隐霜树。","半壶秋水荐黄花，香西风雨。","纵玉勒、轻飞迅羽。","凄凉谁吊荒台古。","记醉蹋南屏，彩扇咽、寒蝉倦梦，不知蛮素。","聊对旧节传杯，尘笺蠹管，断阕经岁慵赋。","小蟾斜影转东篱，夜冷残蛩语。","早白发、缘愁万缕。","惊飙从卷乌纱去。","漫细将、茱萸看，但约明年，翠微高处。"],"theme":"节令风俗","theme2":["咏史怀古"],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["重阳节"],"植物":["叶子"]},"theme_conf":0.78},{"uid":"78975868-daef-40f6-89f2-1aa8b5308c55","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 三","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["已愁花落荒岩底，复恨根生乱石间。","几度欲移移不得，天教抛掷在深山。"],"theme":"山水田园","theme2":["咏物"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["山","花","月","冬","夏"],"cats":{"抒情":["伤感","孤独","感恩"],"四季":["夏天","冬天"],"天气":["月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.475},{"uid":"d2d9fa8e-5872-480a-ad45-b1b62af3619a","title":"题洛苑梧叶上","author":"天宝宫人","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["旧宠悲秋扇，新恩寄早春。","聊题一片叶，将寄接流人。"],"theme":"咏物","theme2":["送别"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["秋","春"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"植物":["叶子"]},"theme_conf":0.47},{"uid":"95bf4642-3062-48e0-a1fd-cc8505d63998","title":"将赴湖州留题亭菊","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["陶菊手自种，楚兰心有期。","遥知渡江日，正是撷芳时。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["江","重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.65},{"uid":"72f577cd-8974-4e77-810b-731a0c7d5e2c","title":"隋堤柳","author":"李山甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["曾傍龙舟拂翠华，至今凝恨倚天涯。","但经春色还秋色，不觉杨家是李家。","背日古阴从北朽，逐波疎影向南斜。","年年只有晴风便，遥为雷塘送雪花。"],"theme":"羁旅思乡","theme2":["送别","咏物"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","雪","舟","春","秋"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"节日":["端午节"],"植物":["柳树"]},"theme_conf":0.374},{"uid":"9f32abfa-6459-4020-b79d-5f96a026c945","title":"九月十日雨中过张伯佳期柳镇未至以诗招之","author":"李益","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["柳吴兴近无消息，张长公贫苦寂寥。","唯有角巾沾雨至，手持残菊向西招。"],"theme":"爱情相思","theme2":["咏史怀古"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","月"],"cats":{"抒情":["怀古"],"天气":["写雨","月亮"],"植物":["柳树"]},"theme_conf":0.574},{"uid":"6d8fb7db-36fd-40f1-b120-dc58e0d8b039","title":"相和歌辞 采莲曲","author":"崔国辅","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["玉溆花红发，金塘水碧流。","相逢畏相失，并著采莲舟。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["花","舟"],"cats":{"植物":["荷花"]},"theme_conf":1.0},{"uid":"f1f7c92e-a574-4324-9c60-8b87a2f2a94f","title":"阙下芙蓉","author":"包何","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["一人理国致升平，万物呈祥助圣明。","天上河从阙下过，江南花向殿前生。","庆云垂荫开难落，湛露为珠满不倾。","更对乐悬张宴处，歌工欲奏采莲声。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["江南","江"],"cats":{"植物":["荷花"]},"theme_conf":0.65},{"uid":"bf9b9f11-1a5d-492c-a94f-88b9ed59f3eb","title":"题严氏竹亭","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["子陵栖遁处，堪系野人心。","溪水浸山影，岚烟向竹阴。","忘机看白日，留客醉瑶琴。","爱此多诗兴，归来步步吟。"],"theme":"闲适隐逸","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","山","酒"],"cats":{"植物":["竹子"]},"theme_conf":0.84},{"uid":"57444b76-3bd5-4667-8998-b0888da88a61","title":"送叶秀才","author":"王初","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["快骑璁珑刻玉羁，河梁返照上征衣。","层冰春近蟠龙起，九泽云闲独鹤飞。","行想北山清梦断，重游西洛故人稀。","汉庭狗监深知己，有日前驱负弩归。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["春","冬","山","园林"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"植物":["叶子"]},"theme_conf":0.649},{"uid":"ff9ba6ba-1892-40f7-b02c-2ce2e0e2c8ed","title":"高荷","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["种藕百余根，高荷才四叶。","飐闪碧云扇，团圆青玉叠。","亭亭自擡举，鼎鼎难藏擪。","不学著水荃，一生长怗怗。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.631},{"uid":"e2046d37-f9c4-40ed-a327-e10c26f7de43","title":"酬皇甫郎中对新菊花见忆","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["爱菊高人吟逸韵，悲秋病客感衰怀。","黄花助兴方携酒，红叶添愁正满堦。","居士荤腥今已断，仙郎杯杓为谁排。","媿君相忆东篱下，拟废重阳一日斋。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"沉郁","style2":["悲慨","清新"],"mood":"相思","mood2":[],"scene":["重阳","花"],"cats":{"抒情":["思念","伤感"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.92},{"uid":"2cd54f56-4ee1-4e91-827b-d6874acd09b2","title":"题花叶诗","author":"德宗宫人","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["一入深宫里，无由得见春。","题诗花叶上，寄与接流人。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"植物":["叶子"]},"theme_conf":0.653},{"uid":"cd6c9cda-dade-4038-9adf-fc5b46e2b4b9","title":"和陆鲁望白菊","author":"司马都","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["耻共金英一例开，素芳须待早霜催。","绕篱看见成瑶圃，泛酒须迷傍玉杯。","映水好将苹作伴，犯寒疑与雪为媒。","夫君每尚风流事，应为徐妃致此栽。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["酒","雪","重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"3db0baa7-cb74-422c-b606-17dadb3a97f4","title":"暮秋与裴居晦宴因见采菊花之作","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["菊花低色过重阳，似忆王孙白玉觞。","今日王孙好收采，高天已下两回霜。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","秋"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.72},{"uid":"2d07a19f-fe9d-467d-a06a-a8795cb13783","title":"相和歌辞 采莲曲","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["菱叶萦波荷飐风，荷花深处小船通。","逢郎欲语低头笑，碧玉搔头落水中。"],"theme":"爱情相思","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["舟"],"cats":{"植物":["荷花"]},"theme_conf":0.45},{"uid":"b298777c-4db6-424c-b441-e4051bf7ecc9","title":"春日叶秀才曲江","author":"罗隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["江花江草暖相隈，也向江边把酒杯。","春色恼人遮不得，别愁如疟避还来。","安排贱迹无良策，裨补明时望重才。","一曲吴歌齐拍手，十年尘眼未曾开。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","江","酒"],"cats":{"抒情":["伤感"],"四季":["春天"],"山水":["江河"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"a28d04d1-9f9b-492e-8f1f-2d70542ffa27","title":"酬叶县刘明府避地庐山言怀诒郑录事昆季苟尊师兼见赠之","author":"吴筠","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["明哲良罕遇，遇君輙思齐。","挺生著天爵，自可析人珪。","河洛初沸腾，方期扫虹霓。","时命竟未合，安能亲鼓鼙。","从此罢飞凫，投簪辞割鸡。","驱车适南土，忠孝两不暌。","庐岳镇江介，于焉惬林栖。","入门披彩服，出谷杖红藜。","隐令旧闾里，而今复成跻。","郑公解簪绂，华萼曜松谿。","贤哉苟征君，灭迹为圃畦。","顾已成非薄，忝兹忘筌蹄。","相观对绿樽，逸思凌丹梯。","道泰我长往，时清君勿迷。","王孙且无归，芳草正萋萋。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["山","花"],"cats":{"山水":["庐山"],"天气":["彩虹"],"植物":["叶子"]},"theme_conf":0.96},{"uid":"23ecc4c8-9ab8-4d67-a68c-1d2f0e57f0ff","title":"奉和柳相公中书言怀","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["运筹时所贵，前席礼偏深。","羸驾归贫宅，攲冠出禁林。","凤巢方得地，牛喘最关心。","雅望期三入，东山未可寻。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"植物":["柳树"]},"theme_conf":0.9},{"uid":"7f1258da-f56c-4485-aea5-e405a6ce4997","title":"题桃树","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["小径升堂旧不斜，五株桃树亦从遮。","高秋总𫗪贫人实，来岁还舒满眼花。","帘户每宜通乳燕，儿童莫信打慈鵶。","寡妻群盗非今日，天下车书正一家。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["儿童"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"deb3ec18-ec62-47b5-a65b-448018743e43","title":"梨花下赠刘师命","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["洛阳城外清明节，百花寥落梨花发。","今日相逢瘴海头，共惊烂漫开正月。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["花","清明"],"cats":{"节日":["清明节"],"植物":["梨花"]},"theme_conf":0.86},{"uid":"fc566dcd-4892-4c67-87ad-6f65ff3b4e04","title":"相和歌辞 采莲曲三首 一","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["吴姬越艳楚王妃，争弄莲舟水湿衣。","来时浦口花迎入，采罢江头月送归。"],"theme":"爱情相思","theme2":["送别"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江南","舟","月"],"cats":{"植物":["荷花"]},"theme_conf":0.503},{"uid":"813ba0d9-9978-4a68-b5b1-9cd1e9ee82ff","title":"云阳寺石竹花","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一自幽山别，相逢此寺中。","高低俱出叶，深浅不分丛。","野蝶难争白，庭榴暗让红。","谁怜芳最久，春露到秋风。"],"theme":"哲理悟道","theme2":[],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["花"],"cats":{"植物":["竹子"]},"theme_conf":0.404},{"uid":"b060055f-cb85-4656-8297-035e68b380ed","title":"巽上人以竹闲自采新茶见赠酬之以诗","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["芳丛翳湘竹，零露凝清华。","复此雪山客，晨朝掇灵芽。","蒸烟俯石濑，咫尺凌丹崖。","圆方丽奇色，圭璧无纤瑕。","呼儿爨金鼎，余馥延幽遐。","涤虑发真照，还源荡昏邪。","犹同甘露饭，佛事薰毗耶。","咄此蓬瀛侣，无乃贵流霞。"],"theme":"咏物","theme2":["闲适隐逸"],"style":"清新","style2":["幽峭"],"mood":"恬淡","mood2":[],"scene":["雪"],"cats":{"植物":["竹子"],"食物":["写茶"]},"theme_conf":0.82},{"uid":"e502aa21-de65-4abd-99ab-ba4773dfbf7e","title":"荅李滁州题庭前石竹花见寄","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["殷疑曙霞染，巧类匣刀裁。","不怕南风热，能迎小暑开。","游蜂怜色好，思妇感年催。","览赠添离恨，愁肠日几廻。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["园林","花","夏"],"cats":{"抒情":["伤感"],"四季":["夏天"],"植物":["竹子"]},"theme_conf":0.76},{"uid":"81981192-77b7-407d-ab89-18ebf00d8de4","title":"九月九日上幸慈恩寺登浮图群臣上菊花寿酒","author":"上官昭容","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["帝里重阳节，香园万乘来。","却邪萸入佩，献寿菊传杯。","墖类承天涌，门疑待佛开。","睿词悬日月，长得仰昭回。"],"theme":"题画咏艺","theme2":["节令风俗"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"天气":["太阳","月亮"],"节日":["重阳节"],"植物":["菊花"],"食物":["写酒"]},"theme_conf":0.381},{"uid":"015761cf-2c04-44fa-8974-aafe4fa19be3","title":"詶陈翃郎中冬至携柳郎窦郎归河中旧居见寄","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三旬一休沐，清景满林庐。","南郭群儒从，东床两客居。","烧烟浮雪野，麦陇润冰渠。","班白皆持酒，蓬茅尽有书。","终期买寒渚，同此利蒲鱼。"],"theme":"寄赠酬答","theme2":["送别","羁旅思乡"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["冬"],"cats":{"抒情":["思乡"],"四季":["冬天"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"5753f4b7-f085-4a30-8698-f3ae049f655d","title":"和乐天䜩李周美中丞宅池上赏樱桃花","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["樱桃千万枝，照耀如雪天。","王孙䜩其下，隔水疑神仙。","宿露发清香，初阳动暄妍。","妖姬满髻插，酒客折枝传。","同此赏芳月，几人有华筵。","杯行勿遽辞，好醉逸三年。"],"theme":"咏物","theme2":["应制干谒"],"style":"豪放","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["酒","花"],"cats":{"植物":["桃花"]},"theme_conf":0.72},{"uid":"990fcce5-9eed-4401-b5b4-e72eb0b05d5f","title":"武陵春日","author":"王建","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["寻春何事却悲凉，春到他乡忆故乡。","秦女洞桃欹涧碧，楚王堤柳舞烟黄。","波涛入梦家山远，名利关身客路长。","不似冥心叩尘寂，玉编金轴有仙方。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["冲淡","悲慨"],"mood":"相思","mood2":["悲怆","孤寂"],"scene":["春"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.557},{"uid":"1a7842f2-0253-4acd-9995-f328fd55c532","title":"都城从事萧员外寄海梨花诗尽绮丽至惠然远及","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["珠履行台拥附蝉，外郎高步似神仙。","陈词今见唐风盛，从事遥瞻卫国贤。","掷地好词凌彩笔，浣花春水腻鱼笺。","东山芳意须同赏，子看囊盛几日传。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["花"],"cats":{"植物":["梨花"]},"theme_conf":0.97},{"uid":"cp71965685b8581b","title":"柳梢青","author":"蔡伸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["数声𫛸鴂。","可怜又是，春归时节。","满院东风，海棠铺绣，梨花飘雪。","丁香露泣残枝，算未比、愁肠寸结。","自是休文，多情多感，不干风月。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["春","花","雪"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.65},{"uid":"b10851b9-e6cb-41eb-979a-c897ccaac1df","title":"梅里旅夕","author":"杨凌","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["沧洲东望路，旅櫂怆羁游。","枫浦蝉随岸，沙汀鸥转流。","露天星上月，水国夜生秋。","谁忍持相忆，南归一叶舟。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋","江"],"cats":{"抒情":["思念","思乡"],"四季":["秋天"],"植物":["梅花"]},"theme_conf":0.723},{"uid":"97384a23-7f75-4d43-baee-ac6c4a6c6d14","title":"柳司马至","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有使归三峡，相过问两京。","函关犹出将，渭水更屯兵。","设备邯郸道，和亲逻些城。","幽燕唯鸟去，商洛少人行。","衰谢身何补，萧条病转婴。","霜天到宫阙，恋主寸心明。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["鸟"],"cats":{"动物":["写马"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"029ff16c-6562-4d06-95d9-765045b30c69","title":"新桃行","author":"张籍","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["桃生叶婆娑，枝叶四向多。","高未出墙颠，蒿苋相凌摩。","植之三年余，今年初试花。","秋来已成实，其阴良已嘉。","青蝉不来鸣，安得迅羽过。","常恶牵丝虫，蒙幂成网罗。","顾托戏儿童，勿折吾柔柯。","明年结其实，磊磊充汝家。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["婉约"],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人物":["儿童"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"83057247-91ce-43d8-8aee-2eccfdcc8773","title":"横吹曲辞 折杨柳","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["纤纤折杨柳，持此寄情人。","一枝何足贵，怜是故园春。","迟景那能久，流芳不及新。","更愁征戍客，鬓老边城尘。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春","园林"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.468},{"uid":"0878208a-077c-4a26-9aa1-3b7d6a3cf1fd","title":"早秋宿叶堕所居","author":"罗隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["池荷叶正圆，长历报时殚。","旷野云蒸热，空庭雨始寒。","蝇蚊犹得志，簟席若为安。","浮世知谁是，劳歌共一懽。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","园林"],"cats":{"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.65},{"uid":"ea783731-e342-41f5-b894-a2a72a5dad63","title":"病中辱谏议惠甘菊药苗因以诗赠","author":"姚合","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["萧萧一亩宫，种菊十余丛。","采摘和芳露，封题寄病翁。","熟宜茶鼎里，飡称石瓯中。","香洁将何比，从来味不同。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳","花"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.88},{"uid":"d48cdb59-2492-497b-a8c3-11a3930448bb","title":"罗浮山父与葛篇","author":"李贺","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["依依宜织江雨空，雨中六月兰台风。","博罗老仙时出洞，千岁石床啼鬼工。","蛇毒浓凝洞堂湿，江鱼不食衔沙立。","欲剪箱中一尺天，吴娥莫道吴刀涩。"],"theme":"亲情","theme2":["山水田园"],"style":"幽峭","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["山","雨","江","江南","月"],"cats":{"人物":["父亲"],"植物":["梅花"]},"theme_conf":0.506},{"uid":"d26fcebf-9555-46f1-be3f-d0a554a7f9e0","title":"梨","author":"李峤","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["擅美玄光侧，传芳瀚海中。","凤文疎象郡，花影丽新丰。","色对瑶池紫，甘依大谷红。","若令逢汉主，还冀识张公。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"植物":["梨花"]},"theme_conf":1.0},{"uid":"8ea76149-dd97-4cd4-9564-7595c9df1506","title":"登润州芙蓉楼","author":"崔峒","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["上古人何在，东流水不归。","往来潮有信，朝暮事成非。","烟树临沙静，云帆入海稀。","郡楼多逸兴，良牧谢玄晖。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"抒情":["怀古"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"88d4489c-981b-416d-97bd-d7de86b432d8","title":"九日与敬处士左学士同赋采菊上东山便为首句","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["采菊上东山，山高路非远。","江湖乍辽敻，城郭亦在眼。","昼日市井喧，闰年禾稼晚。","开尊会佳客，长啸临绝𪩘。","戏鹤唳且闲，断云轻不卷。","乡心各万里，醉话时一展。","乔木列遥天，残阳贯平坂。","徒忧征车重，自笑谋虑浅。","却顾郡斋中，寄傲与君同。"],"theme":"节令风俗","theme2":["山水田园","羁旅思乡"],"style":"豪放","style2":[],"mood":"恬淡","mood2":["愁怨","欢愉"],"scene":["重阳","山"],"cats":{"抒情":["思乡"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.88},{"uid":"f6c4737c-b9d3-4cf5-8410-f296cceb839a","title":"赠陶使君求梨","author":"徐铉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昨宵宴罢醉如泥，惟忆张公大谷梨。","白玉花繁曾缀处，黄金色嫩乍成时。","冷侵肺腑醒偏早，香惹衣襟歇倍迟。","今旦中山方酒渴，唯应此物最相宜。"],"theme":"咏物","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"欢愉","mood2":["相思"],"scene":["酒","花"],"cats":{"抒情":["思念"],"植物":["梨花"]},"theme_conf":0.75},{"uid":"823ebceb-6848-442c-918e-5cbfe2a70f93","title":"浔阳三题 东林寺白莲","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东林北塘水，湛湛见底清。","中生白芙蓉，菡萏三百茎。","白日发光彩，清飙散芳馨。","泄香银囊破，泻露玉盘倾。","我慙尘垢眼，见此琼瑶英。","乃知红莲花，虚得清净名。","夏萼敷未歇，秋房结才成。","夜深众僧寝，独起绕池行。","欲收一颗子，寄向长安城。","但恐出山去，人间种不生。"],"theme":"咏物","theme2":[],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["孤独"],"山水":["庐山"],"植物":["荷花"]},"theme_conf":0.94},{"uid":"065b8cb6-8cbd-461e-8ed8-62ee4ba449e8","title":"杂曲歌辞 桃花行 三","author":"李峤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["源水丛花无数开，丹跗红蕚间青梅。","从今结子三千岁，预喜仙游复摘来。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"抒情":["思乡"],"植物":["桃花"]},"theme_conf":0.65},{"uid":"403f95d9-35f0-4a0a-9570-1337546203c6","title":"采芙蓉","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["结伴戏方塘，携手上雕航。","船移分细浪，风散动浮香。","游鸎无定曲，惊凫有乱行。","莲稀钏声断，水广櫂歌长。","栖乌还密树，泛流归建章。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["舟"],"cats":{"植物":["荷花"]},"theme_conf":0.65},{"uid":"acef2d2d-cbcc-441c-8163-e1669a19b202","title":"题梨花睡鸭图","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔年家住太湖西，常过吴兴罨画溪。","水阁筠帘春似海，梨花影里睡凫鹥。","（见《吴兴艺文志补》卷四四）。"],"theme":"题画咏艺","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["花","春","江南"],"cats":{"四季":["春天"],"植物":["梨花"]},"theme_conf":0.762},{"uid":"fddc2755-a080-41e0-a99d-7d9399dd98ff","title":"木芙蓉","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["新开寒露丛，远比水间红。","艳色宁相妬，嘉名偶自同。","采江官渡晚，搴木古祠空。","愿得勤来看，无令便逐风。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"植物":["荷花"]},"theme_conf":0.96},{"uid":"995153fc-153b-4165-8a84-3cbad12232ef","title":"南海使院对菊怀丁卯别墅","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何处曾移菊，溪桥鹤岭东。","篱疎还有艳，园小亦无丛。","日晚秋烟里，星繁晓露中。","影摇金涧水，香染玉潭风。","罢酒慙陶令，题诗答谢公。","朝来数花发，身在尉佗宫。"],"theme":"送别","theme2":["山水田园"],"style":"豪放","style2":["绮丽","清新"],"mood":"惆怅","mood2":[],"scene":["园林","重阳"],"cats":{"抒情":["离别"],"生活":["写桥"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.402},{"uid":"0f0fc2c7-01ca-4d6b-93b9-f41de3efca31","title":"东园玩菊","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["少年昨已去，芳岁今又阑。","如何寂莫意，复此荒凉园。","园中独立久，日澹风露寒。","秋蔬尽芜没，好树亦凋残。","唯有数丛菊，新开篱落间。","携觞聊就酌，为尔一留连。","忆我少小日，易为兴所牵。","见酒无时节，未饮已欣然。","近从年长来，渐觉取乐难。","常恐更衰老，强饮亦无欢。","顾谓尔菊花，后时何独鲜。","诚知不为我，借尔暂开颜。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["沉郁"],"mood":"欢愉","mood2":["孤寂"],"scene":["酒","园林","重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"8fee5db3-d6de-4569-8bf8-58982e99902e","title":"菊","author":"李峤","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉律三秋暮，金精九日开。","荣舒洛媛浦，香泛野人杯。","靃靡寒潭侧，丰茸晓岸隈。","黄花今日晚，无复白衣来。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"b8f8d992-088f-4cdf-bef6-6690f55e6a8f","title":"奉和虢州刘给事使君三堂新题二十一咏 竹迳","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["无尘从不扫，有鸟莫令弹。","若要添风月，应除数百竿。"],"theme":"应制干谒","theme2":["咏物"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["月"],"cats":{"植物":["竹子"]},"theme_conf":0.95},{"uid":"44916888-b8b7-4a9e-95fe-d18888843b29","title":"柳花歌送客往桂阳","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["沧浪渡头柳花发，断续因风飞不绝。","摇烟拂水积翠间，缀雪含霜谁忍攀。","夹岸纷纷送君去，鸣櫂孤寻到何处。","移家深入桂水源，种柳新成花更繁。","定知别后消散尽，却忆今朝伤旅魂。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["花","月","雪"],"cats":{"抒情":["离别","孤独"],"植物":["柳树"]},"theme_conf":0.668},{"uid":"fa2d3278-87d8-4be7-a9be-eaa04c23cd6a","title":"送太仆寺李丞赴都到桃林塞","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["远过桃林塞，休年自昔闻。","曲河随暮草，重阜接闲云。","造父为周御，詹嘉守晋军。","应多怀古思，落叶又纷纷。"],"theme":"送别","theme2":["送别"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外"],"cats":{"抒情":["怀古"],"生活":["边塞"],"植物":["桃花"]},"theme_conf":0.85},{"uid":"05a734dd-b434-428e-ab3f-695ac637d516","title":"伤桃源薛道士","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["坛边松在鹤巢空，白鹿闲行旧径中。","手植红桃千树发，满山无主任春风。"],"theme":"山水田园","theme2":["悼亡挽歌"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","山"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.491},{"uid":"d1d57a82-baf7-4776-854e-b99e5319ae87","title":"在滁苦雨归桃花崦伤亲友略尽","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["废弃忝残生，后来亦先夭。","诗人感风雨，长夜何时晓。","去国宦情无，近乡归梦少。","庇身绝中授，甘静忘外扰。","丽景变重阴，洞山空木表。","灵潮若可通，寄谢西飞鸟。"],"theme":"羁旅思乡","theme2":["悼亡挽歌"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":["恬淡"],"scene":["雨"],"cats":{"抒情":["友情","思乡","伤感","悼亡"],"天气":["写雨"],"植物":["桃花"]},"theme_conf":0.431},{"uid":"34bac317-4e11-40fa-abae-731bfb0e8d9c","title":"横吹曲辞 折杨柳","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉窗朝日映，罗帐春风吹。","拭泪攀杨柳，长条宛地垂。","白花飞历乱，黄鸟思参差。","妾自肝肠断，旁人那得知。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"a3ff9642-7681-4ab7-8cfc-347a97ca7609","title":"山迳柳","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["宛转若游丝，浅深栽绿崦。","年年立春后，即被啼莺占。"],"theme":"咏物","theme2":["咏物","山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":0.95},{"uid":"9b5c9844-6e46-4d8d-8714-bd7c23382376","title":"三日梨园侍宴","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["九重驰道出，三巳禊堂开。","画鹢中流动，青龙上苑来。","野花飘御座，河柳拂天杯。","日晚迎祥处，笙镛下帝台。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["园林"],"cats":{"天气":["太阳"],"植物":["梨花"]},"theme_conf":0.95},{"uid":"6c8d4916-c8ad-46a9-bfcc-778f2b56a17a","title":"寄罗浮山道者二首 二","author":"黄滔","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["有人曾见洞中仙，才到人间便越年。","金鼎药成龙入海，玉函书发鹤归天。","楼开石脉千寻直，山拆鼇鳞一半膻。","谁到月明朝礼处，翠岩深锁荔枝烟。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"植物":["梅花"],"食物":["荔枝"]},"theme_conf":0.8},{"uid":"609cfa44-628d-4344-91bd-ca03998bf52e","title":"冬至宿杨梅馆","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["十一月中长至夜，三千里外远行人。","若为独宿杨梅馆，冷枕单床一病身。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["冬"],"cats":{"抒情":["思乡","孤独"],"四季":["冬天"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"60c32812-bf4c-4e8f-a71e-7fc60d8f0690","title":"罗浮山","author":"张又新","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["江北重峦积翠浓，绮霞遥映碧芙蓉。","不知末后沧溟上，灭却瀛洲第几峰。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山","江"],"cats":{"植物":["梅花"]},"theme_conf":1.0},{"uid":"7343f60d-c51e-44a0-9b6d-30fb63783ab0","title":"竹枝曲","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["帝子苍梧不复归，洞庭叶下荆云飞。","巴人夜唱竹枝后，肠断晓猿声渐稀。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["江","夜","园林"],"cats":{"抒情":["伤感"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"8bfe2432-2fa9-4733-a72a-45030c30a391","title":"竹溪","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["访竹越云崖，即林若溪绝。","宁知修干下，漠漠秋苔洁。","清光溢空曲，茂色临幽澈。","采摘愧芳鲜，奉君岁暮节。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","秋","江南"],"cats":{"四季":["秋天"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"a86232f7-8794-4b8e-8e40-e84b329e6720","title":"寒蜂采菊蕊","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["游飏下晴空，寻芳到菊丛。","带声来蕊上，连影在香中。","去住沾余雾，高低顺过风。","终慙异蝴蝶，不与梦魂通。"],"theme":"哲理悟道","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"植物":["菊花"]},"theme_conf":1.0},{"uid":"badab31e-682c-4658-9a2e-cb2b13e317f0","title":"和裴仆射看樱桃花","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["昨日南园新雨后，樱桃花发旧枝柯。","天明不待人同看，遶树重重履迹多。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["花"],"cats":{"植物":["桃花"]},"theme_conf":0.9},{"uid":"4c57a579-0494-41cf-a174-6472ac4f2e8e","title":"游桃源一百韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["沅江清悠悠，连山郁岑寂。","回流抱绝𪩘，皎镜含虚碧。","昏旦递明媚，烟岚分委积。","香蔓垂绿潭，暴龙照孤碛。","渊明著前志，子骥思远跖。","寂寂无何乡，密尔天地隔。","金行太元岁，渔者偶探赜。","寻花得幽踪，窥洞穿暗隙。","依微闻鸡犬，豁达值阡陌。","居人互将迎，笑语如平昔。","广乐虽交奏，海禽心不怿。","挥手一来归，故溪无处觅。","绵绵五百载，市朝几迁革。","有路在壶中，无人知地脉。","皇家感至道，圣祚自天锡。","金阙传本枝，玉函留宝历。","禁山开秘宇，复户洁灵宅。","蘂检香氛氲，醮坛烟幂幂。","我来尘外躅，莹若朝星析。","崖转对翠屏，水穷留画鹢。","三休俯乔木，千级扳峭壁。","旭日闻撞钟，彩云迎蹑屐。","遂登最高顶，纵目还楚泽。","平湖见草青，远岸连霞赤。","幽寻如梦想，绵思属空阒。","夤缘且忘疲，耽玩近成癖。","清猨伺晓发，瑶草凌寒坼。","祥禽舞葱茏，珠树摇玓𬍛。","羽人顾我笑，劝我税归轭。","霓裳何飘飖，童颜洁白皙。","重岩是藩屏，驯鹿受羁靮。","楼居弥清霄，萝茑成翠帟。","仙翁遗竹杖，王母留桃核。","姹女飞丹砂，青童护金液。","宝气浮鼎耳，神光生劒脊。","虚无天乐来，僁窣鬼兵役。","丹丘肃朝礼，玉札工䌷绎。","枕中淮南方，床下阜乡舄。","明灯坐遥夜，幽籁听淅沥。","因话近世仙，耸然心神惕。","乃言瞿氏子，骨状非凡格。","往事黄先生，群儿多侮剧。","謷然不屑意，元气贮肝膈。","往往游不归，洞中观博弈。","言高未易信，犹复加诃责。","一旦前致辞，自云仙期迫。","言师有道骨，前事常被谪。","如今三山上，名字在真籍。","悠然谢主人，后岁当来觌。","言毕依庭树，如烟去无迹。","观者皆失次，惊追纷络绎。","日暮山径穷，松风自萧槭。","适逢修蛇见，瞋目光激射。","如严三清居，不使恣搜索。","唯余步纲势，八趾在沙砾。","至今东北隅，表以坛上石。","列仙徒有名，世人非目击。","如何庭庑际，白日振飞翮。","洞天岂幽远，得道如咫尺。","一气无死生，三光自迁易。","因思人间世，前路何狭窄。","瞥然此生中，善祝期满百。","大方播群类，秀气肖翕辟。","性静本同和，物牵成阻厄。","是非鬬方寸，荤血昏精魄。","遂令多夭伤，犹喜见斑白。","喧喧车马驰，苒苒桑榆夕。","共安缇绣荣，不悟泥途适。","纷吾本孤贱，世业在逢掖。","九流宗指归，百氏旁捃摭。","公卿偶慰荐，乡曲缪推择。","居安白社贫，至傲玄𫄸辟。","功名希自取，簪组俟扬历。","书府蚤怀铅，射宫曾发的。","起草香生帐，坐曹乌集柏。","赐燕聆箫韶，侍祠阅琮璧。","尝闻履忠信，可以行蛮貊。","自述希古心，忘恃干时画。","巧言忽成锦，苦志徒食蘗。","平地生峰峦，深心有矛戟。","层波一震荡，弱植忽沦溺。","北渚吊灵均，长岑思亭伯。","祸来昧几兆，事去空叹息。","尘累与时深，流年随漏滴。","才能疑木鴈，报施迷夷跖。","楚奏絷钟仪，商歌劳宁戚。","禀生非悬解，对镜方感激。","自从婴网罗，每事问龟策。","王正降雷雨，环玦赐迁斥。","倘伏夷平人，誓将依羽客。","买山构精舍，领徒开讲席。","冀无身外忧，自有闲中益。","道芽期日就，尘虑乃冰释。","且欲遗姓名，安能慕竹帛。","长生尚学致，一溉岂虚掷。","芝术资糇粮，烟霞拂巾帻。","黄石履看堕，洪崖肩可拍。","聊复嗟蜉蝣，何烦哀虺蜴。","青囊既深味，琼葩亦屡摘。","纵无西山资，犹免长戚戚。"],"theme":"游仙梦幻","theme2":["羁旅思乡"],"style":"绮丽","style2":["幽峭","冲淡"],"mood":"孤寂","mood2":["恬淡","欢愉"],"scene":["山","江","夜"],"cats":{"抒情":["思乡","孤独"],"天气":["写云","太阳"],"人物":["老师"],"人生":["时光","战争"],"植物":["桃花"]},"theme_conf":0.87},{"uid":"2d9229ab-880d-442a-bb15-0f3766fdbefa","title":"送叶秀才赴举兼呈吕少监","author":"方干","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["君辞旧里一年期，艺至心身亦自知。","尊尽离人看北斗，月寒惊鹊绕南枝。","书回册市砧应绝，棹出村潭菊未衰。","与尔相逢终不远，昨闻秘监在台墀。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["月","舟"],"cats":{"植物":["叶子"]},"theme_conf":1.0},{"uid":"7ff205d9-e2f9-4721-910c-90213458841a","title":"晚菊","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["少年饮酒时，踊跃见菊花。","今来不复饮，每见恒咨嗟。","伫立摘满手，行行把归家。","此时无与语，弃置奈悲何。"],"theme":"咏物","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["重阳","酒"],"cats":{"抒情":["伤感"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"29611f25-d27c-4485-920f-d9ab1cfc8a18","title":"重阳席上赋白菊","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["满园花菊郁金黄，中有孤丛色似霜。","还似今朝歌酒席，白头翁入少年场。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.9},{"uid":"365cf5e5-97f6-4c86-a2c3-0638591bec07","title":"赋得秋菊有佳色","author":"公乘亿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["陶令篱边菊，秋来色转佳。","翠攒千片叶，金剪一枝花。","蘂逐蜂须乱，英随蝶翅斜。","带香飘绿绮，和酒上乌纱。","散漫摇霜彩，娇妍漏日华。","芳菲彭泽见，更称在谁家。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["菊花"]},"theme_conf":0.721},{"uid":"02e00858-8361-4f48-9e95-d0353a54ab49","title":"赋得临池柳","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["岸曲丝阴聚，波移带影疎。","还将眉里翠，来就镜中舒。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["园林"],"cats":{"植物":["柳树"]},"theme_conf":1.0},{"uid":"2247b3d2-8476-4f8a-be6e-d3f8276751d3","title":"忆杭州梅花因叙旧游寄萧协律","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["三年闲闷在余杭，曾为梅花醉几场。","伍相庙边繁似雪，孤山园里丽如妆。","蹋随游骑心长惜，折赠佳人手亦香。","赏自初开直至落，欢因小饮便成狂。","薛刘相次埋新垅，沈谢双飞出故乡。","歌伴酒徒零散尽，唯残头白老萧郎。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"欢愉","mood2":["相思","孤寂"],"scene":["花","冬","酒"],"cats":{"抒情":["思念","思乡","孤独"],"山水":["西湖"],"人物":["女子"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"50540ff5-7284-49dc-bcf1-73c8171e4bea","title":"竹里径","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["幽径行迹稀，清阴苔色古。","萧萧风欲来，乍似蓬山雨。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","山"],"cats":{"植物":["竹子"]},"theme_conf":1.0},{"uid":"9f496ac0-4e6d-4f42-9c57-0ee55664afdb","title":"咏夭桃","author":"孔绍安","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["结叶还临影，飞香欲徧空。","不意余花落，翻沈露井中。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"植物":["桃花"]},"theme_conf":1.0},{"uid":"70cfbaa0-6ea5-4a6a-a6ac-0e8bbfd8413c","title":"贻华阳柳少府","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["系马乔木间，问人野寺门。","柳侯披衣笑，见我颜色温。","竝坐石下堂，俛视大江奔。","火云洗月露，绝壁上朝暾。","自非晓相访，触热生病根。","南方六七月，出入异中原。","老少多暍死，汗逾水浆飜。","俊才得之子，筋力不辞烦。","指挥当世事，语及戎马存。","涕泪溅我裳，悲气排帝阍。","郁陶抱长策，义仗知者论。","吾衰卧江汉，但媿识玙璠。","文章一小技，于道未为尊。","起予幸斑白，因是托子孙。","俱客古信州，结庐依毁垣。","相去四五里，径微山叶繁。","时危挹佳士，况免军旅喧。","醉从赵女舞，歌鼓秦人盆。","子壮顾我伤，我驩兼泪痕。","余生如过鸟，故里今空邨。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"悲怆","mood2":["慷慨"],"scene":["月"],"cats":{"抒情":["思乡","伤感"],"山水":["长江"],"植物":["柳树"]},"theme_conf":0.708},{"uid":"a6819c5a-cece-4e07-a998-9513c2c2851d","title":"叶落","author":"吴融","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["红影飘来翠影微，一辞林表不知归。","伴愁无色烟犹在，替恨成啼露未晞。","若逐水流应万里，莫因风起便孤飞。","楚郊千树秋声急，日暮纷纷惹客衣。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"50c438e3-3f13-4895-9f90-c59ce043671d","title":"过终南柳处士","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["五老正相寻，围棋到煮金。","石摧丹井闭，月过洞门深。","猨鸟三时下，藤萝十里阴。","绿泉多草气，青壁少花林。","自愧非仙侣，何言见道心。","悠哉宿山口，雷雨夜沈沈。"],"theme":"山水田园","theme2":["咏史怀古","闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["月","雨","夜","山"],"cats":{"抒情":["怀古"],"植物":["柳树"]},"theme_conf":0.401},{"uid":"5dc1daca-91ed-4733-a4b4-b20c3243d375","title":"和韦开州盛山十二首 梅溪","author":"张籍","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["自爱新梅好，行寻一径斜。","不教人扫石，恐损落来花。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","冬"],"cats":{"植物":["梅花"]},"theme_conf":1.0},{"uid":"e75cc2c9-545d-4604-a912-837abba0724e","title":"送叶尊师归处州","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["风驭南行远，长山与夜江。","群祆离分野，五岳拜旌幢。","石髓调金鼎，云浆实玉缸。","㹞㹞吠声晓，洞府有仙厖。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","山","江"],"cats":{"植物":["叶子"]},"theme_conf":1.0},{"uid":"0999303b-6686-4053-8fd7-c69c1a37a46f","title":"白菊三首 二","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["莫惜西风又起来，犹能婀娜傍池台。","不辞暂被霜寒挫，舞袖招香即却回。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","重阳"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.95},{"uid":"c2232345-1eea-47ab-b252-bc20d75b246f","title":"自江州司马授忠州刺史仰荷圣泽聊书鄙诚","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["炎瘴抛身远，泥涂索脚难。","网初鳞拨剌，笼久翅摧残。","雷电颁时令，阳和变岁寒。","遗簪承旧念，剖竹授新官。","乡觉前程近，心随外事宽。","生还应有分，西笑问长安。"],"theme":"应制干谒","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","江"],"cats":{"四季":["夏天"],"动物":["写马"],"植物":["荷花"]},"theme_conf":0.78},{"uid":"0cb1f27f-af8a-4ed5-abd5-22f43cb845eb","title":"奉和虢州刘给事使君三堂新题二十一咏 竹溪","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["蔼蔼溪流慢，梢梢岸筿长。","穿沙碧簳净，落水紫苞香。"],"theme":"山水田园","theme2":["应制干谒","咏物"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"植物":["竹子"]},"theme_conf":0.363},{"uid":"930a9bfb-ee77-4806-b03c-7bf63a9b070e","title":"宋州东登望题武陵驿","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["梁宋人稀鸟自啼，登舻一望倍含凄。","白骨半随河水去，黄云犹傍郡城低。","平陂战地花空落，旧苑春田草未齐。","明主频移虎符守，几时行县向黔黎。"],"theme":"咏史怀古","theme2":["羁旅思乡","咏物"],"style":"悲慨","style2":[],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["春"],"cats":{"抒情":["思乡","怀古"],"四季":["春天"],"人生":["战争"],"植物":["桃花"]},"theme_conf":0.377},{"uid":"7b501b42-fe79-4c87-97bc-7ff610629698","title":"竹窗闻风寄苗发司空曙","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["微风惊暮坐，临牖思悠哉。","开门复动竹，疑是故人来。","时滴枝上露，稍沾堦下苔。","何当一入幌，为拂绿琴埃。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":["孤寂"],"scene":[],"cats":{"抒情":["友情"],"天气":["写风"],"植物":["竹子"]},"theme_conf":0.91},{"uid":"da41166c-15b3-454a-8abb-da16b0661591","title":"病中对石竹花","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["散点空堦下，闲凝细雨中。","那能久相伴，嗟尔𣨼秋风。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"沉郁","style2":["幽峭"],"mood":"恬淡","mood2":[],"scene":["雨","花"],"cats":{"天气":["写雨"],"植物":["竹子"]},"theme_conf":0.524},{"uid":"3d26433c-a673-4094-8c83-cadb1b08412a","title":"登柳州城楼寄漳汀封连四州","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["城上高楼接大荒，海天愁思正茫茫。","惊风乱飐芙蓉水，密雨斜侵薜荔墙。","岭树重遮千里目，江流曲似九廻肠。","共来百越文身地，犹自音书滞一乡。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["楼","江"],"cats":{"抒情":["伤感"],"山水":["江河"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"861ef4ac-6a0f-4307-a083-e0175c488c75","title":"寄王舍人竹楼","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["傲吏身闲笑五侯，西江取竹起高楼。","南风不用蒲葵扇，纱帽闲眠对水鸥。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["楼"],"cats":{"植物":["竹子"]},"theme_conf":0.82},{"uid":"138a236c-ce00-433b-8931-5460b685d243","title":"庭柳","author":"姚系","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["褭褭柳杨枝，当轩杂珮垂。","交阴总共密，分条各自宜。","因依似永久，揽结更伤离。","爱此阳春色，秋风莫遽吹。"],"theme":"咏物","theme2":["送别"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","春","秋"],"cats":{"四季":["春天","秋天"],"植物":["柳树"]},"theme_conf":0.556},{"uid":"ae1575a1-37c9-4f20-8db2-219565b17e43","title":"奉和虢州刘给事使君三堂新题二十一咏 竹洞","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["竹洞何年有，公初斫竹开。","洞门无锁钥，俗客不曾来。"],"theme":"寄赠酬答","theme2":["咏物"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"植物":["竹子"]},"theme_conf":0.88},{"uid":"000e96e4-474a-47b9-a0b1-c16d2816ed0c","title":"送郑丞之罗浮中习业","author":"杨衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["百年泛飘忽，万事系衰荣。","高鸿脱矰缴，达士去簪缨。","始从天目游，复作罗浮行。","云卧石林密，月窥花洞明。","全形在气和，习默凭境清。","夙秘绛囊诀，屡投金简名。","钟管促离觞，烟霞随去程。","何当真府内，重得欵平生。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","月"],"cats":{"植物":["梅花"]},"theme_conf":1.0},{"uid":"70b41da6-9b4d-4392-b0fb-23ef70a1cd78","title":"横吹曲辞 折杨柳","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["倡楼启曙扉，园柳正依依。","鸟鸣知岁隔，条变识春归。","露叶疑啼脸，风花乱舞衣。","攀折聊将寄，军中书信稀。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","楼","园林"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"3b847cf5-16b1-449d-a436-e5995c6433c4","title":"桃源行","author":"王维","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["渔舟逐水爱山春，两岸桃花夹去津。","坐看红树不知远，行尽青溪不见人。","山口潜行始隈隩，山开旷望旋平陆。","遥看一处攒云树，近入千家散花竹。","樵客初传汉姓名，居人未改秦衣服。","居人共住武陵源，还从物外起田园。","月明松下房栊静，日出云中鸡犬喧。","惊闻俗客争来集，竞引还家问都邑。","平明闾巷埽花开，薄暮渔樵乘水入。","初因避地去人间，及至成仙遂不还。","峡里谁知有人事，世中遥望空云山。","不疑灵境难闻见，尘心未尽思乡县。","出洞无论隔山水，辞家终拟长游衍。","自谓经过旧不迷，安知峰壑今来变。","当时只记入山深，青溪几曲到云林。","春来遍是桃花水，不辨仙源何处寻。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["恬淡","孤寂"],"scene":["山"],"cats":{"抒情":["思念","思乡"],"生活":["田野"],"植物":["桃花"]},"theme_conf":0.687},{"uid":"d2b5090e-e6fe-4d4f-9dd6-fe94ff6d4b5c","title":"清明日宴梅道士房","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["林卧愁春尽，开轩览物华。","忽逢青鸟使，邀入赤松家。","丹灶初开火，仙桃正落花。","童颜若可驻，何惜醉流霞。"],"theme":"佛道禅颂","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["清明"],"cats":{"抒情":["伤感"],"节日":["清明节"],"植物":["梅花"]},"theme_conf":0.68},{"uid":"39588d10-121c-4f20-aace-8cd5392070a7","title":"杂曲歌辞 桃花行 四","author":"李峤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["桃花灼灼有光辉，无数成蹊点更飞。","为见芳林含笑待，遂同温树不言归。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"抒情":["思乡"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"02139bd5-8e74-47f9-9ec3-5d13163bb1d0","title":"山中五咏 门柳","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["接影武昌城，分行汉南道。","何事闲门外，空对青山老。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"植物":["柳树"]},"theme_conf":0.543},{"uid":"621d6001-ea93-4bce-adb6-7e085437f15f","title":"秋夜宴王郎中宅赋得露中菊","author":"朱湾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["众芳春竞发，寒菊露偏滋。","受气何曾异，开花独自迟。","晚成犹待赏，欲采未过时。","忍弃东篱下，看随秋草衰。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["秋","重阳","夜"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.682},{"uid":"c8e50d0a-dd19-4fa2-b07e-95882090e9d7","title":"横吹曲辞 折杨柳 一","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["杨柳多短枝，短枝多别离。","赠远累攀折，柔条安得垂。","青春有定节，离别无定时。","但恐人别促，不怨来迟迟。","莫言短枝条，中有长相思。","朱颜与绿杨，幷在别离期。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["离别","思念"],"四季":["春天"],"人生":["青春"],"植物":["柳树"]},"theme_conf":0.753},{"uid":"c5b54cf0-094f-4f32-ae1b-d12cb826cead","title":"杂曲歌辞 蔟拍相府莲","author":"不详","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["莫以今时宠，宁无旧日恩。","看花满眼泪，不共楚王言。","闺烛无人影，罗屏有梦魂。","近来音耗绝，终日望应门。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"孤寂","mood2":["愁怨","相思"],"scene":[],"cats":{"抒情":["伤感","孤独","闺怨"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"304a41de-8c12-45a4-8c82-e5b1885e90d3","title":"梅湾","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["白石盘盘磴，清香树树梅。","山深不吟赏，[辜]负委苍苔。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","山"],"cats":{"植物":["梅花"]},"theme_conf":0.65},{"uid":"25a3e97e-464e-4d18-a912-1c1cf82b175d","title":"寄柳氏","author":"韩翃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["章台柳，章台柳，颜色青青今在否？纵使长条似旧垂，也应攀折他人手。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"植物":["柳树"]},"theme_conf":0.9},{"uid":"ca42b16b-5f16-40f4-8291-34970d922fac","title":"槐叶冷淘","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["青青高槐叶，采掇付中厨。","新面来近市，汁滓宛相俱。","入鼎资过熟，加餐愁欲无。","碧鲜俱照箸，香饭兼苞芦。","经齿冷于雪，劝人投此珠。","愿随金騕褭，走置锦屠苏。","路远思恐泥，兴深终不渝。","献芹则小小，荐藻明区区。","万里露寒殿，开冰清玉壶。","君王纳凉晚，此味亦时须。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["冬","雪"],"cats":{"抒情":["伤感"],"节日":["春节"],"植物":["叶子"]},"theme_conf":0.93},{"uid":"0a96850c-2e49-4c26-879d-a84eae5d8b9e","title":"乐天池馆夏景方妍白莲初开彩舟空泊唯邀缁侣因以戏之","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["池馆今正好，主人何寂然。","白莲方出水，碧树未鸣蝉。","静室宵闻磬，斋厨晚绝烟。","蕃僧如共载，应不是神仙。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["夏","园林","舟"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.82},{"uid":"26cd7866-5191-4331-9520-3c807474298f","title":"棠梨花和李太尉","author":"薛涛","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["吴均蕙圃移嘉木，正及东溪春雨时。","日晚莺啼何所为，浅深红腻压繁枝。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花"],"cats":{"四季":["春天"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"aeb383ee-1d05-4d4c-a662-dcb83fb07284","title":"折菊","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["篱东菊径深，折得自孤吟。","雨中衣半湿，拥鼻自知心。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"f96d878f-bb81-4d27-a814-c89692c7f34b","title":"寻桃花岭潘三姑台","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["桃花岭上觉天低，人上青山马隔溪。","行到三姑学仙处，还有刘阮二郎迷。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","花"],"cats":{"植物":["桃花"]},"theme_conf":1.0},{"uid":"8085e498-9420-4bf8-93ac-c407eca63f03","title":"菊花","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["秋丛绕舍似陶家，遍绕篱边日渐斜。","不是花中偏爱菊，此花开尽更无花。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花","重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"65c4e93c-38d0-4247-a7cc-b19c6ee77743","title":"叶上题诗从苑中流出","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["花落深宫莺亦悲，上阳宫女断肠时。","君恩不闭东流水，叶上题诗寄与谁。"],"theme":"咏物","theme2":["送别","咏史怀古","闺情宫怨"],"style":"悲慨","style2":["婉约"],"mood":"悲怆","mood2":["愁怨"],"scene":[],"cats":{"抒情":["伤感","闺怨","怀古"],"植物":["叶子"]},"theme_conf":0.353},{"uid":"8098529a-3316-4f89-a17f-6e6a2ce52d59","title":"咏桃","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["禁苑春晖丽，花蹊绮树妆。","缀条深浅色，点露参差光。","向日分千笑，迎风共一香。","如何仙岭侧，独秀隐遥芳。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["花","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"8b282727-8bff-446e-8add-a32cfba7671d","title":"和令狐相公玩白菊","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["家家菊尽黄，梁国独如霜。","莹静真琪树，分明对玉堂。","仙人披雪氅，素女不红妆。","粉蝶来难见，麻衣拂更香。","向风摇羽扇，含露滴琼桨。","高艳遮银井，繁枝覆象床。","桂丛慙竝发，梅蘂妬先芳。","一入瑶华咏，从兹播乐章。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"孤寂","mood2":["恬淡","欢愉"],"scene":["雪","重阳","花"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"e951ac7e-488c-4282-a368-a58852fc9f2f","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 忆题惠山寺书堂","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["故山一别光阴改，秋露清风岁月多。","松下壮心年少去，池边衰影老人过。","白云生灭依岩岫，青桂荣枯托薜萝。","惟有此身长是客，又驱旌斾寄烟波。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"清新","style2":[],"mood":"相思","mood2":["慷慨"],"scene":["山"],"cats":{"抒情":["思念","思乡"],"人生":["时光"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"6b1fa7eb-4658-477b-9a58-622ca51385b5","title":"奉和鲁望白菊","author":"皮日休","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["已过重阳半月天，琅华千点照寒烟。","蘂香亦似浮金靥，花样还如镂玉钱。","玩影冯妃堪比艳，链形萧史好争妍。","无由擿向牙箱里，飞上方诸赠列仙。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.9},{"uid":"87600c40-eb40-430b-ac24-351551bbff5b","title":"桃竹杖引赠章留后","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["江心蟠石生桃竹，苍波喷浸尺度足。","斩根削皮如紫玉，江妃水仙惜不得。","梓潼使君开一束，满堂宾客皆叹息。","怜我老病赠两茎，出入爪甲铿有声。","老夫复欲东南征，乘涛鼓枻白帝城。","路幽必为鬼神夺，拔劒或与蛟龙争。","重为告曰，杖兮！杖兮！尔之生也甚正直，慎勿见水踊跃学变化为龙。","使我不得尔之扶持，灭迹于君山湖上之青峰。","噫！风尘澒洞兮豺虎𫜪人，忽失双杖兮吾将曷从。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"惆怅","mood2":[],"scene":["江","山"],"cats":{"植物":["桃花","竹子"]},"theme_conf":0.78},{"uid":"cpe47cfbafe8fffc","title":"月照梨花・河传","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["闷已萦损。","那堪多病。","几曲屏山，伴人昼静。","梁燕催起犹慵。","换熏龙。","新愁旧恨何时尽。","渐凋绿鬓。","小雨知花信。","芳笺寄与何处，绣阁珠栊。","柳阴中。"],"theme":"闺情宫怨","theme2":["送别"],"style":"沉郁","style2":["清新","绮丽"],"mood":"愁怨","mood2":[],"scene":["花","月"],"cats":{"抒情":["伤感","闺怨"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":0.556},{"uid":"17097de0-b154-43fd-9213-91d38353eb8c","title":"杂曲歌辞 桃花行 五","author":"李峤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红蕚竞妍春苑曙，粉茸新向御筵开。","长年愿奉西王宴，近侍慙无东朔才。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["花","春"],"cats":{"抒情":["思乡"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.65},{"uid":"1f28ab03-8388-4a2f-8c4f-3ce47789e221","title":"桃花谿","author":"张旭","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["隐隐飞桥隔野烟，石矶西畔问渔船。","桃花尽日随流水，洞在清谿何处边。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["花"],"cats":{"生活":["写桥"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"f9747c4d-c1e5-4d2c-8bce-10889bba41b4","title":"樱桃曲","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["百舌犹来上苑花，游人独自忆京华。","遥知寝庙尝新后，敕赐樱桃向几家。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["相思"],"scene":[],"cats":{"抒情":["思念","孤独"],"植物":["桃花"]},"theme_conf":0.72},{"uid":"2c4755aa-a07d-4e0a-97b6-afdf906a3f00","title":"天宝初南曹小司寇舅于我太夫人堂下累土为山一匮盈尺以代彼朽木承诸焚香瓷瓯瓯甚安矣旁植慈竹盖兹数峰嵚岑婵娟宛有尘外数致乃不知兴之所至而作是诗","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一匮功盈尺，三峰意出群。","望中疑在野，幽处欲生云。","慈竹春阴覆，香炉晓势分。","惟南将献寿，佳气日氛氲。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["清新"],"mood":"恬淡","mood2":["欢愉"],"scene":["山","中秋"],"cats":{"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"],"食物":["写茶"]},"theme_conf":0.784},{"uid":"d8d4a2e2-28ae-42d1-84ce-306a9b4df039","title":"听唱赤白桃李花","author":"李益","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["赤白桃李花，先皇在时曲。","欲向西宫唱，西宫[宫]树绿。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["花","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"人物":["老师"],"植物":["桃花"]},"theme_conf":0.7},{"uid":"e82ca232-9a56-4a68-acaa-b6e622fe2777","title":"登叶县故城谒沈诸梁庙","author":"李百药","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["总辔临秋原，登城望寒日。","烟霞共掩映，林野俱萧瑟。","楚塞郁不穷，吴山高渐出。","客行殊未已，沐澡期终吉。","椒桂奠芳樽，风云下虚室。","馆宇肃而静，神心康且逸。","伊我非真龙，勿惊疲朽质。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","秋","酒"],"cats":{"抒情":["怀古"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.548},{"uid":"c76247eb-572b-4fa3-8d38-ab33fe686124","title":"江上柳送人","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江柳断肠色，黄丝垂未齐。","人看几重恨，鸟入一枝低。","乡泪正堪落，与君又解携。","相思万里道，春去夕阳西。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约","豪放"],"mood":"愁怨","mood2":["相思"],"scene":["江"],"cats":{"抒情":["思念","伤感"],"山水":["江河"],"植物":["柳树"]},"theme_conf":0.609},{"uid":"a0da6bc2-f1d1-468f-885f-4b515398106b","title":"叹庭前甘菊花","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["檐前甘菊移时晚，青蘂重阳不堪摘。","明日萧条醉尽醒，残花烂熳开何益。","篱边野外多众芳，采撷细琐升中堂。","念兹空长大枝叶，结根失所缠风霜。"],"theme":"咏物","theme2":["节令风俗","民生疾苦","讽喻刺世"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["重阳","花"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.92},{"uid":"210ba813-2a72-42c0-ad24-23bab9962f5a","title":"乞竹","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["乞取池西三两竿，房前栽著病时看。","亦知自惜难判割，犹胜横根引出栏。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"植物":["竹子"]},"theme_conf":1.0},{"uid":"cpf2a280a2cda3d4","title":"月照梨花・河传","author":"黄升","dynasty":"宋","section":"宋词","form":"词","paragraphs":["昼景。","方永。","重帘花影。","好梦犹酣，莺声唤醒。","门外风絮交飞。","送春归。","修蛾画了无人问。","几多别恨。","泪洗残妆粉。","不知郎马何处嘶。","烟草萋迷。","鹧鸪啼。"],"theme":"送别","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["花","月","春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":0.737},{"uid":"cpfefb3d1fd306d5","title":"惜黄花慢","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["送客吴皋。","正试霜夜冷，枫落长桥。","望天不尽，背城渐杳，离亭黯黯，恨水迢迢。","翠香零落红衣老，暮愁锁、残柳眉梢。","念瘦腰。","沈郎旧日，曾系兰桡。","仙人凤咽琼箫。","怅断魂送远，九辨难招。","醉鬟留盼，小窗翦烛，歌云载恨，飞上银霄。","素秋不解随船去，败红趁、一叶寒涛。","梦翠翘。","怨鸿料过南谯。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["秋","花"],"cats":{"抒情":["伤感"],"四季":["秋天"],"生活":["写桥"],"植物":["菊花"]},"theme_conf":0.497},{"uid":"6ecbed64-2409-4f6d-ade3-ccfec85ff92c","title":"梅雨","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["梅实迎时雨，苍茫值晚春。","愁深楚猿夜，梦断越鸡晨。","海雾连南极，江云暗北津。","素衣今尽化，非为帝京尘。"],"theme":"山水田园","theme2":[],"style":"雄浑","style2":[],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["伤感"],"天气":["写雨"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"a42d87f4-4427-4933-90d9-d25d0192f409","title":"元和甲午岁诏书尽征江湘逐客余自武陵赴京宿于都亭有怀续来诸君子","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["雷雨江山起卧龙，武陵樵客蹑仙踪。","十年楚水枫林下，今夜初闻长乐钟。"],"theme":"羁旅思乡","theme2":["山水田园","咏史怀古"],"style":"雄浑","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","怀古"],"山水":["江河"],"植物":["桃花"]},"theme_conf":0.359},{"uid":"cp44b029899def35","title":"疏影","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["苔枝缀玉。","有翠禽小小，枝上同宿。","客里相逢，篱角黄昏，无言自倚修竹。","昭君不惯胡沙远，但暗忆、江南江北。","想佩环、月夜归来，化作此花幽独。","犹记深宫旧事，那人正睡里，飞近蛾绿。","莫似春风，不管盈盈，早与安排金屋。","还教一片随波去，又却怨、玉龙哀曲。","等恁时、重觅幽香，已入小窗横幅。"],"theme":"闺情宫怨","theme2":["山水田园","羁旅思乡"],"style":"绮丽","style2":["婉约","冲淡"],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["夜","江南","花","春","江"],"cats":{"抒情":["思乡","孤独","闺怨"],"四季":["春天"],"植物":["梅花"]},"theme_conf":0.373},{"uid":"b6ccc575-b4f1-4027-b442-811fc39a451d","title":"重忆山居六首 罗浮山","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["龙伯钓鼇时，蓬莱一峰坼。","飞来碧海畔，遂与三山隔。","其下多长溪，潺湲淙乱石。","知君分如此，赠逾荆山璧。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"植物":["梅花"]},"theme_conf":0.572},{"uid":"edca8c83-0380-4c83-af64-371da14c6611","title":"和令狐相公谢太原李侍中寄蒲桃","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["珍果出西域，移根到北方。","昔年随汉使，今日寄梁王。","上相芳缄至，行台绮席张。","鱼鳞含宿润，马乳带残霜。","染指铅粉腻，满喉甘露香。","酝成十日酒，味敌五云桨。","咀嚼停金盏，称嗟响画堂。","慙非末至客，不得一枝尝。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["花","酒"],"cats":{"抒情":["感恩"],"植物":["桃花"]},"theme_conf":0.83},{"uid":"cp0ddc73d1a3910a","title":"竹马子・竹马儿","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["登孤垒荒凉，危亭旷望，静临烟渚。","对雌霓挂雨，雄风拂槛，微收烦暑。","渐觉一叶惊秋，残蝉噪晚，素商时序。","览景想前欢，指神京，非雾非烟深处。","向此成追感，新愁易积，故人难聚。","凭高尽日凝伫。","赢得消魂无语。","极目霁霭霏微，暝鸦零乱，萧索江城暮。","南楼画角，又送残阳去。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["雨","楼","江","秋","夏"],"cats":{"抒情":["友情","伤感","孤独"],"四季":["夏天","秋天"],"动物":["写马"],"植物":["竹子"]},"theme_conf":0.639},{"uid":"b18e52d9-a647-499b-a759-bca7c250393f","title":"与沈杨二舍人合老同食勅赐樱桃玩物感恩因成十四韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["清晓趋丹禁，红缨降紫宸。","驱禽养得熟，和叶摘来新。","圆转盘倾玉，鲜明笼透银。","内园题两字，西掖赐三臣。","荧惑晶华赤，醍醐气味真。","如珠未穿孔，似火不烧人。","杏俗难为对，桃顽讵可伦。","肉嫌卢橘厚，皮笑荔枝皴。","琼液酸甜足，金丸大小匀。","偷须防曼倩，惜莫掷安仁。","手擘才离核，匙抄半是津。","甘为舌上露，暖作腹中春。","已惧长尸禄，仍惊数食珍。","最慙恩未报，饱𫗪不才身。"],"theme":"应制干谒","theme2":["应制干谒"],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"植物":["桃花"],"食物":["荔枝"]},"theme_conf":0.87},{"uid":"b320cb73-b204-4653-b12a-5480f3e0436d","title":"南池荷花","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["蝉噪城沟水，芙蓉忽已繁。","红花迷越艳，芳意过湘沅。","湛露宜清暑，披香正满轩。","朝朝秖自赏，秾李亦何言。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["花","夏"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.517},{"uid":"70585fc1-31c6-4d25-92a0-f8c52cc26957","title":"幸梨园亭观打毬应制","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["今春芳苑游，接武上琼楼。","宛转萦香骑，飘飖拂画毬。","俯身迎未落，回辔逐傍流。","秖为看花鸟，时时误失筹。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["楼","花","园林"],"cats":{"植物":["梨花"]},"theme_conf":0.98},{"uid":"d0788381-649d-4d28-814f-f448f3cfef9a","title":"咏大慈寺斋头鲜于阇梨","author":"陈裕","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["酒肉终朝没阙时，高堂大舍养肥尸。","行婆满院多为妇，童子成行半是儿。","面折掇斋穷措大，笑迎搽粉阿尼师。","一朝若也无常至，剑树刀山不放伊。"],"theme":"哲理悟道","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","园林","山"],"cats":{"人生":["哲理"],"植物":["梨花"]},"theme_conf":0.507},{"uid":"fdefa73b-111d-4b67-ae50-343eb1acce7a","title":"宿黄花馆","author":"杨发","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孤馆萧条槐叶稀，暮蝉声隔水声微。","年年为客路无尽，日日送人身未归。","何处迷鸿离浦月，谁家愁妇捣霜衣。","夜深不卧帘犹卷，数点残萤入户飞。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["花","秋","月","夜"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"],"植物":["菊花"]},"theme_conf":0.506},{"uid":"7cae1dc9-23b8-4611-938d-27d143c3781b","title":"草堂前新开一池养鱼种荷日有幽趣","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["淙淙三峡水，浩浩万顷陂。","未如新塘上，微风动涟漪。","小萍加泛泛，初蒲正离离。","红鲤二三寸，白莲八九枝。","绕水欲成径，护堤方插篱。","已被山中客，呼作白家池。"],"theme":"山水田园","theme2":["闲适隐逸","羁旅思乡"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","夏"],"cats":{"抒情":["思乡"],"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.364},{"uid":"4af04ec2-4fde-4a22-8847-3ee2dcb3f527","title":"微之到通州日授馆未安见尘壁间有数行字读之即仆旧诗其落句云渌水红莲一朵开千花百草无颜色然不知题者何人也微之吟叹不足因缀一章兼录仆诗本同寄省其诗乃十五年前初及第时赠长安妓人阿輭绝句缅思往事杳若梦中怀旧感今因酬长句","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["十五年前似梦游，曾将诗句结风流。","偶助笑歌嘲阿輭，可知传诵到通州。","昔教红袖佳人唱，今遣青衫司马愁。","惆怅又闻题处所，雨淋江馆破墙头。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["花"],"cats":{"人物":["女子"],"人生":["梦想"],"植物":["荷花"]},"theme_conf":0.88},{"uid":"2986234c-d484-47aa-b566-f370e03f2602","title":"白菊杂书四首 三","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["狂才不足自英雄，仆妾驱令学贩舂。","侯印几人封万户，侬家只办买孤峰。"],"theme":"闺情宫怨","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳","山"],"cats":{"抒情":["孤独","闺怨"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"8aa36cc8-fec9-455c-91b7-23fc83cdddb1","title":"和张尹忆东篱菊","author":"李端","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["传书报刘尹，何事忆陶家。","若为篱边菊，山中有此花。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念"],"生活":["乡村"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.82},{"uid":"a9b968e6-ce41-4ed5-bfed-9815700ada3d","title":"白菊","author":"许棠","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["所尚雪霜姿，非关落帽期。","香飘风外别，影到月中疑。","发在林雕后，繁当露冷时。","人间稀有此，自古乃无诗。"],"theme":"送别","theme2":["咏物"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳","雪","月"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.51},{"uid":"2ecf783d-8e3f-4d06-8560-11ba520f5e37","title":"苦竹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["青冥亦自守，輭弱强扶持。","味苦夏虫避，丛卑春鸟疑。","轩墀曾不重，剪伐欲无辞。","幸近幽人屋，霜根结在兹。"],"theme":"民生疾苦","theme2":["咏物"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["夏","春"],"cats":{"四季":["春天","夏天"],"植物":["竹子"]},"theme_conf":0.537},{"uid":"25d13241-414a-4a80-a9aa-7d4c41e8dd64","title":"醉中对红叶","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["临风杪秋树，对酒长年人。","醉貌如霜叶，虽红不是春。"],"theme":"咏物","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"恬淡","mood2":[],"scene":["酒"],"cats":{"四季":["秋天"],"植物":["叶子"],"食物":["写酒"]},"theme_conf":0.82},{"uid":"bd80d8ef-c061-4d52-bb4e-3b364ef260b2","title":"题竹扇赠别","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["湘竹殊堪制，齐纨且未工。","幸亲芳袖日，尤带旧林风。","掩笑歌筵里，传书卧阁中。","竟将为别赠，宁与合欢同。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["楼"],"cats":{"抒情":["离别"],"植物":["竹子"]},"theme_conf":0.699},{"uid":"4b13e5da-48ea-4213-9ede-dd8cec48c7c3","title":"春雪间早梅","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["梅将雪共春，彩艳不相因。","逐吹能争密，排枝巧妬新。","谁令香满座，独使净无尘。","芳意饶呈瑞，寒光助照人。","㻏珑开已徧，点缀坐来频。","那是俱疑似，须知两逼真。","荧煌初乱眼，浩荡忽迷神。","未许琼华比，从将玉树亲。","先期迎献岁，更伴占兹晨。","愿得长辉暎，轻微敢自珍。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","冬","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写雪"],"植物":["梅花"]},"theme_conf":0.95},{"uid":"396cd474-fdac-49f4-9594-f28d013760ac","title":"杂歌谣辞 郑樱桃歌","author":"李颀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["石季龙，僭天禄。","擅雄豪，美人姓郑名樱桃。","樱桃美颜香且泽，娥娥侍寝专宫掖。","后庭卷衣三万人，翠眉清镜不得亲。","官军女骑一千匹，繁花照耀漳河春。","织成花映红纶巾，红旗掣曳卤簿新。","鸣鼙走马接飞鸟，铜[驮]琴瑟随去尘。","凤阳重门如意馆，百尺金梯倚银汉。","自言富贵不可量，女为公主男为王。","赤花双簟珊瑚床，盘龙斗帐琥珀光。","淫昏伪位神所恶，灭石者陵终不误。","邺城苍苍白露微，世事飜覆黄云飞。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["花","春","七夕"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人物":["女子"],"节日":["七夕节"],"植物":["桃花"]},"theme_conf":0.581},{"uid":"b51c9f56-c13f-487f-846f-90ec85b1b7ac","title":"秋朝木芙蓉","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["水面芙蓉秋已衰，繁条到是著花时。","平明露滴垂红脸，似有朝愁暮落悲。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"植物":["荷花"]},"theme_conf":0.95},{"uid":"e1ea09bb-0ca8-4ec2-b9ee-f1299f878734","title":"游后湖赏莲花","author":"嗣主璟","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["蓼花蘸水火不灭，水鸟惊鱼银梭投。","满目荷花千万顷，红碧相杂敷清流。","孙武已斩吴宫女，琉璃池上佳人头。"],"theme":"山水田园","theme2":["咏史怀古","闺情宫怨"],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["花","江"],"cats":{"抒情":["闺怨","怀古"],"人物":["女子"],"植物":["荷花"]},"theme_conf":0.354},{"uid":"3c0f4e33-d046-48ce-bf7f-0aaf1d7f85dc","title":"莲塘驿","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["五月渡淮水，南行遶山陂。","江村远鸡应，竹里闻缲丝。","楚女肌发美，莲塘烟露滋。","菱花覆碧渚，黄鸟双飞时。","渺渺溯洄远，凭风托微词。","斜光动流睇，此意难自持。","女歌本轻艳，客行多怨思。","女萝蒙幽蔓，拟上青桐枝。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["江","月"],"cats":{"抒情":["思乡"],"植物":["荷花"]},"theme_conf":0.579},{"uid":"6a0d85ba-b322-48e5-8dbc-4ce3f6efac5e","title":"题程修己竹障","author":"文宗皇帝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["良工运精思，巧极似有神。","临窗忽覩繁阴合，再盼真假殊未分。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"植物":["竹子"]},"theme_conf":1.0},{"uid":"4ceed844-05e4-493f-a345-b26e9230b080","title":"春日题苗发竹亭","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春亭及策上，郎吏谢玄晖。","闲咏疎篁近，高眠远岫微。","偏宜留野客，暂得解朝衣。","犹忆东溪里，雷云掩故扉。"],"theme":"闲适隐逸","theme2":["咏物","闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["春","楼"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.75},{"uid":"5c373cc0-d72c-4bc8-b39e-c48d0564c86e","title":"酬王维春夜竹亭赠别","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["山月随客来，主人兴不浅。","今宵竹林下，谁觉花源远。","惆怅曙莺啼，孤云还绝𪩘。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["孤寂"],"scene":["春","夜"],"cats":{"抒情":["离别","孤独"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.715},{"uid":"9c2e9bc9-e7a3-459b-8c90-e3aefae8d962","title":"奉和礼部尚书酬杨著作竹亭歌","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["直城朱户相逦连，九逵丹毂声阗阗。","春官自有花源赏，终日南山当目前。","晨摇玉佩趋温室，莫入竹溪疑洞天。","烟销雨过看不足，晴翠鲜飙逗深谷。","独谣一曲泛流霞，闲对千竿连净绿。","萦回疏凿随胜地，石磴岩扉光景异。","虚斋寂寂清籁唫，幽涧纷纷杂英坠。","家承麟趾贵，劒有龙泉赐。","上奉明时事无事，人间方外兴偏多。","能以簪缨狎薜萝，常通内学青莲偈。","更奏新声白雪歌，风入松，云归栋。","鸿飞灭处犹目送，蝶舞闲时梦忽成。","兰台有客叙交情，返照中林曳履声。","直为君恩催造膝，东方辨色谒承明。"],"theme":"寄赠酬答","theme2":["送别","应制干谒"],"style":"清新","style2":["冲淡","绮丽"],"mood":"孤寂","mood2":[],"scene":["楼","山","雪","春"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.8},{"uid":"487805d3-fe67-46d9-912d-29587a2cb1c5","title":"赋得弱柳鸣秋蝉","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["散影玉阶柳，含翠隐鸣蝉。","微形藏叶里，乱响出风前。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["柳树"]},"theme_conf":0.75},{"uid":"4639b839-235b-4c5e-8355-29c2b797fd3c","title":"蓝田溪杂咏二十二首 竹屿","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["幽鸟清涟上，兴来看不足。","新篁压水低，昨夜鸳鸯宿。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["夜"],"cats":{"植物":["竹子"]},"theme_conf":0.479},{"uid":"4e85cb66-dc1d-42b5-9f64-c5a19b4e9fed","title":"赋得残菊","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["阶兰凝曙霜，岸菊照晨光。","露浓晞晚笑，风劲浅残香。","细叶凋轻翠，圆花飞碎黄。","还持今岁色，复结后年芳。"],"theme":"咏物","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["重阳","花"],"cats":{"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"a44cd68d-3b13-4e10-bbf4-035abc5948a4","title":"登楚州城望驿路十余里山村竹林相次交映","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["十里山村道，千峰栎树林。","霜浓竹枝亚，岁晚荻花深。","草市多樵客，渔家足水禽。","幽居虽可羡，无那子牟心。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"生活":["乡村"],"植物":["竹子"]},"theme_conf":0.562},{"uid":"fbc64d79-0672-454c-9255-e48d063e44f6","title":"奉酬皮先辈霜菊见赠","author":"崔璞","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["菊花开晚过秋风，闻道芳香正满丛。","争奈病夫难强饮，应须速自召车公。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","重阳","花"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.9},{"uid":"ea2ee88a-1def-4bda-833b-762f75314d5d","title":"和徐法曹赠崔洛阳斑竹杖以诗见荅","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉干一寻余，苔花锦不如。","劲堪和醉倚，轻好向空书。","采拂稽山曲，因依释氏居。","方辰将独步，岂与此君疎。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["酒","山"],"cats":{"抒情":["孤独"],"植物":["竹子"]},"theme_conf":0.86},{"uid":"c06c6f1d-b88f-4169-8df1-6aea35110ec1","title":"柳边","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["只道梅花发，那知柳亦新。","枝枝总到地，叶叶自开春。","紫燕时飜翼，黄鹂不露身。","汉南应老尽，霸上远愁人。"],"theme":"咏物","theme2":[],"style":"清新","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.78},{"uid":"6685502b-4f24-4ab8-82db-c0b0b155c13e","title":"杂曲歌辞 桃花行 二","author":"李峤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["绮蕚成蹊遍籞芳，红英扑地满筵香。","莫将秋宴传王母，来比春华寿圣皇。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"抒情":["思乡"],"植物":["桃花"]},"theme_conf":0.65},{"uid":"dc20aed7-693e-44db-99c4-ab3d8f5ba7d1","title":"南阳公请东樱桃亭子春䜩","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["万木皆未秀，一林先含春。","此地独何力，我公布深仁。","霜叶日舒卷，风枝远埃尘。","初英濯紫霞，飞雨流清津。","赏异出嚣杂，折芳积懽忻。","文心兹焉重，俗尚安能珍。","碧玉粧粉比，飞琼秾艳均。","鸳鸯七十二，花态并相新。","常恐遗秀志，迨兹广䜩陈。","芳菲争胜引，歌咏竟良辰。","方知戏马会，永谢登龙宾。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["爱情","孤独"],"四季":["春天"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"9d551104-88c1-4011-b24a-2ef8f5e60731","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["如折芙蓉栽旱地，似抛芍药挂高枝。","云埋水隔无人识，唯有南宾太守知。"],"theme":"山水田园","theme2":["咏物"],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["月","冬","夏","花","山"],"cats":{"抒情":["孤独","感恩"],"四季":["夏天","冬天"],"天气":["写云","月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.488},{"uid":"599ee7ca-7e82-4689-b92a-709e51bfce33","title":"寄梅处士","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["扰扰人间是与非，官闲自觉省心机。","六行班里身常下，九列符中事亦稀。","市客惯曾赊贱药，家僮惊见著新衣。","君今独得居山乐，应喜多时未办归。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","山"],"cats":{"抒情":["思乡"],"植物":["梅花"]},"theme_conf":0.96},{"uid":"3979821a-6f07-41ad-9625-f9a4b76d9108","title":"过柳溪道院","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["溪上谁家掩竹扉，鸟啼浑似惜春晖。","日斜深巷无人迹，时见棃花片片飞。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.705},{"uid":"47b3819c-142f-41f0-ab66-dda052360a3b","title":"梅花落","author":"刘方平","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["新岁芳梅树，繁花四面同。","春风吹渐落，一夜几枝空。","少妇今如此，长城恨不穷。","莫将辽海雪，来比后庭中。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["花","冬"],"cats":{"植物":["梅花"]},"theme_conf":1.0},{"uid":"fc114608-fa50-4999-8471-217ef1936685","title":"咏菊","author":"陈叔达","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["霜间开紫蔕，露下发金英。","但令逢采摘，宁辞独晚荣。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"5b2c85ac-3edd-43b7-aa6d-b32c31d01bd0","title":"横吹曲辞 折杨柳","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东城攀柳叶，柳叶低著草。","少壮莫轻年，轻年有人老。","柳发徧川岗，登高堪断肠。","雨烟轻漠漠，何树近君乡？","赠君折杨柳，颜色岂能久。","上客莫沾巾，佳人正回首。","新柳送君行，古柳伤君情。","突兀临荒渡，婆娑出旧营。","隋家两岸尽，陶宅五株平。","日暮偏愁望，春山有鸟声。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["塞外","春","重阳","雨"],"cats":{"抒情":["离别","伤感"],"四季":["春天"],"人物":["女子"],"人生":["青春"],"节日":["重阳节"],"植物":["柳树"]},"theme_conf":0.653},{"uid":"c724c20d-b1a6-4044-af22-5cb1b6aba150","title":"送桃岩成上人归本寺","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["长老归缘起，桃花忆旧岩。","清晨云抱石，深夜月笼杉。","道具门人捧，斋粮谷鸟衔。","余生愿依止，文字欲三缄。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"植物":["桃花"]},"theme_conf":0.557},{"uid":"078f4ec7-6634-44b2-ba3d-f19e322069cb","title":"赠别王炼师往罗浮","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["道俗骈阗留不住，罗浮山上有心期。","却愁仙处人难到，别后音书寄与谁。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["离别","伤感"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"cf912dac-30ed-4f16-a951-ddecd90387ed","title":"郡斋左偏栽竹百余竿炎凉已周青翠不改而为墙垣所蔽有乖爱赏假日命去斋居之东墙由是俯临轩阶低映帷户日夕相对颇有翛然之趣","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["斋居栽竹北窗边，素壁新开映碧鲜。","青蔼近当行药处，绿阴深到卧帷前。","风惊晓叶如闻雨，月过春枝似带烟。","老子忆山心暂缓，退公闲坐对婵娟。"],"theme":"讽喻刺世","theme2":["山水田园"],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":["恬淡","相思"],"scene":["夏","中秋","楼","春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.464},{"uid":"995a9440-f8e3-4a9b-843d-27a34ea8b671","title":"陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["伐竹为桥结构同，褰裳不涉往来通。","天寒白鹤归华表，日落青龙见水中。","顾我老非题柱客，知君才是济川功。","合欢却笑千年事，驱石何时到海东。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["冬","江"],"cats":{"四季":["冬天"],"天气":["太阳"],"生活":["写桥"],"动物":["写马"],"植物":["竹子"]},"theme_conf":0.52},{"uid":"655e4998-5575-47e5-b386-655ace27fc36","title":"梨花","author":"温宪","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["绿阴寒食晚，犹自满空园。","两歇芳菲白，蜂稀寂寞繁。","一枝横野路，数树出江村。","怅望频回首，何人共酒尊。","（《古今图书集成·草木典·梨部》（见宋陈景沂《全芳备祖前集》卷九《梨花》。","「蜂稀」，《全芳备祖》作「蜂声」。","）。"],"theme":"咏物","theme2":["咏物","闲适隐逸"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["花","清明"],"cats":{"抒情":["孤独"],"节日":["寒食节","清明节"],"植物":["梨花"]},"theme_conf":0.86},{"uid":"c637d249-8158-48b9-98ee-a2300c0acbde","title":"赠梅处士","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["早闻声价满京城，头白江湖放旷情。","讲易自传新注义，题诗不著旧官名。","近移马迹山前住，多向牛头寺里行。","天子如今议封禅，应将束帛请先生。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江","冬"],"cats":{"人生":["哲理"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"d058b37e-109f-4f52-be37-f42936cdd75b","title":"琴曲歌辞 绿竹引","author":"宋之问","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["青溪绿潭潭水侧，修竹婵娟同一色。","徒生仙实凤不游，老死空山人讵识。","妙年秉愿逃俗纷，归卧嵩丘弄白云。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"悲怆","mood2":[],"scene":["中秋","山"],"cats":{"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.759},{"uid":"d7955404-a6e6-4a5a-8947-f4ae3f518181","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["上家山，家山依旧好。","昔去松桂长，今来容须老。","上家山，临古道。","高低入云树，芜没连天草。","草色绿萋萋，寒蛩徧草啼。","噪鸦啼树远，行雁帖云齐。","嵒光翻落日，僧火开经室。","竹洞磬声长，松楼钟韵疾。","苔阶泉溜鈌，石甃青莎密。","旧径行处迷，前交坐中失。","叹息整华冠，持杯强自欢。","笑歌怜稚孺，弦竹纵吹弹。","山明溪月上，酒满心聊放。","丱发此淹留，垂丝匪闲旷。","青山不可上，昔事还惆怅。","况复白头人，追怀空望望。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"欢愉","mood2":["惆怅"],"scene":["酒","鸟","月","山"],"cats":{"植物":["梅花"]},"theme_conf":0.392},{"uid":"27b07714-e121-47ce-8c42-5517591d40fc","title":"左掖梨花","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["巧笑解迎人，晴雪香堪惜。","随风蝶影翻，误点朝衣赤。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","雪"],"cats":{"植物":["梨花"]},"theme_conf":1.0},{"uid":"0877cd66-9611-4b76-9fe6-0c6a06e90d48","title":"京兆府新栽莲","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["汚沟贮浊水，水上叶田田。","我来一长叹，知是东溪莲。","下有青泥汚，馨香无复全。","上有红尘扑，颜色不得鲜。","物性犹如此，人事亦宜然。","托根非其所，不如遭弃捐。","昔在溪中日，花叶媚清涟。","今来不得地，顦顇府门前。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["花"],"cats":{"植物":["荷花"]},"theme_conf":0.547},{"uid":"3dabbe1b-2f16-498b-a1e7-be13ab466eca","title":"相和歌辞 湖边采莲妇","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["小姑织白纻，未解将人语。","大嫂采芙蓉，溪湖千万重。","长兄行不在，莫使外人逢。","愿学秋胡妇，真心比古松。"],"theme":"山水田园","theme2":["爱情相思","闺情宫怨"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"抒情":["闺怨"],"植物":["荷花"]},"theme_conf":0.362},{"uid":"56855193-bee7-4ab9-bfc9-29eb35781ea3","title":"左掖梨花","author":"王维","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["闲洒阶边草，轻随箔外风。","黄莺弄不足，衔入未央宫。"],"theme":"咏物","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["花"],"cats":{"植物":["梨花"]},"theme_conf":0.556},{"uid":"12c06865-5953-478a-86df-2ae3d927be97","title":"咏史诗 叶县","author":"胡曾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["叶公丘墓已尘埃，云矗崇墉亦半摧。","借问往年龙见日，几多风雨送将来。"],"theme":"咏史怀古","theme2":["咏物"],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["雨"],"cats":{"抒情":["怀古"],"植物":["叶子"]},"theme_conf":0.457},{"uid":"17483666-0c00-4a97-9824-4ee04d4ca776","title":"蕉叶","author":"徐夤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["绿绮新裁织女机，摆风摇日影离披。","只应青帝行春罢，闲倚东墙卓翠旗。"],"theme":"送别","theme2":["闲适隐逸"],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["七夕","春"],"cats":{"四季":["春天"],"节日":["七夕节"],"植物":["叶子"]},"theme_conf":0.5},{"uid":"2186935c-d029-4ee0-b0b1-4f6341b0323b","title":"野菊","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苦竹园南椒坞边，微香冉冉泪涓涓。","已悲节物同寒雁，忍委芳心与暮蝉。","细路独来当此夕，清尊相伴省他年。","紫云新苑移花处，不取霜栽近御筵。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["花","重阳","秋"],"cats":{"抒情":["伤感","孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.757}];
